    L["Visit a Bank NPC to snapshot bank items."] = "Fale com um banqueiro para salvar os itens do seu banco."
    L["Web Armory Link"] = "Link Web Armory"
    L["Broadcasts your current activity tag (LFG, M+, Raid, PvP, etc.), optional short note, and Clan Sync toggle safely to guildmates using SocialCentral."] = "Transmite sua tag de atividade atual (LFG, M+, Raid, PvP, etc.), nota curta opcional e a opção Sync da Guilda com segurança para colegas usando o SocialCentral."
    L["Centralizes Online Guild Roster (Rank/Zone/Note), Events, Diplomacy stances, Guild Crafters, and Saved Dungeon/Raid Lockouts."] = "Centraliza os Membros Online da Guilda (Cargo/Área/Nota), Eventos, Diplomacia, Profissões de Artesãos e Lockouts salvos."
    L["Click '+ Event Call' to post an event, or use the filter dropdown to inspect 'Calendar' and open the native WoW Calendar."] = "Clique em '+ Chamado' para anunciar um evento ou use o filtro para ver o 'Calendário' e abrir o Calendário oficial do WoW."
    L["Click 'My Status', pick an activity tag, toggle Clan Sync (SCentral1), or trigger a manual Sync."] = "Clique em 'Meu Status', escolha uma tag, ative/desative o Sync da Guilda (SCentral1) ou clique em Sincronizar."
    L["Equipped"] = "Equipados"
    L["Filter: %s"] = "Filtro: %s"
    L["Type Name or Name-Surname and click '+ Add', click the Battle.net globe icon to track a Battle.net friend's entire account, or leave empty while targeting a player."] = "Digite Nome ou Nome-Sobrenome e clique em '+ Adicionar', clique no globo da Battle.net para acompanhar a conta Battle.net inteira de um amigo ou deixe vazio com um jogador selecionado."
    L["Lets you add any character manually (or your current target), pick a Battle.net friend account across all alts, and run an official single /who query outside combat with cooldown >= 5s."] = "Permite adicionar qualquer personagem manualmente (ou o seu alvo atual), escolher uma conta amiga da Battle.net para acompanhar todas as alts e consultar um /who oficial fora de combate com espera mínima de 5s."
    L["Added %s to your Watchlist (tracking all Battle.net / linked alts)."] = "%s adicionado à Watchlist (acompanhando todas as alts da conta Battle.net)."
    L["%s now tracks all Battle.net & linked characters."] = "%s agora acompanha todos os personagens e alts vinculados na Battle.net."
    L["Could not add this Battle.net account right now."] = "Não foi possível adicionar esta conta Battle.net agora."
    L["Added Battle.net friend %s for this session. As soon as they log into WoW on any character, it will stay saved permanently across all their alts."] = "Amigo Battle.net %s adicionado para esta sessão. Assim que ele entrar no WoW com qualquer personagem, ficará salvo permanentemente para todas as alts."
    L["Track all Battle.net / linked alts"] = "Acompanhar todas as alts Battle.net / vinculadas"
    L["Watch Battle.net Account (All Alts)"] = "Vigiar Conta Battle.net (Todas Alts)"
