    L["Select any character or click the map icon beside it to switch worlds, use the sub-tabs below for Alts, Overview, Items, Gear, and Account Matrix, or open Armory / Remove inside the character menu."] = "Escolha qualquer personagem ou clique no ícone de mapa ao lado para trocar de mundo, use as sub-abas abaixo (Alts, Visão Geral, Itens, Equipamento e Conta) ou acesse o Arsenal / Remover no menu do personagem."
