    L["Scan public chat channels for LFG Bulletin"] = "Indexar mensagens LFG de canais públicos no Mural"
    L["Select 'Global Chat LFG' in Group Finder to browse clean server chat requests separated from your Guild and Allies."] = "Selecione 'LFG do Chat Global' no Buscador de Grupos para ver pedidos do servidor separados da sua Guilda e Aliados."
