    L["Click 'Auto-Detect' to pull your live professions, or click 'Publish Note' so all guildmates see your crafts even without SocialCentral."] = "Clique em 'Auto-Detectar' para puxar suas profissões atuais, ou em 'Publicar Nota' para que toda a guilda veja seus ofícios mesmo sem SocialCentral."
    L["Click to edit your professions or publish Guild Note."] = "Clique para editar suas profissões ou publicar na Nota da Guilda."
