    L["Current Character (Auto-Detected)"] = "Personagem Atual (Auto-Detectado)"
    L["Detects your character's current professions and skill ranks automatically, and lets you publish a compact tag to your Guild Public Note."] = "Detecta automaticamente as profissões e níveis de perícia do personagem e permite publicar uma etiqueta compacta na Nota Pública da Guilda."
