    L["Filter by profession or source (Online, Guild, Alts), click any crafter row to whisper or invite, or click '+ Prof' to set a craft note or publish your Guild Public Note."] = "Filtre por profissão ou fonte (Online, Guilda, Alts), clique em um artesão para sussurrar ou convidar, ou clique em '+ Prof' para definir sua nota ou publicar na Nota Pública."
