    L["Switch between 'Locks' and 'Professions' in the selector or click 'Refresh' to request updated raid lockout timers from the server."] = "Alterne entre 'Locks' e 'Profissões' no seletor ou clique em 'Atualizar' para solicitar os tempos de reinício de raides ao servidor."
