    L["Notify when a Blocked or Avoided player appears nearby"] = "Notificar quando um jogador Bloqueado ou marcado Evitar aparecer por perto"
    L["Help: Spotter Blocked Alerts"] = "Ajuda: Alertas de Jogadores Bloqueados"
    L["Alerts and displays on Target Radar whenever someone on your WoW Ignore list or SocialCentral 'Avoid' red flag appears nearby."] = "Alerta e exibe no Radar de Alvos quando alguém da sua lista de Ignorados do WoW ou marcado 'Evitar' no SocialCentral aparecer por perto."
    L["Strangers outside Friends, Watchlist, Guild/Diplomacy, and Blocked lists are never scanned repeatedly."] = "Desconhecidos fora de Amigos, Watchlist, Guilda/Diplomacia e Bloqueados nunca são escaneados repetidamente."
    L["%s has In-Addon Direct Chat disabled. Send via Blizzard chat instead."] = "%s está com o Chat Direto do Addon desativado. Envie pelo chat da Blizzard."
    L["%s signed (%s): %s"] = "%s confirmou (%s): %s"
    L["Addon Message Notifications"] = "Notificações de Mensagens do Addon"
    L["Alerts you with a clickable notification and toast whenever a guildmate schedules a new Raid, Quest, PvP, or Custom Guild Event."] = "Alerta você com notificação clicável e toast flutuante sempre que um membro da guilda agendar uma nova Raide, Missão, PvP ou Evento da Guilda."
    L["Calls Blizzard's FlashClientIcon() so the WoW window highlights on your Windows taskbar if you are alt-tabbed when a DM or invite arrives."] = "Chama Blizzard FlashClientIcon() para piscar a janela do WoW na barra de tarefas do Windows caso receba uma DM ou convite em segundo plano."
    L["Clears automatically as soon as you open and view the unread threads or invitations."] = "É limpo automaticamente assim que você abre e visualiza as conversas ou convites não lidos."
    L["Click to show the pill, drag it anywhere on screen, or reset positions anytime with '/sc resetpos'."] = "Clique para exibir o aviso, arraste para qualquer lugar da tela ou restaure posições a qualquer momento com '/sc resetpos'."
    L["Combine the floating Toast pill, clickable [SC] chat lines, Minimap & Side-Tab unread badges, and taskbar flashing to suit your screen."] = "Combine o aviso Toast flutuante, linhas clicáveis [SC] no chat, contadores no Minimapa e nas Abas Laterais e piscar na barra de tarefas como preferir."
    L["Customize how SocialCentral alerts you when incoming addon-only messages (Direct Messages, Private Rooms, Invites, Alliance Chat, and Guild Alerts) arrive."] = "Personalize como o SocialCentral alerta você quando chegam mensagens exclusivas do addon (Diretas, Salas Privadas, Convites, Aliança e Alertas da Guilda)."
    L["Direct Addon"] = "Direta Addon"
    L["Displays a compact red unread counter badge directly on the corner of the SocialCentral Minimap button alongside the golden ring tint."] = "Exibe um contador vermelho compacto de não lidas diretamente no canto do botão do SocialCentral no Minimapa, junto ao anel dourado."
    L["Displays a compact, draggable 100%-opaque pill beside your Minimap or chat window when a peer messages you via the addon or sends a room invite."] = "Exibe um aviso compacto, arrastável e 100% opaco ao lado do Minimapa ou do chat quando alguém envia mensagem pelo addon ou convite de sala."
    L["Displays unread Direct/Room message counts on the Social (O) side-tab and new Guild Event/LFG alert counts on the Guild (J) side-tab."] = "Exibe a contagem de mensagens Diretas/Salas na aba lateral Social (O) e novos alertas de Eventos/LFG da Guilda na aba lateral da Guilda (J)."
    L["Enable to never miss scheduled guild activities even when outside Dungeon LFG."] = "Ative para nunca perder atividades agendadas da guilda mesmo fora do LFG de Masmorras."
    L["Event Signup"] = "Inscrição em Evento"
