    L["Help: Alliance Chat Sound"] = "Ajuda: Som do Chat da Aliança"
    L["Help: Floating Notification Toast"] = "Ajuda: Toast Flutuante"
    L["Help: Guild Event Alerts"] = "Ajuda: Alertas de Eventos da Guilda"
    L["Help: Guild Signup Alerts"] = "Ajuda: Alertas de Inscrição"
    L["Help: Minimap Unread Counter"] = "Ajuda: Contador no Minimapa"
