    L["Invite to room: %s"] = "Convite para sala: %s"
    L["Left-click the pill to jump directly to the conversation (deferred automatically after combat), hover to pause, or right-click to dismiss."] = "Clique esquerdo no aviso para abrir a conversa (adiado automaticamente após o combate), passe o mouse para pausar ou clique direito para fechar."
    L["Notifies you as the event organizer whenever a guildmate signs up (or declines) on one of your active Guild Events."] = "Notifica você como organizador sempre que um membro da guilda confirmar (ou recusar) presença em um Evento da Guilda criado por você."
    L["Notify me when guildmates sign up to my Events"] = "Notificar quando membros confirmarem presença nos meus Eventos"
    L["Notify when guildmates post a new Guild Event"] = "Notificar quando membros criarem um novo Evento da Guilda"
    L["Only flashes for priority incoming notifications and does nothing while you are already viewing the open thread."] = "Só pisca para notificações prioritárias e não faz nada se você já estiver vendo a conversa aberta."
    L["Open"] = "Abrir"
    L["Play chime on Alliance Chat messages"] = "Tocar sinal sonoro em mensagens do Chat da Aliança"
    L["Plays a distinct audio chime when an authorized Alliance member posts in cross-guild Alliance Chat."] = "Toca um som distinto quando um membro autorizado da Aliança envia mensagem no Chat da Aliança entre guildas."
