    L["Spawns a sample floating Notification Toast pill with sound so you can preview its look and drag it to your preferred screen position."] = "Exibe um Toast de notificação de exemplo com som para testar o visual e arrastá-lo para a posição preferida na tela."
    L["Test Notification Toast"] = "Testar Toast de Notificação"
    L["Triggers only on events you created so your chat stays clutter-free."] = "Dispara apenas nos eventos criados por você para manter seu chat limpo."
    L["Uncheck if you prefer completely plain bookmark tabs without counter pills."] = "Desmarque se preferir as abas laterais limpas sem contadores numéricos."
