    L["Help: Alts Roster & Gold"] = "Ajuda: Lista de Alts e Ouro"
    L["Shows all recorded characters on this WoW Forever realm pool with class, level, gold, rested XP, bag space, pending mail, professions, and active lockouts."] = "Mostra todos os personagens salvos neste grupo de reinos do WoW Forever com classe, nível, ouro, XP descansado, espaço na mochila, correio pendente, profissões e lockouts."
    L["Help: Character Inspector & Actions"] = "Ajuda: Ficha e Ações do Personagem"
    L["Help: Alt Items & Account Search"] = "Ajuda: Itens e Busca na Conta"
    L["Browse equipped items, bags, bank snapshots, and learned recipes in a 2D icon grid or readable list, filtered by category, rarity, world, and faction."] = "Navegue por equipamentos, mochilas, banco e receitas aprendidas em grade 2D ou lista legível, filtrando por categoria, raridade, mundo e facção."
    L["Type to search, click the bag icon to filter source/category/rarity (including Recipes), click the people icon to switch single-alt vs all-alts & world/faction scope, Shift+Click to link, Ctrl+Click to preview, or Right-Click for actions."] = "Digite para buscar, clique no ícone de mochila para filtrar origem/categoria/raridade (incluindo Receitas), clique no ícone de pessoas para alternar entre um alt ou todos os alts e mundo/facção, Shift+Clique para linkar, Ctrl+Clique para provar ou botão direito para ações."
    L["Help: Equipped Gear (2D)"] = "Ajuda: Equipamentos (2D)"
    L["Shows all 19 equipment slots in a lightweight 2D overview with average iLvl, durability, and missing enchant checks."] = "Mostra todos os 19 espaços de equipamento em visão 2D leve, com iLvl médio, durabilidade e verificação de encantamentos faltando."
    L["Hover any slot for the full tooltip, Shift+Click to link in chat, Ctrl+Click to preview in Dressing Room, or Right-Click to search across all your alts."] = "Passe o mouse em qualquer espaço para ver o tooltip completo, Shift+Clique para colar no chat, Ctrl+Clique para provar no Provador ou botão direito para buscar em todos os alts."
    L["+ Room"] = "+ Sala"
    L["Open a 1-on-1 conversation with a friend, guildmate, target, or character name."] = "Abrir conversa 1-para-1 com um amigo, colega de guilda, alvo ou nome."
    L["Manage Conversations"] = "Gerenciar Conversas"
    L["Mark all conversations read, open Personal Notes, or clear/delete the active conversation."] = "Marcar todas como lidas, abrir Notas Pessoais ou limpar/apagar a conversa atual."
    L["Mark All Read"] = "Marcar Todas Lidas"
    L["Clear Active Chat"] = "Limpar Conversa Atual"
    L["Conversation Actions"] = "Ações da Conversa"
    L["Pin, mark unread, copy, clear history, or delete this conversation."] = "Fixar, marcar como não lida, copiar, limpar histórico ou apagar esta conversa."
    L["Type a name to filter online friends, Battle.net, or guildmates — or click a player below:"] = "Digite um nome ou clique em um amigo Battle.net, do WoW ou da guilda abaixo:"
    L["Start"] = "Iniciar"
    L["Help: New 1-on-1 Chat"] = "Ajuda: Nova Conversa 1-para-1"
    L["Starts a 1-on-1 conversation with any Battle.net friend, WoW friend, guildmate, target, or typed character name."] = "Inicia uma conversa 1-para-1 com qualquer amigo Battle.net, amigo do WoW, colega de guilda, alvo selecionado ou nome digitado."
    L["Click anyone in the online list to open chat immediately, click '+ Target' to fill your current target, or type a name and click 'Start'."] = "Clique em alguém da lista online para abrir o chat na hora, clique em '+ Alvo' para preencher seu alvo atual ou digite o nome e clique em 'Iniciar'."
    L["Alert only for Dungeon calls (exclude raids/PvP)"] = "Alertar apenas para Masmorras (excluir raides/PvP)"
    L["Allied Clans can only be set for guilds of your own faction."] = "Guildas Aliadas só podem ser definidas para guildas da sua própria facção."
    L["Automatically displays tracked Watchlist players on Target Radar and measures distance when selected."] = "Exibe automaticamente os jogadores monitorados da Watchlist no Radar de Alvos e mede a distância quando selecionados."
    L["Check Watchlist character"] = "Verificar personagem da Watchlist"
    L["Check after placing Target Radar where you want it on screen."] = "Marque depois de posicionar o Radar de Alvos onde desejar na tela."
    L["Check to show the button. Left-click opens SocialCentral, Right-click opens quick actions, Drag moves it."] = "Marque para exibir o botão. Clique esq.: abre o SocialCentral, Botão direito: menu rápido, Arrastar: move o botão."
    L["Click any character to inspect it, hover the bottom gold bar for a per-alt breakdown, or right-click a row to copy Armory URL or remove old alts."] = "Clique em qualquer personagem para inspecioná-lo, passe o cursor na barra de ouro abaixo para ver por alt ou clique com o botão direito para copiar o Arsenal ou remover alts antigos."
    L["Comma-separated dungeon or level keywords (e.g. 'BRD, Strat, tank') so Clan Dungeon Alerts only fire on matching requests."] = "Palavras-chave de masmorra ou função separadas por vírgula (ex.: 'BRD, Strat, tank') para filtrar alertas LFG."
    L["Configure below to enable/disable alerts, restrict to Dungeons only, or filter specific dungeon keywords."] = "Configure abaixo para ativar/desativar avisos, limitar a Masmorras ou filtrar palavras-chave."
    L["Detected %dd ago"] = "Detectado há %dd"
    L["Displays WoW Friends and Battle.net Friends on Target Radar and shows range when selected."] = "Mostra Amigos do WoW e Amigos Battle.net no Radar de Alvos e exibe a distância quando selecionados."
    L["Displays active dungeon and raid lockouts, boss progress, reset countdowns, and your active Group Finder status across this character and your Alts."] = "Mostra vínculos ativos de masmorra e raide, chefes derrotados, tempo de reinício e status do Localizador neste personagem e seus Alts."
    L["Enabled by default: mirrors WoW Guild, Officer, Party, Raid, and Instance messages inside Conversations."] = "Ativado por padrão: espelha mensagens de Guilda, Oficial, Grupo, Raide e Instância dentro de Conversas."
    L["Event Title (e.g. Blackrock Depths, Molten Core):"] = "Título do Evento (ex.: Abismo Rocha Negra, Núcleo Derretido):"
    L["Filters Clan LFG alerts to Dungeon calls, ignoring Raids and PvP announcements."] = "Filtra alertas LFG da Guilda para chamados de Masmorra, ignorando anúncios de Raide e PvP."
    L["Fishing"] = "Pesca"
    L["Help: Lock Target Radar HUD"] = "Ajuda: Travar Posição do Radar de Alvos"
    L["Lock Target Radar HUD position"] = "Travar posição do Radar de Alvos"
    L["Mail Reminder: Unclaimed mail detected earlier on: %s."] = "Lembrete de Correio: correspondência pendente detectada anteriormente em: %s."
    L["Manually opens the Target Radar HUD to test target tracking and range display."] = "Abre manualmente o HUD do Radar de Alvos para testar rastreamento e exibição de distância."
    L["Mirror WoW Guild / Party / Raid channels inside Conversations"] = "Espelhar canais Guilda / Grupo / Raide do WoW em Conversas"
    L["Mode: LFG (Join)"] = "Modo: LFG (Entrar)"
    L["Mode: LFM (Recruit)"] = "Modo: LFM (Recrutar)"
    L["Notifies you in chat (with optional sound and clickable Whisper/Clan links) whenever a guildmate looks for a Dungeon group."] = "Notifica no chat (com som opcional e links clicáveis de Sussurro/Guilda) sempre que um colega procurar grupo de Masmorra."
    L["Only the creator or authorized guild officers can remove this event."] = "Apenas o criador ou oficiais autorizados da guilda podem remover este evento."
    L["Prevents accidental dragging of the floating Target Radar pill during gameplay."] = "Impede arrastar acidentalmente a barra flutuante do Radar de Alvos durante o jogo."
    L["Radar active! Monitors nearby tracked players and measures distance when targeted."] = "Radar ativo! Monitora jogadores rastreados próximos e mede a distância quando selecionados como alvo."
    L["Right-click to inspect, copy Armory URL, or remove."] = "Clique direito para inspecionar, copiar link do Arsenal ou remover."
    L["Select any character or use the filter dropdown ('All', 'Equipped', 'Bags', 'Bank'), search by item name, or access Web Armory / Remove actions inside the character menu."] = "Selecione qualquer personagem, use o filtro ('Tudo', 'Equipado', 'Mochilas', 'Banco'), busque por nome de item ou acesse Arsenal Web / Remover no menu."
    L["The Target Radar tracks nearby Watchlist, Friend, Ally, Same-Clan, and Enemy players via sightlines and nameplates. When a tracked player is detected, a compact HUD appears with click-to-target and range tracking when selected."] = "O Radar de Alvos detecta jogadores da Watchlist, Amigos, Aliados, Guilda e Inimigos próximos via linha de visão e placas de nome. Ao detectar um jogador rastreado, uma barra compacta aparece com clique para mirar e medição de distância ao selecionar o alvo."
    L["Type Name or Name-Surname and click '+ Add' (or leave empty while targeting a player)."] = "Digite Nome ou Nome-Sobrenome e clique em '+ Adicionar' (ou deixe vazio com um jogador selecionado)."
    L["Uncheck if you want Conversations to focus only on Direct Whispers, Battle.net, Alliance Chat, and Private Rooms."] = "Desmarque se quiser que Conversas exiba apenas Sussurros Diretos, Battle.net, Chat da Aliança e Salas Privadas."
    L["When unchecked or when the other player lacks SocialCentral, sending falls back cleanly to official WoW Whisper or Battle.net chat."] = "Quando desmarcado ou quando o outro jogador não usa o SocialCentral, o envio recorre ao sussurro oficial do WoW ou Battle.net."
    L["e.g. Progression Guild · Dungeons & Raids nightly"] = "ex.: Guilda de Progressão · Masmorras e Raides todas as noites"
    L["Level 60 Dungeons (BRD / Strat / Scholo / DM)"] = "Masmorras Nv 60 (BRD / Strat / Scholo / DM)"
    L["Leveling Dungeons"] = "Masmorras de Nivelamento"
    L["Elite & Attunement Quests"] = "Missões Elite e Sintonização"
    L["Addon Update Alerts"] = "Alertas de Atualização do Addon"
    L["Attaches the Guild Hub, Events, Professions, and Diplomacy side-tab inside Blizzard's Guild / Communities (J) window."] = "Anexa a aba lateral do Hub da Guilda, Eventos, Profissões e Diplomacia dentro da janela da Guilda / Comunidades (J)."
    L["Attaches the My Alts side-tab (gold vault, equipped items, bags, and bank search) inside Blizzard's Character (C) window."] = "Anexa a aba lateral Meus Alts (ouro total, itens equipados, mochilas e busca no banco) dentro da janela de Personagem (C)."
    L["Attaches the SocialCentral Watchlist, Social, and Nearby side-tab to Blizzard's Friends/Social (O) window."] = "Anexa a aba lateral de Watchlist, Social e Por Perto do SocialCentral na janela de Amigos/Social (O)."
    L["Automatically hide Guild features when this character has no guild"] = "Ocultar recursos de Guilda automaticamente quando este personagem não tiver guilda"
    L["Automatically hides Guild (J) integration, Hub Guild tab, Alliance chat mirrors, and Guild shortcuts whenever you play a character with no guild."] = "Oculta automaticamente a integração na Guilda (J), a aba Guilda no Hub, espelhos da Aliança e atalhos de Guilda sempre que você jogar com um personagem sem guilda."
    L["Character & Alts (C)"] = "Personagem & Alts (C)"
