    L["Configure alerts for Guild LFG calls, scheduled Events, World Buff announcements, Scout shares, and Group Avoid safety warnings."] = "Configure alertas de chamados LFG da Guilda, Eventos agendados, avisos de World Buffs, compartilhamento de Batedor e avisos de Evitar em Grupo."
