    L["Keep enabled so guildless characters stay clutter-free without manually turning Guild options off and on."] = "Mantenha marcado para que personagens sem guilda fiquem limpos sem precisar ligar e desligar opções manualmente."
    L["Keep opt-in sync off for 100% local play, or turn on to share guild status/LFG/events with teammates."] = "Deixe a sincronização desmarcada para uso 100% local, ou ative para compartilhar status, LFG e eventos com sua guilda."
    L["Notifications"] = "Notificações"
    L["Notifications muted for %s."] = "Notificações silenciadas para %s."
    L["Notify on shared Guild Scout sighting alerts"] = "Avisar sobre alertas de Batedor compartilhados pela Guilda"
    L["Only %s"] = "Só %s"
    L["Opt-in guild communication, Group Finder automation-free helpers, and peer version checks."] = "Comunicação opcional da guilda, facilitadores manuais no Localizador e verificação passiva de versão."
    L["Radar & Map"] = "Radar & Mapa"
    L["Screen Target Radar"] = "Radar de Alvos na Tela"
    L["Shows chat, sound, and popup alerts when a guildmate shares an Enemy Scout sighting."] = "Exibe alertas no chat, som e popup quando um colega da guilda compartilha um avistamento de Batedor inimigo."
    L["Silence this notification"] = "Silenciar esta notificação"
    L["Social & Friends (O)"] = "Social & Amigos (O)"
    L["Stop checking or alerting when peers run a newer addon version."] = "Para de verificar ou avisar quando outros jogadores tiverem uma versão mais nova do addon."
    L["Stop notifying on Scout sightings shared by guildmates."] = "Para de avisar sobre avistamentos de Batedor compartilhados por colegas da guilda."
    L["Stop notifying when Classic World Buffs are announced or synced."] = "Para de avisar quando World Buffs Clássicos forem anunciados ou sincronizados."
    L["Stop notifying when Watchlist players come online."] = "Para de avisar quando jogadores da sua Watchlist ficarem online."
    L["Stop notifying when friends connect to WoW."] = "Para de avisar quando amigos se conectarem ao WoW."
    L["Stop notifying when friends disconnect from WoW."] = "Para de avisar quando amigos desconectarem do WoW."
    L["Stop notifying when guildmates look for a Dungeon / Group."] = "Para de avisar quando colegas da guilda procurarem Masmorra ou Grupo."
    L["Stop notifying when guildmates post new Guild Events."] = "Para de avisar quando colegas postarem novos Eventos da Guilda."
    L["Stop notifying when guildmates sign up to your Events."] = "Para de avisar quando colegas se inscreverem nos seus Eventos."
    L["Stop showing 15m and 5m reminders before Guild & Calendar events."] = "Para de exibir lembretes de 15 min e 5 min antes de eventos da Guilda e Calendário."
    L["Stop showing floating popups for addon messages (conversations still appear in Chat)."] = "Para de exibir popups flutuantes de mensagens do addon (você continua vendo tudo em Conversas e no chat)."
    L["Stop warning when an Avoid-flagged player enters your group."] = "Para de avisar quando um jogador marcado como Evitar entrar no seu grupo ou raide."
    L["Stop warning when an active World Buff has under 5m left."] = "Para de avisar quando um World Buff ativo estiver com menos de 5 minutos restantes."
    L["Summary & Windows"] = "Resumo & Janelas"
    L["Uncheck to keep Blizzard's Friends (O) window 100% vanilla while still keeping '/sc hub' available."] = "Desmarque para deixar a janela de Amigos (O) 100% original mantendo o '/sc hub' disponível."
    L["Uncheck to mute shared Guild Scout alerts without disabling your own Target Radar."] = "Desmarque para silenciar alertas de Batedor da Guilda sem desligar o seu próprio Radar de Alvos."
    L["Watchlist Online Alerts"] = "Alertas Watchlist Online"
    L["World Buff Expiry Warning"] = "Aviso de Expiração de World Buff"
    L["Your character is not currently in a guild."] = "Seu personagem atual não está em nenhuma guilda."
    L["This module is disabled in Settings."] = "Este módulo está desativado nas Configurações."
    L["disabled. Re-enable anytime in Settings -> Notifications."] = "desativado. Você pode reativar quando quiser em Opções -> Notificações."
    L["All notification categories are active and no individual players are muted."] = "Todas as categorias de notificação estão ativas e nenhum jogador está silenciado."
    L["Alt+Click: toggle Target Radar"] = "Alt+Clique: alternar Radar de Alvos"
    L["Attaches the Clans, Allies & Global Chat LFG side-tab inside Blizzard's Group Finder (I) window and scans public LFG channels."] = "Anexa a aba lateral de Guildas, Aliados e Chat Global dentro da janela Procurando Grupo (I) e monitora canais públicos de LFG."
    L["Auto-silence social popups & chimes inside Dungeons, Raids & BGs"] = "Silenciar popups e sons sociais automaticamente em Masmorras, Raides e BGs"
    L["Automatically pauses social popups and chimes whenever you enter a Dungeon, Raid, or Battleground (Group Avoid safety warnings still show)."] = "Pausa popups e sons sociais automaticamente sempre que você entrar em Masmorra, Raide ou Campo de Batalha (avisos de segurança de Evitar em Grupo continuam aparecendo)."
    L["Click 'Re-enable Alerts' or 'Unmute All Players' anytime if you accidentally silenced something via the toast crossed-bell button."] = "Clique em 'Reativar Alertas' ou 'Dessilenciar Jogadores' quando quiser se tiver silenciado algo sem querer pelo botão de sino cortado do aviso."
    L["Click any shortcut below to jump straight to that official game window with the SocialCentral tab active, or configure preferences above."] = "Clique em qualquer atalho abaixo para abrir direto a janela oficial do jogo com a aba do SocialCentral ativa, ou ajuste suas preferências acima."
    L["Ctrl+Click: open Conversations"] = "Ctrl+Clique: abrir Conversas"
    L["Disabled:"] = "Desativados:"
    L["Do Not Disturb (pause all popups & chimes without changing your checkboxes)"] = "Não Perturbe (pausa todos os popups e sons sem alterar suas opções)"
    L["Drag: move button"] = "Arrastar: mover botão"
    L["Great for raids, arenas, or quiet focus sessions; uncheck to resume your exact saved preferences."] = "Ótimo para raides, arenas ou momentos de foco; desmarque para retomar suas preferências salvas exatamente como estavam."
