    L["Your character is Lv %d — first dungeons (Ragefire Chasm / Hall of Thanes) start at Lv 13.\n\nSwitch Category to 'All Categories' or 'Quests & Zones', uncheck 'My Level', or use '/LookingForGroup' to see all groups now."] = "Seu personagem está no Nv %d — as primeiras masmorras (Cavernas Ígneas / Hall of Thanes) começam no Nv 13.\n\nMude a categoria para 'Todas as Categorias' ou 'Missões e Áreas', desmarque 'Meu Nível' ou use '/LookingForGroup' para ver grupos agora."
