    L["Blizzard protects direct opening of the Calendar panel from addons. Copy '/calendar' below or click the Calendar icon on your Minimap."] = "A Blizzard protege a abertura direta do Calendário por addons. Copie '/calendar' abaixo ou clique no ícone do Calendário no Minimapa."
