    L["Blizzard restricts public Group Finder creation to the native Official tab (Tab 1). Clicking here switches you there with your roles ready."] = "A Blizzard restringe a criação no Localizador público à aba Oficial (Aba 1). Clicar aqui muda direto para lá com suas funções prontas."
    L["Chat (/g)"] = "Chat (/g)"
    L["Click Blizzard's Remove button on the Official Listing tab to end your public listing."] = "Clique no botão Remover da Blizzard na aba Oficial para encerrar seu anúncio público."
    L["Create a group listing first to share it in Guild Chat (/g)."] = "Crie ou publique um anúncio primeiro para compartilhá-lo no Chat da Guilda (/g)."
    L["Create a private group listing visible only to your Guild, Allied Guilds & Friends (hidden from public LFG)."] = "Cria um anúncio privado visível apenas para sua Guilda, Guildas Aliadas e Amigos (oculto do LFG público)."
    L["Help: Official LFG + SocialCentral Mirror"] = "Ajuda: LFG Oficial + Espelho SocialCentral"
    L["Inst (1h): %d/%d"] = "Inst (1h): %d/%d"
    L["List Official"] = "Listar Oficial"
    L["List in Official LFG (+ Guild & Allies)"] = "Listar no LFG Oficial (+ Guilda e Aliadas)"
