    L["Official LFG + Clan & Allies (Official Tab)"] = "LFG Oficial + Guilda e Aliados (Aba Oficial)"
    L["Official LFG tab opened: select your activities and click Blizzard's List button — SocialCentral will mirror it automatically."] = "Aba Oficial aberta: escolha suas atividades e clique no botão Listar da Blizzard — o SocialCentral espelhará automaticamente."
    L["Official Only (No Mirror)"] = "Somente Oficial (Sem Espelho)"
    L["Once you click Blizzard's List button on Tab 1, SocialCentral automatically mirrors your Official listing to Guild, Allies & Friends."] = "Ao clicar no botão Listar da Blizzard na Aba 1, o SocialCentral espelha automaticamente seu anúncio oficial para Guilda, Aliadas e Amigos."
    L["Open Official Tab"] = "Abrir Aba Oficial"
    L["Or create a PRIVATE listing (Guild, Allies & Friends only — hidden from public LFG):"] = "Ou crie um anúncio PRIVADO (só Guilda, Aliadas e Amigos — oculto do LFG público):"
    L["Pre-fills Guild Chat (/g) with your active Official LFG activity and details."] = "Preenche o Chat da Guilda (/g) com a atividade e detalhes do seu anúncio Oficial ativo."
    L["Press 'I' to open Blizzard's Group Finder (Listing tab) — SocialCentral will mirror your Official listing automatically."] = "Aperte 'I' para abrir o Localizador de Grupos da Blizzard (aba Listar) — o SocialCentral espelhará seu anúncio Oficial automaticamente."
    L["Private + Guild Chat (/g)"] = "Privado + Chat da Guilda (/g)"
    L["Private [SC]"] = "Privado [SC]"
    L["Select roles & dungeons above, then click Blizzard's List button!"] = "Marque funções e masmorras acima e clique no botão Listar da Blizzard!"
    L["Stopped mirroring your Official LFG listing to SocialCentral (your Official listing remains active)."] = "Espelhamento no SocialCentral desativado (seu anúncio no LFG Oficial continua ativo)."
    L["Switches to Blizzard's Official Listing tab so you can publish your group cleanly while SocialCentral mirrors it to Guild & Allies."] = "Muda para a aba Oficial da Blizzard para você publicar no Localizador público enquanto o SocialCentral espelha para Guilda e Aliados."
    L["Your private listing (%s) is now active in SocialCentral."] = "Seu anúncio privado (%s) já está ativo no SocialCentral."
    L["Apply only to this shortcut (%s)"] = "Aplicar apenas a este atalho (%s)"
    L["Apply to all applicable shortcuts (%s)"] = "Aplicar a todos os atalhos aplicáveis (%s)"
    L["Are you sure you want to reset your shortcut auto-open choices so SocialCentral asks again on O, I, J, and C?"] = "Tem certeza de que deseja redefinir suas escolhas de abertura automática dos atalhos para o SocialCentral perguntar novamente em O, I, J e C?"
    L["Ask Again on Shortcuts"] = "Perguntar Novamente nos Atalhos"
    L["Automatically opens the SocialCentral Clans & Allies LFG tab whenever you open Group Finder (I)."] = "Abre automaticamente a aba de LFG da Guilda e Aliadas do SocialCentral sempre que você abrir o Localizador de Grupos (I)."
    L["Automatically opens the SocialCentral Guild Hub tab whenever you open Guild / Communities (J)."] = "Abre automaticamente a aba Central da Guilda do SocialCentral sempre que você abrir Guilda / Comunidades (J)."
    L["Automatically opens the SocialCentral My Alts inventory & gold vault tab whenever you open Character (C)."] = "Abre automaticamente a aba Meus Alts do SocialCentral sempre que você abrir Personagem (C)."
    L["Automatically opens the SocialCentral side-tab whenever you open Social / Friends (O)."] = "Abre automaticamente a aba lateral do SocialCentral sempre que você abrir Social / Amigos (O)."
    L["Character & My Alts"] = "Personagem e Meus Alts"
    L["Choose whether to apply this preference to only the current shortcut or to all enabled shortcuts, and change it anytime in Settings."] = "Escolha se deseja aplicar esta preferência apenas ao atalho atual ou a todos os atalhos ativos, podendo mudar depois em Configurações."
    L["Clears your saved first-time shortcut choices (O, I, J, C) and resets auto-open back to asking on first open."] = "Limpa suas escolhas salvas da primeira abertura dos atalhos (O, I, J, C) e volta a perguntar na próxima abertura."
    L["Click Blizzard's Character or Currency bottom tabs anytime to switch back to equipment view."] = "Clique nas abas inferiores oficiais da Blizzard a qualquer momento para voltar para equipamentos ou reputação."
    L["Click Blizzard's Guild Chat or Roster tabs on the right anytime to return to the native guild view."] = "Clique nas abas laterais oficiais do Chat da Guilda ou Lista de Membros a qualquer momento para voltar à tela oficial."
    L["Click Blizzard's Official Listing or Browse tabs anytime to switch back inside the same window."] = "Clique nas abas oficiais Listar ou Buscar na parte direita a qualquer momento para voltar dentro da mesma janela."
    L["Click any Blizzard tab inside the window anytime to switch back to the native Friends or Who lists."] = "Clique em qualquer aba oficial da janela a qualquer momento para voltar às listas nativas de Amigos."
    L["Click to re-enable the confirmation prompt the next time you press an enabled official shortcut key."] = "Clique para reativar a pergunta de confirmação na próxima vez que abrir uma janela oficial habilitada."
    L["Guild & Communities"] = "Guilda e Comunidades"
    L["Help: Ask Again on Shortcuts"] = "Ajuda: Perguntar Novamente nos Atalhos"
    L["Help: Auto-Open Character (C)"] = "Ajuda: Abrir Direto em Personagem (C)"
