    L["Keep Blizzard Official Tab"] = "Manter Aba Oficial da Blizzard"
    L["Lets you choose whether pressing an official game window shortcut (O, I, J, C) jumps straight to the SocialCentral tab or opens Blizzard's default tab."] = "Permite escolher se pressionar o atalho de uma janela oficial do jogo (O, I, J, C) já abre direto na aba do SocialCentral ou na aba padrão da Blizzard."
    L["Open Shortcut Directly on SocialCentral Tab"] = "Abrir Atalho Direto na Aba do SocialCentral"
    L["Open SocialCentral Tab"] = "Abrir Aba do SocialCentral"
    L["Saved for %s: shortcut will keep opening on Blizzard's default tab."] = "Salvo para %s: o atalho continuará abrindo na aba padrão da Blizzard."
    L["Saved for %s: shortcut will open directly on the SocialCentral tab."] = "Salvo para %s: o atalho agora abrirá direto na aba do SocialCentral."
    L["Saved for all enabled shortcuts (%s): windows will keep opening on Blizzard's default tab."] = "Salvo para todos os atalhos ativos (%s): as janelas continuarão abrindo na aba padrão da Blizzard."
    L["Saved for all enabled shortcuts (%s): windows will open directly on the SocialCentral tab."] = "Salvo para todos os atalhos ativos (%s): as janelas agora abrirão direto na aba do SocialCentral."
    L["Shortcut Behavior — %s (%s)"] = "Comportamento do Atalho — %s (%s)"
    L["Shortcut prompts reset: SocialCentral will ask again the next time you open each window."] = "Perguntas de atalhos redefinidas: o SocialCentral perguntará novamente na próxima vez que você abrir cada janela."
    L["Social & Friends"] = "Social e Amigos"
    L["You can change this anytime in Settings -> Summary & Windows."] = "Você pode alterar isso a qualquer momento em Configurações -> Resumo e Janelas."
    L["You opened %s (%s) with SocialCentral integration enabled.\nWould you like this shortcut to open directly on the SocialCentral tab instead of Blizzard's default tab?"] = "Você abriu %s (%s) com a integração do SocialCentral ativada.\nDeseja que este atalho já abra diretamente na aba do SocialCentral em vez da aba oficial da Blizzard?"
    L["Anyone in the guild need Stratholme or Scholomance?"] = "Alguém na guilda precisa de Stratholme ou Scolomântia?"
    L["Automatically pauses minimap message previews while you are inside 5-player Dungeons or instanced scenarios."] = "Pausa automaticamente as prévias de mensagens no minimapa enquanto você estiver dentro de Masmorras de 5 jogadores ou cenários instanciados."
    L["Automatically pauses minimap message previews while you are inside Battlegrounds or Arenas."] = "Pausa automaticamente as prévias de mensagens no minimapa enquanto você estiver em Campos de Batalha ou Arenas."
    L["Automatically pauses minimap message previews while you are inside Raid instances."] = "Pausa automaticamente as prévias de mensagens no minimapa enquanto você estiver dentro de Raides."
    L["Battle.net Friends"] = "Amigos da Battle.net"
    L["Choose which message types should trigger previews and whether to automatically silence them inside Dungeons, Raids, Battlegrounds, or Combat. You can change this anytime in Settings -> Notifications."] = "Escolha quais tipos de mensagem devem abrir prévias e se deseja silenciá-las automaticamente dentro de Masmorras, Raides, Campos de Batalha ou Combate. Você pode alterar isso a qualquer momento em Configurações -> Notificações."
    L["Configure Previews..."] = "Configurar Prévias..."
    L["Controls how many seconds the message preview stays expanded beside the Minimap before closing and gliding back into the SC icon."] = "Controla por quantos segundos a prévia da mensagem fica expandida ao lado do Minimapa antes de se fechar e voltar para o ícone do SC."
