    L["Expands the minimap message preview for Party, Raid, and Instance chat lines sent by your teammates (showing their live portrait when nearby)."] = "Expande a prévia no minimapa para mensagens de Grupo, Raide e Instância enviadas por seus companheiros (mostrando o retrato do personagem quando estiver perto)."
