    L["Expands the minimap message preview whenever a Battle.net friend messages you (showing their character icon or the Battle.net emblem)."] = "Expande a prévia no minimapa sempre que um amigo da Battle.net enviar mensagem (mostrando o ícone do personagem ou o emblema da Battle.net)."
