    L["Hey! Saw you online — want to group up for a dungeon?"] = "Oi! Vi você online — anima montar grupo para uma masmorra?"
    L["Hide message previews inside Battlegrounds & Arenas"] = "Ocultar prévias de mensagens em Campos de Batalha e Arenas"
    L["Hide message previews inside Dungeons"] = "Ocultar prévias de mensagens dentro de Masmorras"
    L["Hide message previews inside Raids"] = "Ocultar prévias de mensagens dentro de Raides"
    L["Hide message previews while in combat"] = "Ocultar prévias de mensagens durante combate"
    L["Hover over the preview to read the full text and pause the timer, or click to jump straight into replying."] = "Passe o mouse sobre a prévia para ler a mensagem completa e pausar o tempo, ou clique para ir direto responder."
    L["Hovering your mouse over the preview always pauses the countdown automatically so you can finish reading."] = "Passar o mouse sobre a prévia sempre pausa a contagem automaticamente para você terminar de ler com calma."
    L["Keep checked during boss nights to avoid distractions beside the minimap."] = "Mantenha marcado em noites de raide para evitar distrações ao lado do minimapa."
    L["Keep checked to keep your minimap area completely clear during dungeon pulls; resumes automatically once you exit."] = "Mantenha marcado para deixar a área do minimapa livre durante masmorras; volta ao normal automaticamente ao sair."
    L["Left-click opens the conversation or Shift+Click opens a quick Battle.net reply."] = "Clique esquerdo abre a conversa ou Shift+Clique abre resposta rápida da Battle.net."
    L["Master switch for the animated message preview capsule beside the Minimap."] = "Chave geral para a caixa animada de prévia de mensagens ao lado do Minimapa."
    L["Meeting in town in 5 minutes before heading out!"] = "Encontro na cidade em 5 minutos antes de sairmos!"
    L["Minimap Message Previews"] = "Prévias de Mensagens no Minimapa"
    L["Minimap Message Previews disabled. You can re-enable them anytime in Settings -> Notifications."] = "Prévias de Mensagens no Minimapa desativadas. Você pode reativar quando quiser em Configurações -> Notificações."
    L["Minimap Message Previews enabled! Change channels or dungeon/raid filters anytime in Settings -> Notifications."] = "Prévias de Mensagens no Minimapa ativadas! Altere canais ou filtros de masmorra/raide quando quiser em Configurações -> Notificações."
    L["No, Disable"] = "Não, desativar"
    L["Off by default for busy guilds; enable if you want to catch guild messages right beside your minimap without watching chat."] = "Desativado por padrão para guildas movimentadas; ative se quiser acompanhar mensagens da guilda ao lado do minimapa sem olhar o chat."
    L["Off by default to keep group runs quiet; combine with the Dungeon/Raid silence checkboxes below to show only open-world group chat."] = "Desativado por padrão para manter masmorras silenciosas; combine com as opções de ocultar em Masmorras/Raides abaixo para ver só chat de grupo no mundo aberto."
    L["Open Conversation"] = "Abrir Conversa"
    L["Pauses minimap message previews whenever your character is actively in combat, even in the open world."] = "Pausa as prévias de mensagens no minimapa sempre que seu personagem estiver em combate, mesmo no mundo aberto."
    L["Pick which channels trigger previews (Whispers, Battle.net, Group, Guild, Private Rooms) and silence them automatically inside Dungeons, Raids, Battlegrounds, or Combat."] = "Escolha quais canais abrem prévias (Sussurros, Battle.net, Grupo, Guilda, Salas Privadas) e silencie automaticamente dentro de Masmorras, Raides, Campos de Batalha ou Combate."
    L["Preview display duration (seconds):"] = "Tempo de exibição da prévia (segundos):"
    L["Quick Reply in Chat"] = "Responder Rápido no Chat"
    L["Ready check! Summoning everyone at the dungeon entrance."] = "Todos prontos! Sumonando o grupo na entrada da masmorra."
    L["Select at least one channel above, or click 'No, Disable'."] = "Selecione pelo menos um canal acima ou clique em 'Não, desativar'."
    L["Show previews for Battle.net Friends"] = "Mostrar prévias de Amigos da Battle.net"
    L["Show previews for Group Chat (Party / Raid / Instance)"] = "Mostrar prévias de Chat de Grupo (Grupo / Raide / Instância)"
    L["Show previews for Guild & Officer Chat"] = "Mostrar prévias de Chat da Guilda e Oficiais"
    L["Show previews for Private Rooms & Alliance Chat"] = "Mostrar prévias de Salas Privadas e Chat da Aliança"
    L["Show previews for Whispers & SocialCentral Direct Chat"] = "Mostrar prévias de Sussurros e Chat Direto do SocialCentral"
    L["Shows a compact animated preview with the sender's icon and opening words on the left side of your Minimap whenever a matching message arrives, then closes back into the SC icon."] = "Exibe uma prévia compacta e animada com o ícone de quem enviou e as primeiras palavras no lado esquerdo do Minimapa sempre que chegar uma mensagem, fechando-se de volta para o ícone do SC."
    L["Temporarily expands a compact animated capsule vertically centered on the left side of your Minimap showing the sender's character icon and opening words, then smoothly closes back into the SC icon."] = "Expande temporariamente uma caixa compacta e centralizada na vertical ao lado esquerdo do Minimapa com o ícone do personagem e as primeiras palavras da mensagem, fechando-se suavemente de volta ao ícone do SC."
    L["Test Minimap Preview"] = "Testar Prévia no Minimapa"
    L["Uncheck if you prefer to receive Private Room & Alliance alerts only in the top Toast stack or Conversations panel."] = "Desmarque se preferir ver avisos de Salas Privadas e Aliança apenas nos alertas do topo da tela ou na aba Conversas."
    L["Uncheck if you still want Whispers or Group previews during PvP matches."] = "Desmarque se ainda quiser ver prévias de Sussurros ou Grupo durante partidas PvP."
    L["Uncheck to disable minimap message previews completely without affecting your Conversations panel or unread counter badge."] = "Desmarque para desativar completamente as prévias no minimapa sem afetar sua janela de Conversas ou o contador de não lidas."
    L["Whispers & Direct Chat"] = "Sussurros e Chat Direto"
    L["You can customize channels, duration, and dungeon/raid rules anytime in Settings -> Notifications."] = "Você pode ajustar canais, duração e filtros de masmorra/raide quando quiser em Configurações -> Notificações."
    L["You received a message! Would you like SocialCentral to briefly expand a message preview with the sender's icon beside the Minimap? Choose which channels to show:"] = "Você recebeu uma mensagem! Deseja que o SocialCentral exiba temporariamente uma prévia com o ícone do personagem e as primeiras palavras ao lado do Minimapa? Escolha quais canais deseja receber:"
    L["%d results"] = "%d resultados"
    L["0 results"] = "0 resultados"
    L["1 result"] = "1 resultado"
    L["Any additional incoming messages wait cleanly in a queue (+N) and rise smoothly into view as soon as the top preview finishes and returns to the SC icon."] = "Mensagens adicionais ficam organizadas em uma fila (+N) e sobem suavemente assim que a primeira prévia termina o tempo e volta para o ícone do SC."
    L["Go to"] = "Ir para"
    L["Help: Preview Max Visible"] = "Ajuda: Linhas Simultâneas de Prévia"
    L["Help: Settings Search"] = "Ajuda: Pesquisa nas Configurações"
    L["Instantly searches every SocialCentral option across all four tabs by title, description, channel, or common keywords in English, Portuguese, and Spanish (no accents required)."] = "Pesquisa instantaneamente todas as opções do SocialCentral nas quatro abas por título, descrição, canal ou palavras-chave em Português, Inglês e Espanhol (sem precisar digitar acentos)."
    L["Minimap"] = "Minimapa"
    L["Module Disabled"] = "Módulo Desativado"
    L["No settings found for \"%s\"."] = "Nenhuma configuração encontrada para \"%s\"."
    L["Radar"] = "Radar"
    L["Search settings (e.g. minimap, sound, raid, radar, theme)..."] = "Pesquisar configurações (ex: minimapa, som, raide, radar, tema)..."
    L["Sets how many message previews can appear stacked simultaneously beside your Minimap (1 to 3 rows, newest at the bottom)."] = "Define quantas linhas de prévia podem aparecer empilhadas ao mesmo tempo ao lado do Minimapa (de 1 a 3 linhas, com a mais recente embaixo)."
    L["Shortcuts"] = "Atalhos"
    L["Simultaneous minimap preview rows (1–3):"] = "Linhas simultâneas de prévia no minimapa (1 a 3):"
    L["Sound"] = "Som"
    L["Test Queue (4)"] = "Testar Fila (4)"
    L["Toggle checkboxes, adjust counters, switch options, or run actions right inside the search results — or click 'Go to' on any card to jump directly to its tab and highlight it."] = "Marque caixas, ajuste contadores, troque opções ou clique em botões direto nos resultados — ou clique em 'Ir para' em qualquer card para abrir a aba exata com destaque dourado."
    L["Try a quick topic below or search by tab, feature, or shortcut key:"] = "Experimente um tema rápido abaixo ou pesquise por aba, recurso ou tecla de atalho:"
    L["Private Rooms"] = "Salas Privadas"
    L["Minimap counter badge style:"] = "Estilo do contador no minimapa:"
    L["Help: Minimap Badge Style"] = "Ajuda: Estilo do Contador no Minimapa"
    L["Choose how multiple unread message types appear on the Minimap icon: either a single chat-colored Fusion Circle directly under the SC icon (blending Whisper pink, Group blue, Raid orange, Guild green, and Battle.net cyan, splitting cleanly on hover) or separate non-overlapping numbers orbiting around the icon."] = "Escolha como vários tipos de mensagens não lidas aparecem no ícone do Minimapa: um único Círculo de Fusão com as cores do chat misturadas logo abaixo do ícone do SC (rosa de sussurro, azul de grupo, laranja de raide, verde de guilda e ciano da Battle.net, que se divide ao passar o mouse) ou números separados em volta do ícone sem sobreposição."
    L["Pick 'Fusion Circle (Under Icon)' for the animated color-merge orb directly beneath the icon, or 'Around Icon (Separate)' to keep each chat type spaced around the icon at all times."] = "Escolha 'Círculo de Fusão (Sob o Ícone)' para o efeito animado de fusão de cores exatamente abaixo do ícone, ou 'Em Volta do Ícone (Separados)' para manter cada tipo de chat espaçado ao redor o tempo todo."
    L["Fusion Circle (Under Icon)"] = "Círculo de Fusão (Sob o Ícone)"
    L["Around Icon (Separate)"] = "Em Volta do Ícone (Separados)"
    L["Move Preview Position"] = "Mover Posição das Prévias"
    L["Reset Preview Position"] = "Voltar ao Minimapa"
    L["Help: Move Preview Position"] = "Ajuda: Mover Posição das Prévias"
    L["Lets you move the 3-row message preview stack to any location on your screen (or drag any live preview directly), while keeping the smooth launch and return-to-Minimap fusion animation."] = "Permite posicionar as até 3 notificações de prévia em qualquer lugar da tela (ou arrastar uma prévia ativa diretamente), mantendo a animação de saída e retorno com fusão no ícone do SC no Minimapa."
    L["Click 'Move Preview Position' (or type '/sc preview move') to drag the 3-slot guide anywhere on screen, then click 'Done'. Click 'Reset Preview Position' anytime to dock back beside the Minimap."] = "Clique em 'Mover Posição das Prévias' (ou digite '/sc preview move') para arrastar o guia de 3 espaços para qualquer ponto da tela e clique em 'Concluir'. Clique em 'Voltar ao Minimapa' quando quiser restaurar o padrão."
    L["Drag anywhere on screen"] = "Arraste para qualquer lugar da tela"
    L["Returns to SC Minimap icon"] = "Volta para o ícone SC no Minimapa"
    L["Done"] = "Concluir"
    L["Message preview position reset beside Minimap."] = "Posição das prévias restaurada ao lado do Minimapa."
    L["Left-click: open conversation  |  Shift+Click: quick reply\nDrag: move previews anywhere  |  Right-click: options"] = "Clique esq.: abrir conversa  |  Shift+Clique: resposta rápida\nArraste: mover prévias na tela  |  Clique dir.: opções"
