    L["Account-Ignored players also trigger Group Avoid warnings, LFG warnings, and Target Radar alerts. Never stores BattleTags or Real IDs."] = "Jogadores nos Ignorados da Conta também disparam alertas em Grupo, Localizador e Radar de Alvos. Nunca grava BattleTags nem Real IDs."
    L["Add details (optional)..."] = "Adicionar detalhes (opcional)..."
    L["Add extra words or short phrases to hide in public channels when Anti-Spam Shield is enabled."] = "Adicione palavras ou frases curtas extras para ocultar em canais públicos quando o Escudo Anti-Spam estiver ativado."
    L["Add keywords like 'Crusader' or 'Onyxia' above to get instant alerts from busy city chats."] = "Adicione palavras-chave como 'Cruzado' ou 'Onyxia' acima para receber alertas instantâneos dos chats movimentados."
    L["Are you sure you want to clear the session filtered messages log?"] = "Tem certeza de que deseja limpar o registro de mensagens filtradas desta sessão?"
    L["Are you sure you want to remove '%s' from your Account Ignore list?"] = "Tem certeza de que deseja remover '%s' da sua lista de Ignorados da Conta?"
    L["Automatically hides messages in Blizzard's chat windows from anyone on your unlimited Account Ignore list without consuming WoW's 50-slot per-character ignore cap."] = "Oculta automaticamente no chat oficial do WoW as mensagens de qualquer jogador na sua lista ilimitada de Ignorados da Conta, sem gastar o limite de 50 vagas por personagem do jogo."
    L["Block"] = "Bloquear"
    L["Blocked Keyword"] = "Palavra Bloqueada"
    L["Blocks a player across all characters on your account with a reason, optional expiration, and automatic official chat hiding without using WoW's 50-slot character ignore limit."] = "Bloqueia um jogador em todos os personagens da sua conta com motivo, validade opcional e ocultação automática no chat oficial sem usar o limite de 50 vagas por personagem."
    L["Busy / AFK"] = "Ocupado / AFK"
