    L["Chat hidden"] = "Chat oculto"
    L["Chat visible"] = "Chat visível"
    L["Checks Trade, General, World, and LFG channels for your name, nicknames, and custom keywords (automatically skipping blocked/spam messages)."] = "Monitora os canais Comércio, Geral, Mundo e LFG procurando seu nome, apelidos e palavras-chave (pulando automaticamente mensagens bloqueadas/spam)."
    L["Checks incoming Guild and Officer messages for your name, nicknames, and custom keywords."] = "Monitora mensagens recebidas na Guilda e Oficial procurando seu nome, apelidos e palavras-chave."
    L["Checks incoming Party, Raid, and Instance messages for your name, nicknames, and custom keywords."] = "Monitora mensagens de Grupo, Raide e Instância procurando seu nome, apelidos e palavras-chave."
    L["Checks nearby Say and Yell messages for your name, nicknames, and custom keywords."] = "Monitora mensagens próximas em Dizer e Gritar procurando seu nome, apelidos e palavras-chave."
