    L["Click a sender name above to reply, or click 'Keywords' to configure."] = "Clique no nome de um remetente acima para responder ou em 'Palavras-Chave' para configurar."
    L["Click any highlighted link to open SocialCentral's Copy Link popup ready for Ctrl+C."] = "Clique em qualquer link destacado para abrir a janela de cópia do SocialCentral pronta para Ctrl+C."
    L["Click any row to copy the message, edit/remove an Account Ignore, or block a spammer permanently."] = "Clique em qualquer linha para copiar a mensagem, editar/remover um Ignorado da Conta ou bloquear um spammer."
    L["Click any sender name to whisper or open chat, or click Keywords to edit monitored words."] = "Clique no nome de qualquer remetente para sussurrar ou abrir conversa, ou em Palavras-Chave para editar termos monitorados."
