    L["On my way! ({zone})"] = "A caminho! ({zona})"
    L["Opens the Social directory filtered directly to your Account Ignores list where you can view reasons, timers, add new blocks, or unblock players."] = "Abre o diretório Social filtrado direto nos seus Ignorados da Conta, onde você vê motivos, prazos, adiciona bloqueios ou desbloqueia jogadores."
    L["Optional Note:"] = "Nota Opcional:"
    L["Other"] = "Outro"
    L["Party / Raid / Instance"] = "Grupo / Raide / Instância"
    L["Highlights matched words in gold directly inside chat messages, triggers optional alerts, and logs matches in the Mentions Radar whenever your name, nicknames, or keywords appear in selected channels."] = "Destaca em dourado as palavras encontradas dentro das mensagens dos chats, dispara alertas opcionais e registra no Radar de Menções sempre que seu nome, apelidos ou palavras-chave aparecerem."
    L["Permanent"] = "Permanente"
    L["Personal nicknames / alt names (comma-separated):"] = "Apelidos pessoais / nomes de alts (separados por vírgula):"
    L["Play audio chime on mention or keyword match"] = "Tocar som ao detectar menção ou palavra-chave"
    L["Plays a subtle audio chime whenever a monitored mention or custom keyword is detected in chat."] = "Toca um som sutil sempre que uma menção ou palavra-chave monitorada for detectada no chat."
    L["Press Ctrl+C to copy this link to your clipboard."] = "Pressione Ctrl+C para copiar este link para a área de transferência."
    L["Protects your chat across all characters with an unlimited Account Ignore list, optional public Anti-Spam Shield, and 1-click copyable Discord/Web links."] = "Protege seu chat em todos os personagens com Ignorados da Conta ilimitados, Escudo Anti-Spam público opcional e links Discord/Web clicáveis em 1 clique."
    L["Public Channels (Trade/General)"] = "Canais Públicos (Comércio/Geral)"
    L["Reason:"] = "Motivo:"
    L["Reduces wall-of-text repetition in Trade and World channels without affecting guild or party chat."] = "Reduz repetições seguidas no Comércio e Mundo sem afetar o chat da guilda ou do grupo."
    L["Repeated Flood"] = "Flood Repetido"
    L["Save Block"] = "Salvar Bloqueio"
    L["Say"] = "Dizer"
    L["Say / Yell"] = "Dizer / Gritar"
    L["Scammer"] = "Golpista"
    L["Sends a local sample mention to preview the Notification Toast, chime, and Mentions Radar log."] = "Envia uma menção de exemplo local para testar o Toast, o som e o registro no Radar de Menções."
    L["Separate entries with commas (e.g. 'Rapha, MainName'). Matching is case- and accent-insensitive."] = "Separe com vírgulas (ex.: 'Rapha, Principal'). A busca ignora maiúsculas e acentos."
    L["Separate entries with commas (e.g. 'gdkp, boost, carry'). Ignored for Friends, Guild, and Group members."] = "Separe com vírgulas (ex.: 'gdkp, boost, carry'). Nunca afeta Amigos, Guilda ou Grupo."
    L["Separate keywords with commas (e.g. 'Onyxia, Crusader, Portal, BRD'). Matching ignores accents and capitalization."] = "Separe palavras-chave com vírgulas (ex.: 'Onyxia, Cruzado, Portal, BRD'). Ignora acentos e maiúsculas."
    L["Separate multiple entries with commas (e.g. 'Onyxia, Crusader, Portal, Tank'). Respects Do Not Disturb and Auto-Silence in Instances."] = "Separe vários termos com vírgulas (ex.: 'Onyxia, Cruzado, Portal, Tank'). Respeita Não Perturbe e Silenciar em Instâncias."
    L["Shows every message hidden this session by your Account Ignore list or the optional Public Anti-Spam Shield so nothing legitimate is ever lost silently."] = "Exibe cada mensagem oculta nesta sessão pelos Ignorados da Conta ou pelo Escudo Anti-Spam para que nada legítimo se perca."
    L["Spam / RMT"] = "Spam / RMT"
    L["Spammer"] = "Spammer"
    L["Stop alerting when your name, nickname, or custom keywords appear in chat."] = "Parar de avisar quando seu nome, apelido ou palavras-chave aparecerem no chat."
    L["Suppress repeated identical public messages (flood) from strangers"] = "Bloquear mensagens públicas repetidas seguidas (flood) de desconhecidos"
    L["Target a player first."] = "Selecione um jogador como alvo primeiro."
    L["Test Mention Alert"] = "Testar Alerta de Menção"
    L["Toxic"] = "Tóxico"
    L["Trade & Craft"] = "Comércio e Craft"
    L["Turns Discord invite links (discord.gg/...) and web URLs (https://...) into clickable links in both SocialCentral Conversations and official WoW chat."] = "Transforma convites do Discord (discord.gg/...) e endereços web (https://...) em links clicáveis nas Conversas do SocialCentral e no chat oficial do WoW."
    L["Unblock"] = "Desbloquear"
    L["Uncheck for silent visual toast and Mentions Radar logging only."] = "Desmarque para receber apenas o alerta visual e o registro silencioso no Radar de Menções."
    L["Use a character name (BattleTags are never stored)."] = "Use o nome de um personagem (BattleTags nunca são gravadas)."
    L["Useful when raid leaders call your name or role in chat."] = "Útil quando líderes de raide chamam seu nome ou função no chat."
    L["Watch selected chat channels for custom words or short phrases such as bosses, dungeons, enchants, or portals."] = "Monitora os canais selecionados buscando palavras ou frases curtas como chefes, masmorras, encantamentos ou portais."
    L["When Anti-Spam Shield is active, hides duplicate identical messages sent by the same stranger in public channels within 45 seconds."] = "Com o Escudo Anti-Spam ativo, oculta mensagens idênticas repetidas enviadas pelo mesmo desconhecido em canais públicos dentro de 45 segundos."
    L["Yell"] = "Gritar"
    L["You can also use /sc ignore <name> anytime."] = "Você também pode usar /sc ignore <nome> a qualquer momento."
    L["Zero network messages are sent; purely local preview."] = "Nenhuma mensagem de rede é enviada; prévia 100% local."
    L["e.g. Onyxia, Crusader, Portal, BRD"] = "ex.: Onyxia, Cruzado, Portal, BRD"
    L["e.g. Rapha, Tank, MainName"] = "ex.: Rapha, Tank, Principal"
    L["Minimum interval between message sounds (anti-spam):"] = "Intervalo mínimo entre sons de mensagem (anti-spam):"
    L["Help: Message Sound Cooldown"] = "Ajuda: Intervalo do Som de Mensagem"
    L["Prevents rapid spam from repeating the message notification sound. No new message chime will play until at least this many seconds have passed (6 seconds by default, 3 seconds minimum)."] = "Impede que spam rápido fique repetindo o som de notificação de mensagens. Nenhum novo som toca até passar pelo menos esse tempo em segundos (padrão de 6 segundos, mínimo de 3 segundos)."
    L["Applies globally and per sender across Whispers, Battle.net, Rooms, Mentions, and mirrored Guild/Group chat."] = "Aplica globalmente e por remetente em Sussurros, Battle.net, Salas, Menções e chat espelhado de Guilda/Grupo."
    L["Test Message Sound"] = "Testar Som de Mensagem"
    L["Help: Test Message Sound"] = "Ajuda: Testar Som de Mensagem"
    L["Plays the incoming message notification chime so you can verify your volume and anti-spam interval."] = "Toca o som de notificação de mensagem recebida para você testar o volume e o intervalo anti-spam."
    L["Click repeatedly to confirm the anti-spam cooldown prevents rapid re-triggering within the chosen interval."] = "Clique várias vezes seguidas para confirmar que a proteção anti-spam impede o som de repetir antes do intervalo escolhido."
    L["%d boss(es)"] = "%d chefe(s)"
    L["%s logged: %s — %s (%d members). View in /sc runs"] = "%s registrada: %s — %s (%d membros). Veja em /sc runs"
    L["...and %d more"] = "...e mais %d"
    L["Are you sure you want to delete all %d recorded dungeon and raid runs?"] = "Tem certeza de que deseja apagar todas as %d masmorras e raids registradas?"
    L["Armed"] = "Preparado"
    L["Automatically saves each dungeon or raid that actually enters combat, storing teammate names, classes, roles, bosses, and duration from the 1st enemy pulled until a member leaves or the run finishes."] = "Salva automaticamente cada masmorra ou raid que realmente entra em combate, guardando os nomes, classes, funções, chefes derrotados e a duração desde o 1º inimigo atacado até alguém sair do grupo ou a masmorra encerrar."
    L["Avoid / Red Flag"] = "Evitar / Alerta"
    L["Bosses Defeated"] = "Chefes Derrotados"
    L["Clear Dungeon Log"] = "Limpar Histórico de Masmorras"
    L["Click for teammate actions, copy summary, or delete"] = "Clique para ações com companheiros, copiar resumo ou excluir"
    L["Completed"] = "Concluída"
    L["Copy Run Summary"] = "Copiar Resumo da Masmorra"
    L["Delete This Run"] = "Excluir Esta Masmorra"
    L["Disable Recording"] = "Desativar Registro"
    L["Dungeon & Raid Group Log"] = "Registro de Grupos de Masmorra e Raid"
    L["Dungeon & Raid Log"] = "Histórico de Masmorras"
    L["Dungeon & Raid recording disabled. Re-enable anytime in Settings -> Summary & Windows -> Dungeon & Raid Group Log."] = "Registro de Masmorras e Raids desativado. Reative quando quiser em Configurações -> Resumo & Janelas -> Registro de Grupos de Masmorra e Raid."
    L["Dungeon Log"] = "Masmorras"
    L["Duration (1st pull to end)"] = "Duração (1º combate até o fim)"
    L["Ended By"] = "Encerrada por"
    L["Entered another instance"] = "Entrou em outra instância"
    L["Exited instance"] = "Saiu da instância"
    L["Help: Dungeon & Raid Log"] = "Ajuda: Histórico de Masmorras e Raids"
    L["Help: Record Dungeon & Raid Log"] = "Ajuda: Registrar Masmorras e Raids"
    L["In Progress"] = "Em Andamento"
    L["Instance reset"] = "Instância reiniciada"
    L["Joined mid-run"] = "Entrou no meio"
    L["Keep Recording"] = "Continuar Registrando"
    L["Left early"] = "Saiu antes"
    L["Left group"] = "Saiu do grupo"
    L["Member left group"] = "Membro saiu do grupo"
    L["No matching dungeon or raid runs found."] = "Nenhuma masmorra ou raid correspondente encontrada."
    L["No started dungeons or raids recorded yet. Runs are logged automatically from the 1st enemy pulled."] = "Nenhuma masmorra ou raid iniciada foi registrada ainda. O registro começa automaticamente no 1º inimigo atacado."
    L["Open Dungeon & Raid Log"] = "Abrir Histórico de Masmorras"
    L["Open Log"] = "Abrir Histórico"
    L["Opens your searchable progression history of started dungeon and raid groups with all teammates and run times."] = "Abre seu histórico pesquisável de grupos de masmorras e raids iniciadas com todos os companheiros e o tempo total de cada uma."
    L["Passively records started dungeon and raid groups, teammate names, roles, bosses defeated, and total run time from the first enemy pulled until the run ends."] = "Registra passivamente grupos de masmorras e raids que realmente começaram, com o nome de cada membro, função, chefes derrotados e tempo total desde o primeiro inimigo atacado até o fim."
    L["Record started dungeon & raid groups (teammates & total time)"] = "Registrar grupos de masmorras e raids iniciadas (membros e tempo total)"
    L["Recorded Runs"] = "Registros Salvos"
    L["Recorded runs: %d / 120 (event-driven, zero lag)"] = "Registros salvos: %d / 120 (por eventos, zero lag)"
    L["Recording is paused. Click 'Recording: OFF' to re-enable."] = "Registro pausado. Clique em 'Registro: OFF' para reativar."
    L["Recording: OFF"] = "Registro: OFF"
    L["Recording: ON"] = "Registro: ON"
    L["Remove %s from your Dungeon & Raid Log?"] = "Remover %s do seu Histórico de Masmorras e Raids?"
    L["Search by dungeon, player or boss..."] = "Buscar por masmorra, jogador ou chefe..."
    L["Session ended"] = "Sessão encerrada"
    L["Shows started dungeons and raids with all teammate names, roles, bosses defeated, and total run time from the 1st enemy pulled."] = "Mostra masmorras e raids iniciadas com o nome de todos os membros, funções, chefes derrotados e o tempo total desde o 1º inimigo atacado."
    L["Solo / no teammates recorded"] = "Solo / sem companheiros registrados"
    L["Started / Ended"] = "Início / Fim"
    L["Teammates"] = "Companheiros"
    L["This Character"] = "Este Personagem"
    L["Ultra-lightweight: only runs when a dungeon/raid actually starts combat, with zero background polling. You can change this anytime in Settings -> Summary & Windows -> Dungeon & Raid Group Log."] = "Ultraleve: só ativa quando uma masmorra/raid realmente inicia combate, sem varreduras em segundo plano. Você pode mudar isso quando quiser em Configurações -> Resumo & Janelas -> Registro de Grupos de Masmorra e Raid."
    L["Uncheck to pause recording. Already recorded runs remain available in the Dungeon & Raid Log until you clear them."] = "Desmarque para pausar novos registros. As masmorras já salvas continuam disponíveis no histórico até você limpar."
    L["Press I to open Blizzard's Group Finder and apply directly on the official Browse tab."] = "Pressione I para abrir o Localizador de Grupos da Blizzard e candidatar-se diretamente na aba oficial Procurar."
    L["View anytime in /sc -> Dungeon & Raid Log (or /sc runs). Uses zero combat-log scanning and keeps up to 120 compact runs so PC impact stays negligible."] = "Consulte quando quiser em /sc -> Histórico de Masmorras (ou /sc runs). Não varre o registro de combate e guarda até 120 registros compactos para quase zero impacto no PC."
    L["You can also open this view anytime via '/sc runs' or from the Group tab inside the main SocialCentral window."] = "Você também pode abrir direto com '/sc runs' ou pela aba Grupo na janela principal do SocialCentral."
    L["Your first dungeon/raid group has been recorded! You can check who you ran with and how long each run took anytime via /sc (Dungeon & Raid Log). Would you like to keep recording future runs?"] = "Sua primeira masmorra/raid foi registrada! Você pode consultar com quem jogou e o tempo total de cada uma quando quiser em /sc (Histórico de Masmorras). Deseja continuar registrando as próximas?"
    L["waiting for 1st pull"] = "aguardando 1º combate"
    L["Create a Private Addon Room for synced group or friend chats."] = "Crie uma Sala Privada do Addon para conversas sincronizadas com grupo ou amigos."
    L["Displays the selected character's full profile and character management actions."] = "Exibe o perfil completo do personagem selecionado e ações de gerenciamento."
    L["Click 'Actions' to view the Web Armory link or remove an offline alt, and switch between 'Overview', 'Items', 'Gear', and 'Account' below."] = "Clique em 'Ações' para copiar o link da Armory ou remover um alt offline, e alterne entre 'Resumo', 'Itens', 'Equip.' e 'Conta' abaixo."
    L["Plays a live sample message preview beside your Minimap with expand and close-to-SC-icon animation."] = "Exibe uma amostra animada de mensagem ao lado do Minimapa com efeito de abertura e recolhimento ao ícone SC."
    L["You can also test specific channels anytime using '/sc preview whisper', 'bnet', 'group', or 'guild'."] = "Você também pode testar canais específicos quando quiser usando '/sc preview whisper', 'bnet', 'group' ou 'guild'."
    L["Copy Official Chat"] = "Copiar Chat Oficial"
    L["No chat messages captured yet on this chat window."] = "Nenhuma mensagem capturada ainda nesta janela de chat."
    L["Press Ctrl+C to copy recent chat lines."] = "Pressione Ctrl+C para copiar as linhas recentes do chat."
    L["Lv."] = "Nv."
    L["Official Window"] = "Janela Oficial"
    L["Click: Toggle features or disable here"] = "Clique: Alternar recursos ou desativar aqui"
    L["Tab 1 Mirror Bar"] = "Barra Espelho da Aba 1"
    L["On"] = "Ativo"
    L["Off"] = "Desligado"
    L["Show Official Tab 1 Mirror Bar"] = "Mostrar Barra Espelho Oficial da Aba 1"
    L["Official Chat"] = "Chat Oficial"
    L["Short Channels"] = "Canais Curtos"
    L["Sender Badges"] = "Tags de Jogador"
    L["Clickable URLs"] = "Links Clicáveis (URLs)"
    L["EditBox History"] = "Histórico da Barra"
    L["Fast Scroll"] = "Rolagem Rápida"
    L["Anti-Spam Shield"] = "Escudo Anti-Spam"
    L["Shorten public channel names"] = "Encurtar nomes de canais públicos"
    L["Show [Lv], [Main], [+]/[Avoid] tags"] = "Mostrar tags [Nv], [Main], [+]/[Evitar]"
    L["Remember typed chat history (EditBox)"] = "Lembrar histórico digitado no chat (EditBox)"
    L["Fast scroll (Shift/Ctrl + Wheel)"] = "Rolagem rápida (Shift/Ctrl + Roda do Mouse)"
    L["Hide Account-Ignored chat"] = "Ocultar chat de Ignorados da Conta"
    L["Public Chat Anti-Spam Shield"] = "Escudo Anti-Spam no Chat Público"
    L["Hide quick [SC] button here"] = "Ocultar botão rápido [SC] aqui"
    L["Official Chat [SC] button hidden. Re-enable anytime in Settings (/sc)."] = "Botão [SC] do Chat Oficial ocultado. Reative quando quiser em Configurações (/sc)."
    L["Disable Official Chat Enhancements"] = "Desativar Recursos no Chat Oficial"
    L["Official Chat enhancements disabled. Re-enable anytime in Settings (/sc)."] = "Recursos do Chat Oficial desativados. Reative quando quiser em Configurações (/sc)."
    L["Quick Select Alt Recipient attached to Blizzard's Mailbox."] = "Seletor rápido de destinatário Alt acoplado ao Correio oficial da Blizzard."
    L["Disable in this window"] = "Desativar nesta janela"
    L["Disabled in this window. Re-enable anytime in Settings (/sc)."] = "Desativado nesta janela. Reative quando quiser em Configurações (/sc)."
    L["Official Chat (ChatFrame)"] = "Chat Oficial (ChatFrame)"
    L["Help: Official Chat (ChatFrame)"] = "Ajuda: Chat Oficial (ChatFrame)"
    L["Master switch for SocialCentral features injected directly into Blizzard's official Chat windows (short channels, sender badges, Copy Chat, fast scroll, and [SC] button)."] = "Chave principal dos recursos do SocialCentral integrados diretamente às janelas oficiais de Chat da Blizzard (canais curtos, tags de remetente, Copiar Chat, rolagem rápida e botão [SC])."
    L["Uncheck here or click [SC] beside Chat -> 'Disable in this window' to keep Blizzard Chat 100% vanilla."] = "Desmarque aqui ou clique em [SC] ao lado do Chat -> 'Desativar nesta janela' para manter o Chat da Blizzard 100% padrão."
    L["Official Mailbox (Alts)"] = "Correio Oficial (Alts)"
    L["Help: Official Mailbox (Alts)"] = "Ajuda: Correio Oficial (Alts)"
    L["Attaches the 'Alts v' recipient selector and standardized [SC] quick toggle directly inside Blizzard's Send Mail window."] = "Acopla o seletor de destinatário 'Alts v' e o botão rápido padronizado [SC] diretamente dentro da janela de envio do Correio da Blizzard."
    L["Uncheck here or click [SC] beside the Mailbox field to keep Blizzard's Send Mail window completely unmodified."] = "Desmarque aqui ou clique em [SC] ao lado do campo de destinatário do Correio para manter o Correio da Blizzard sem modificações."
    L["Official Chat & Quick [SC] Controls"] = "Chat Oficial & Controles Rápidos [SC]"
    L["Help: Official Chat Enhancements"] = "Ajuda: Recursos no Chat Oficial"
    L["Controls SocialCentral enhancements directly inside Blizzard's official Chat windows (short channels, clickable sender tags, EditBox history, fast mouse wheel scroll, Copy Official Chat, and the quick [SC] control button)."] = "Controla os aprimoramentos do SocialCentral diretamente dentro das janelas oficiais de Chat da Blizzard (canais curtos, tags clicáveis de remetente, histórico do EditBox, rolagem rápida, Copiar Chat Oficial e o botão rápido [SC])."
    L["Every feature below can be toggled here or directly via the standardized [SC] button beside Blizzard's Official Chat, Mailbox, and Group Finder (I)."] = "Cada recurso abaixo pode ser alternado por aqui ou diretamente pelo botão padronizado [SC] ao lado do Chat Oficial, Correio e Localizador de Grupos (I)."
    L["Enable Official Chat Enhancements (ChatFrame)"] = "Ativar Aprimoramentos no Chat Oficial (ChatFrame)"
    L["Help: Master Official Chat Toggle"] = "Ajuda: Chave Principal do Chat Oficial"
    L["Master switch for SocialCentral features injected directly into Blizzard's official Chat windows."] = "Interruptor geral para os recursos do SocialCentral injetados diretamente nas janelas oficiais de Chat da Blizzard."
    L["Uncheck to return Blizzard's Chat frames to 100% vanilla while keeping all settings ready to re-enable anytime."] = "Desmarque para restaurar o Chat oficial ao comportamento 100% padrão preservando suas preferências para reativar depois."
    L["Show quick [SC] control button beside Official Chat"] = "Mostrar botão rápido [SC] ao lado do Chat Oficial"
    L["Help: Quick [SC] Chat Button"] = "Ajuda: Botão Rápido [SC] no Chat"
    L["Shows the standardized [SC] quick-menu button beside Blizzard's main Chat frame so you can toggle Short Channels, Sender Badges, History, or Copy Chat in 1 click."] = "Exibe o botão de menu rápido padronizado [SC] ao lado do Chat principal da Blizzard para alternar Canais Curtos, Tags, Histórico ou Copiar Chat em 1 clique."
    L["You can also right-click the button to hide it anytime and re-enable it right here."] = "Você também pode clicar com o botão direito para ocultar o botão quando quiser e reativá-lo por aqui."
    L["Shorten public channel names in Official Chat ([LFG], [Trade], [Defense])"] = "Encurtar nomes de canais públicos no Chat Oficial ([LFG], [Comércio], [Defesa])"
    L["Help: Short Official Channels"] = "Ajuda: Canais Curtos no Chat Oficial"
    L["Replaces verbose channel prefixes such as [LookingForGroup] or [General - Stormwind City] with compact [LFG], [General], and [Defense] tags inside official chat."] = "Substitui prefixos longos como [ProcurandoGrupo] ou [Geral - Ventobravo] por siglas compactas como [LFG], [Geral] e [Defesa] no chat oficial."
    L["Applies cleanly via Blizzard's message filter with zero UI taint."] = "Aplicado de forma limpa via filtro oficial de mensagens da Blizzard sem risco de taint."
    L["Show [Lv], [Main], and [+]/[AVOID] sender tags in Official Chat"] = "Mostrar tags [Nv], [Main] e [+]/[EVITAR] dos remetentes no Chat Oficial"
    L["Help: Official Sender Badges"] = "Ajuda: Tags de Remetente no Chat Oficial"
    L["Prepends cached [Lv.X], linked [Main], and saved [+] Good / [AVOID] reputation badges beside known players directly in Blizzard's chat window."] = "Adiciona antes do remetente as tags salvas [Nv.X], [Main] vinculado e reputação [+] Bom / [EVITAR] para jogadores conhecidos direto no chat oficial."
    L["Reads strictly from already-known guild, friend, or Social notes memory (zero automatic /who queries)."] = "Lê estritamente dados já conhecidos de guilda, amigos ou notas sociais (zero consultas /who automáticas)."
    L["Remember typed Official Chat history across /reload (Alt+Up / Down)"] = "Lembrar histórico digitado no Chat Oficial após /reload (Alt+Cima / Baixo)"
    L["Help: Persistent EditBox History"] = "Ajuda: Histórico Persistente do EditBox"
    L["Saves your last 25 sent lines per character (excluding Battle.net tokens for privacy) so you can recall them with Up/Down arrows even after reloading UI."] = "Salva suas últimas 25 linhas enviadas por personagem (ignorando identificadores Battle.net por privacidade) para recuperar com as setas mesmo após recarregar a UI."
    L["Uncheck anytime to stop saving chat bar history across reloads."] = "Desmarque quando quiser para interromper o salvamento do histórico entre recarregamentos."
    L["Fast scroll in Official Chat (Shift+Wheel top/bottom, Ctrl+Wheel page)"] = "Rolagem rápida no Chat Oficial (Shift+Roda topo/base, Ctrl+Roda página)"
    L["Help: Fast Official Chat Scroll"] = "Ajuda: Rolagem Rápida no Chat Oficial"
    L["Lets you jump straight to the top or bottom of official chat with Shift+MouseWheel, or scroll 4 lines at a time with Ctrl+MouseWheel."] = "Permite pular direto para o topo ou rodapé do chat oficial com Shift+Roda do Mouse, ou rolar 4 linhas por vez com Ctrl+Roda do Mouse."
    L["Disable anytime if you prefer standard single-line WoW mousewheel scrolling."] = "Desative quando quiser se preferir a rolagem padrão de 1 linha por vez do WoW."
    L["Help: Copy Official Chat"] = "Ajuda: Copiar Chat Oficial"
    L["Opens a clean Ctrl+C copy window containing the most recent lines rendered in Blizzard's main Official Chat window."] = "Abre uma janela limpa pronta para Ctrl+C com as mensagens mais recentes exibidas no Chat Oficial principal da Blizzard."
    L["You can also use '/sc copychat' (or '/sc copychat 80' to choose how many lines) or click the [SC] button beside Official Chat."] = "Você também pode usar '/sc copychat' (ou '/sc copychat 80' para escolher quantas linhas copiar) ou clicar no botão [SC] ao lado do Chat Oficial."
    L["Manual Chat"] = "Chat manual"
    L["Manual Chat (SocialCentral)"] = "Chat manual (SocialCentral)"
    L["Shared Library"] = "Biblioteca compartilhada"
    L["Origin: %s"] = "Origem: %s"
    L["Identify error origin in chat"] = "Identificar origem de erros no chat"
    L["Identify addon origin on chat errors ([Origin: Addon])"] = "Identificar qual addon gerou erros no chat ([Origem: Addon])"
    L["Help: Chat Error Origin Identifier"] = "Ajuda: Identificador de Origem de Erros no Chat"
    L["Correlates unblocked yellow system errors in Official Chat (such as offline player whispers, missing group/guild, or message throttles) with recent addon or manual chat activity and appends [Origin: Addon] to show what triggered the error."] = "Relaciona erros amarelos do sistema exibidos no Chat Oficial (como sussurros para jogadores offline, avisos de grupo/guilda ou limite de envio) com consultas recentes de addons ou envios manuais, adicionando [Origem: Addon] na linha."
    L["Keep checked to immediately see which addon is causing 'No player named...' spam or chat errors. SocialCentral's own silent presence checks remain automatically hidden."] = "Mantenha marcado para ver na hora qual addon está causando spam de 'Nenhum jogador de nome...' ou outros erros. As verificações silenciosas do próprio SocialCentral continuam ocultas automaticamente."
    L["Show Official Tab 1 Mirror Bar in Group Finder (I)"] = "Mostrar Barra Espelho Oficial da Aba 1 no Localizador de Grupos (I)"
    L["Help: Official LFG Tab 1 Mirror Bar"] = "Ajuda: Barra Espelho Oficial na Aba 1 do Localizador (I)"
    L["Displays the compact SocialCentral quick-mirror bar and standardized [SC] control button below Blizzard's Group Finder (I) Browse tab."] = "Exibe a barra compacta de espelho rápido do SocialCentral e o botão padronizado [SC] abaixo da aba Explorar do Localizador de Grupos (I) da Blizzard."
    L["You can toggle this anytime from here or via the [SC] button directly on Blizzard's Group Finder bar."] = "Você pode ativar ou desativar aqui ou direto pelo botão [SC] na própria barra do Localizador de Grupos da Blizzard."
