    L["Asking online guildmates who can craft '%s'..."] = "Consultando colegas da guilda online que fabricam '%s'..."
    L["Sends a lightweight recipe lookup to online guildmates using SocialCentral so crafters who know your typed item appear here and in tooltips."] = "Envia uma consulta leve aos colegas da guilda online com SocialCentral para listar aqui e nos tooltips quem sabe fazer o item digitado."
    L["Help: Ask Guild Recipe Search"] = "Ajuda: Consultar Receitas na Guilda"
    L["Queries online SocialCentral guildmates cleanly (8s cooldown, opt-in Guild Sync) to find who knows the exact item or recipe you typed."] = "Consulta membros online da guilda com SocialCentral de forma segura (recarga de 8s, exige Sync da Guilda) para descobrir quem possui a receita pesquisada."
    L["Type e.g. 'Crusader' or 'Flask', click 'Ask Guild' (or press Enter), then click any matching crafter to send a pre-filled Craft Request whisper."] = "Digite ex.: 'Cruzado' ou 'Frasco', clique em 'Consultar Guilda' (ou aperte Enter) e clique em qualquer artesão para enviar o Pedido de Craft."
