    L["Passively catalogs each character's learned recipes when opening Blizzard's Profession window and attaches the standardized [SC] quick control button."] = "Cataloga passivamente todas as receitas aprendidas ao abrir a janela oficial de Profissão da Blizzard e acopla o botão rápido padronizado [SC]."
    L["Uncheck here or click [SC] inside any Profession window -> 'Disable in this window' to stop indexing recipes and hide the button."] = "Desmarque aqui ou clique em [SC] dentro da janela de Profissão -> 'Desativar nesta janela' para parar a indexação e ocultar o botão."
    L["Show 'Craftable by Alt / Guild' and Recipe hints in tooltips"] = "Mostrar 'Craftável por Alt / Guilda' e avisos de Receita nos tooltips"
    L["Help: Craftable & Recipe Tooltips"] = "Ajuda: Tooltips de Craft & Receitas"
    L["Shows directly on Blizzard item tooltips which Alt or Guildmate can craft the hovered item, and whether a hovered Recipe scroll is already learned or needed by an Alt."] = "Exibe direto no tooltip oficial de qualquer item qual Alt ou colega da Guilda sabe fabricá-lo, e se uma Receita/Fórmula já foi aprendida ou falta em algum Alt."
    L["Open each character's Profession window once so SocialCentral indexes their recipes for Auction House, Bags, Mail, and Chat links."] = "Abra a janela de Profissão uma vez em cada personagem para o SocialCentral usar suas receitas na Casa de Leilões, Bolsas, Correio e links do Chat."
    L["Answer online Guild Recipe Searches (requires Clan Sync)"] = "Responder buscas de receitas da Guilda online (requer Sync da Guilda)"
    L["Help: Guild Recipe Replies"] = "Ajuda: Respostas de Receita na Guilda"
    L["Allows your character to reply quietly (Trickle rate-limited) when a guildmate clicks 'Ask Guild' inside Guild Professions (J) looking for a learned recipe."] = "Permite ao seu personagem responder silenciosamente (com proteção anti-flood) quando um colega clicar em 'Consultar Guilda' em Profissões (J) procurando uma receita."
    L["Requires 'Enable Clan guild sync (opt-in)' above; never sends replies in combat or floods guild chat."] = "Requer 'Ativar sincronização da Guilda (opt-in)' acima; nunca envia respostas em combate nem faz spam no chat."
    L["Alert in Official Chat when Watched Dungeon or Raid groups appear"] = "Alertar no Chat Oficial quando surgirem grupos das Masmorras ou Raids Vigiadas"
