    L["Keep checked to focus on groups you can actually join, or uncheck anytime from Settings or the Group Finder [SC] button."] = "Mantenha marcado para focar apenas em grupos onde você realmente cabe, ou desmarque quando quiser em Configurações ou no botão [SC] do Localizador."
