    L["Click here to type..."] = "Clique aqui para digitar..."
    L["Quick Reply Guide"] = "Guia da Janela Rápida"
    L["Step %d/%d"] = "Passo %d/%d"
    L["Next"] = "Próximo"
    L["Got it!"] = "Entendi!"
    L["Link Item"] = "Linkar Item"
    L["Try On"] = "Provar"
    L["Lit = Typing"] = "Acesa = Digitando"
    L["Dark = Game Keys Free"] = "Escura = Teclas Livres"
    L["Draft saved"] = "Rascunho salvo"
    L["Closing in %ds"] = "Fechando em %ds"
    L["Saved draft (%d) — Click to resume"] = "Rascunho salvo (%d) — Clique para continuar"
    L["Show Threads"] = "Ver Conversas"
    L["Focus Chat"] = "Focar Chat"
    L["Quick Reply Popup (Minimap)"] = "Janela Rápida de Resposta (Minimapa)"
    L["Open Quick Reply popup when clicking Minimap with pending messages"] = "Abrir Janela Rápida ao clicar no Minimapa com mensagens pendentes"
    L["Help: Quick Reply Popup"] = "Ajuda: Janela Rápida de Resposta"
    L["When enabled, clicking the Minimap or Official Chat shortcut jumps directly to your newest unread message (or toggles Quick Reply when caught up). Clicking chat tabs keeps your keys free; press ENTER or click the typing field to start typing, and sending a message releases focus automatically just like Official Chat."] = "Quando ativo, clicar no ícone do Minimapa ou do Chat Oficial pula direto para a mensagem mais recente não lida (ou abre/fecha a Janela Rápida quando não houver pendências). Clicar nas abas mantém suas teclas livres; aperte ENTER ou clique no campo para começar a digitar, e ao enviar uma mensagem o foco é liberado automaticamente como no Chat Oficial."
    L["You can drag Quick Reply anywhere while unlocked, lock its position with the Padlock, place it over Official Chat with the Map button, and reopen straight to your last sent chat using ENTER even during combat."] = "Você pode arrastar a Janela Rápida quando destravada, travar com o Cadeado, encaixar sobre o Chat Oficial pelo ícone do Mapa e reabrir direto no último chat enviado apertando ENTER até em combate."
    L["Auto-close Quick Reply on inactivity (saves draft)"] = "Fechar Janela Rápida por inatividade (salva rascunho)"
    L["Help: Quick Reply Auto-Close & Drafts"] = "Ajuda: Fechamento Automático e Rascunhos"
    L["Off by default so Quick Reply stays always open. Enable if you prefer Quick Reply to close automatically after inactivity while keeping your typed message saved as a draft."] = "Desativado por padrão para a Janela Rápida ficar sempre visível. Marque se preferir que ela feche sozinha após inatividade, mantendo o texto salvo como rascunho."
    L["Click the Minimap icon anytime to reopen with your draft restored, or toggle Always Show / Auto-close directly in the Quick Reply header."] = "Clique no ícone do Minimapa quando quiser para reabrir com o rascunho restaurado, ou alterne Sempre Mostrar / Auto-fechar direto no cabeçalho da Janela Rápida."
    L["Quick Reply auto-close delay (seconds):"] = "Tempo para fechar a Janela Rápida (segundos):"
    L["Help: Quick Reply Auto-Close Delay"] = "Ajuda: Tempo de Fechamento da Janela Rápida"
    L["Sets how many seconds the Quick Reply popup waits after inactivity or outside interaction before closing automatically (when Auto-Close is enabled)."] = "Define quantos segundos a Janela Rápida aguarda após inatividade ou interação fora dela antes de fechar automaticamente (quando o fechamento automático estiver ativo)."
    L["You can also change this timer or keep Quick Reply always open directly from the button in the Quick Reply window header."] = "Você também pode mudar esse tempo ou manter a Janela Rápida sempre aberta diretamente pelo botão no cabeçalho da janela."
    L["Make Quick Reply transparent after inactivity"] = "Deixar Janela Rápida transparente após inatividade"
    L["Help: Quick Reply Idle Transparency"] = "Ajuda: Transparência por Inatividade da Janela Rápida"
    L["Keeps Quick Reply visible at all times while automatically fading it to a gentle transparent state after the configured seconds of inactivity."] = "Mantém a Janela Rápida sempre visível na tela e deixa a janela suavemente transparente após os segundos de inatividade configurados."
    L["Hovering, clicking, or typing immediately restores full visibility. Uncheck if you want Quick Reply to remain fully opaque at all times."] = "Passar o mouse, clicar ou digitar devolve a visibilidade total na hora. Desmarque se preferir que a Janela Rápida fique sempre totalmente opaca."
    L["Seconds before Quick Reply becomes transparent:"] = "Segundos para a Janela Rápida ficar transparente:"
    L["Help: Quick Reply Transparency Delay"] = "Ajuda: Tempo para Transparência da Janela Rápida"
    L["Sets how many seconds Quick Reply waits without interaction before turning transparent (15 seconds by default)."] = "Define quantos segundos a Janela Rápida espera sem interação antes de ficar transparente (15 segundos por padrão)."
    L["You can also adjust this timer or keep Quick Reply fully opaque directly from the timer button in the Quick Reply header."] = "Você também pode ajustar esses segundos ou manter a Janela Rápida totalmente opaca direto pelo botão de tempo no cabeçalho da Janela Rápida."
    L["Auto-close: %d seconds"] = "Auto-fechar: %d segundos"
    L["Fade: %ds"] = "Transp.: %ds"
    L["Transparent: %ds"] = "Transparente: %ds"
    L["Opaque"] = "Opaca"
    L["Always Open (Opaque)"] = "Sempre Aberta (Opaca)"
    L["Transparency After Inactivity"] = "Transparência Após Inatividade"
    L["Never become transparent (always opaque)"] = "Nunca ficar transparente (sempre opaca)"
    L["Window Visibility & Auto-Close"] = "Visibilidade e Fechamento Automático"
    L["Always show Quick Reply (Default)"] = "Sempre mostrar a Janela Rápida (Padrão)"
    L["Auto-close after inactivity..."] = "Fechar automaticamente após inatividade..."
    L["Hide Quick Reply during combat"] = "Sumir com a Janela Rápida em combate"
    L["Always Open: ESC releases typing focus and keeps this window visible. Click X to close until reopened."] = "Sempre Aberta: ESC libera o foco de digitação e mantém a janela visível. Clique no X para fechar até reabrir."
    L["Visibility & Transparency"] = "Visibilidade e Transparência"
    L["Stays visible at all times and becomes transparent after %d seconds of inactivity (returns to 100%% on hover, click, or typing)."] = "Fica sempre visível e se torna transparente após %d segundos sem interação (volta a 100%% ao passar o mouse, clicar ou digitar)."
    L["Stays visible and fully opaque at all times until you close it manually with X."] = "Fica sempre visível e totalmente opaca até você fechá-la manualmente pelo X."
    L["Dungeon/Raid Mode: Stays open even if you press ESC or click outside, and only closes when you click X or turn off Dungeon Mode."] = "Modo Masmorra/Raide: Fica aberta mesmo apertando ESC ou clicando fora e só fecha ao clicar no X ou desativar o Modo Masmorra."
    L["Combat hiding: ON (disappears during combat until it ends or you press ENTER)."] = "Sumir em combate: ATIVO (desaparece durante o combate até acabar ou você apertar ENTER)."
    L["Combat hiding: OFF (stays visible during combat)."] = "Sumir em combate: DESATIVADO (continua visível em combate)."
    L["Click to set transparency seconds, auto-close, or combat hiding."] = "Clique para definir os segundos de transparência, fechamento automático ou sumir em combate."
    L["Tank · Healer · DPS Role"] = "Função: Tank · Healer · DPS"
    L["Main Tank · Main Assist · Master Looter"] = "Tank Principal · Assistente Principal · Mestre de Saque"
    L["Confirmed online (Group, Friends, Guild, BNet, Watchlist)"] = "Online confirmado (Grupo, Amigos, Guilda, BNet, Watchlist)"
    L["Confirmed offline in Friends, Guild, or Watchlist"] = "Offline confirmado nos Amigos, Guilda ou Watchlist"
    L["Unverified History"] = "Histórico não verificado"
    L["Outside Friends/Guild — right-click to add to Watchlist (/who)"] = "Fora de Amigos/Guilda — clique direito para vigiar na Watchlist (/who)"
    L["Favorite · SocialCentral · Good Partner · Avoid"] = "Favorito · Usa SocialCentral · Bom Parceiro · Evitar"
    L["Chat Colors"] = "Cores dos Chats"
    L["Favorite · SocialCentral · Battle.net"] = "Favorito · Usa SocialCentral · Battle.net"
    L["Alliance / Horde Faction Tag"] = "Tag de Facção: Aliança / Horda"
    L["Live Guild member online status"] = "Status online em tempo real na Guilda"
    L["Favorite · SocialCentral · Away · Busy"] = "Favorito · Usa SocialCentral · Ausente · Ocupado"
    L["Login Alerts"] = "Alertas de Login"
    L["Bell ON = Notify when online"] = "Sino ligado = Avisar quando entrar online"
    L["Green = Online · Grey = Offline · Amber = /who pending"] = "Verde = Online · Cinza = Offline · Âmbar = Pendente de /who"
    L["Favorite · SocialCentral · Login Alerts"] = "Favorito · Usa SocialCentral · Alertas de Login"
    L["%d seconds (Default)"] = "%d segundos (Padrão)"
    L["%d seconds"] = "%d segundos"
    L["Closes this window automatically after %d seconds of inactivity or when you interact outside it (your typed draft is preserved)."] = "Fecha esta janela automaticamente após %d segundos de inatividade ou ao interagir fora dela (o texto digitado fica salvo como rascunho)."
    L["Dock Quick Reply over Official WoW Chat (exact size)"] = "Encaixar Janela Rápida sobre o Chat Oficial (mesmo tamanho)"
    L["Help: Dock Quick Reply Over Official Chat"] = "Ajuda: Encaixar Janela Rápida no Chat Oficial"
    L["Automatically places the Quick Reply window directly on top of Blizzard's main chat window, matching its exact current width and height."] = "Posiciona a Janela Rápida automaticamente sobre a janela principal do chat da Blizzard, assumindo exatamente a largura e a altura atuais dela."
    L["Uncheck if you prefer to place Quick Reply freely anywhere else on screen. You can also drag Quick Reply anytime while unlocked or click the Place over Official Chat button in its title bar."] = "Desmarque se preferir posicionar a Janela Rápida livremente em outro lugar da tela. Você também pode arrastá-la a qualquer momento quando destravada ou clicar no botão de colocar sobre o Chat Oficial na barra superior."
    L["Lock Quick Reply window position"] = "Travar posição da Janela Rápida"
    L["Help: Lock Quick Reply Position"] = "Ajuda: Travar Posição da Janela Rápida"
    L["Prevents moving the Quick Reply window accidentally when dragging or clicking near its edges."] = "Impede que a Janela Rápida seja movida sem querer ao arrastar ou clicar perto das bordas."
    L["Open Quick Reply on ENTER when messages are pending"] = "Abrir Janela Rápida com ENTER quando houver mensagens pendentes"
    L["Help: Open Quick Reply on ENTER"] = "Ajuda: Abrir Janela Rápida com ENTER"
    L["When you have unread Minimap notifications, saved drafts, or recently sent a message, pressing ENTER jumps Quick Reply straight to where you sent your last message (even during combat, pausing fade while you type)."] = "Quando houver notificações no Minimapa, rascunhos ou uma mensagem recente, apertar ENTER abre a Janela Rápida direto no chat onde você enviou a última mensagem (mesmo em combate, pausando a transparência enquanto você digita)."
    L["Reopening from the Minimap or Chat button preserves your current tab (switching only when you click a notification). During combat, Blizzard's bar receives your ready message for one final ENTER confirmation; outside combat, one ENTER sends directly."] = "Reabrir pelo Minimapa ou botão do chat mantém a aba atual (trocando só ao clicar em uma notificação). Em combate, a barra oficial recebe a mensagem pronta para você confirmar com um ENTER final; fora de combate, um ENTER já envia direto."
    L["Hide Group chat (Party / Raid / Instance) in Official Chat (keep in SocialCentral)"] = "Ocultar chat de Grupo (Grupo / Raide / Instância) no Chat Oficial (manter no SocialCentral)"
    L["Help: Hide Group in Official Chat"] = "Ajuda: Ocultar Grupo no Chat Oficial"
    L["Keeps Party, Raid, and Instance messages out of Blizzard's Official Chat window (leaving it clean for server shutdown warnings, system alerts, and loot) while continuing to receive and reply normally inside SocialCentral."] = "Impede que mensagens de Grupo, Raide e Instância apareçam no Chat Oficial da Blizzard (deixando-o limpo para avisos de manutenção, servidor e saques), mantendo o recebimento e as respostas normais no SocialCentral."
    L["Pair with Quick Reply docked over Official Chat + ENTER to read and answer group messages cleanly without cluttering Blizzard's window."] = "Combine com a Janela Rápida encaixada sobre o Chat Oficial + ENTER para ler e responder mensagens de grupo de forma limpa, sem misturar com avisos do servidor."
    L["Hide Guild & Officer chat in Official Chat (keep in SocialCentral)"] = "Ocultar chat da Guilda e Oficial no Chat Oficial (manter no SocialCentral)"
    L["Help: Hide Guild in Official Chat"] = "Ajuda: Ocultar Guilda no Chat Oficial"
    L["Keeps Guild and Officer messages out of Blizzard's Official Chat window while continuing to receive and reply normally inside SocialCentral."] = "Impede que mensagens da Guilda e de Oficiais apareçam no Chat Oficial da Blizzard, mantendo tudo funcionando normalmente dentro do SocialCentral."
    L["Check anytime to keep Blizzard's chat window dedicated solely to server and system announcements."] = "Marque quando quiser para deixar a janela oficial da Blizzard dedicada apenas a avisos do servidor e do sistema."
    L["Hide Whispers & Battle.net in Official Chat (keep in SocialCentral)"] = "Ocultar Sussurros e Battle.net no Chat Oficial (manter no SocialCentral)"
    L["Help: Hide Whispers in Official Chat"] = "Ajuda: Ocultar Sussurros no Chat Oficial"
    L["Keeps character Whispers and Battle.net friend messages out of Blizzard's Official Chat window while continuing to receive and reply normally inside SocialCentral."] = "Impede que Sussurros e mensagens de amigos Battle.net apareçam no Chat Oficial da Blizzard, mantendo tudo funcionando normalmente dentro do SocialCentral."
    L["Check anytime to handle all personal whispers strictly through Quick Reply and Conversations."] = "Marque quando quiser para lidar com todos os sussurros apenas pela Janela Rápida e por Conversas."
    L["Hide in Official Chat (Keep in SC)"] = "Ocultar no Chat Oficial (Manter no SC)"
    L["Group (Party / Raid / Instance)"] = "Grupo (Grupo / Raide / Instância)"
    L["Guild & Officer"] = "Guilda e Oficial"
    L["Whispers & Battle.net"] = "Sussurros e Battle.net"
    L["Previous tabs page"] = "Página anterior de abas"
    L["Next tabs page"] = "Próxima página de abas"
    L["Quick Reply notifications: Whispers & SocialCentral Chat"] = "Notificações na Janela Rápida: Sussurros e Chat SocialCentral"
    L["Help: Quick Reply Whispers"] = "Ajuda: Janela Rápida para Sussurros"
    L["Marks incoming personal Whispers and SocialCentral direct/room messages as pending notifications for the Minimap Quick Reply popup."] = "Marca Sussurros pessoais e mensagens diretas/salas do SocialCentral como notificações pendentes para a Janela Rápida do Minimapa."
    L["Leave checked to reply to whispers in one click from the Minimap without opening the full Conversations tab."] = "Deixe marcado para responder sussurros em 1 clique pelo Minimapa sem abrir a janela completa de Conversas."
    L["Quick Reply notifications: Battle.net Messages"] = "Notificações na Janela Rápida: Mensagens Battle.net"
    L["Help: Quick Reply Battle.net"] = "Ajuda: Janela Rápida para Battle.net"
    L["Marks incoming Battle.net friend messages as pending notifications for the Minimap Quick Reply popup."] = "Marca mensagens recebidas de amigos Battle.net como notificações pendentes para a Janela Rápida do Minimapa."
    L["Uncheck if you prefer to answer Battle.net messages only from Blizzard chat or the full Conversations tab."] = "Desmarque se preferir responder mensagens Battle.net apenas pelo chat oficial ou pela aba completa de Conversas."
    L["Quick Reply notifications: Party / Instance Chat"] = "Notificações na Janela Rápida: Chat de Grupo / Instância"
    L["Help: Quick Reply Party"] = "Ajuda: Janela Rápida para Grupo"
    L["Marks incoming Party and Instance chat messages as pending notifications so you can reply quickly via the Minimap icon."] = "Marca mensagens do chat de Grupo e Instância como notificações pendentes para responder rapidamente pelo ícone do Minimapa."
    L["Uncheck if you prefer to read Party chat solely in Blizzard's chat window."] = "Desmarque se preferir acompanhar o chat de Grupo apenas na janela oficial do WoW."
    L["Quick Reply notifications: Raid Chat"] = "Notificações na Janela Rápida: Chat de Raide"
    L["Help: Quick Reply Raid"] = "Ajuda: Janela Rápida para Raide"
    L["Marks incoming Raid chat messages as pending notifications for the Minimap Quick Reply popup and displays a separate orange Raid circle on the Minimap."] = "Marca mensagens do chat de Raide como notificações pendentes para a Janela Rápida e exibe um círculo laranja separado de Raide no Minimapa."
    L["Enabled by default so Raid messages show an orange Raid circle on the Minimap and can be answered via Quick Reply; uncheck in noisy raids if preferred."] = "Ativado por padrão para que mensagens de Raide mostrem um círculo laranja separado no Minimapa e possam ser respondidas pela Janela Rápida; desmarque se preferir silenciar raides movimentadas."
    L["Quick Reply notifications: Guild & Officer Chat"] = "Notificações na Janela Rápida: Chat da Guilda e Oficial"
    L["Help: Quick Reply Guild"] = "Ajuda: Janela Rápida para Guilda"
    L["Marks incoming Guild and Officer chat messages as pending notifications for the Minimap Quick Reply popup."] = "Marca mensagens da Guilda e Oficiais como notificações pendentes para a Janela Rápida do Minimapa."
    L["Off by default for busy guilds; enable if you want Guild chat to trigger the Minimap Quick Reply popup."] = "Desligado por padrão para guildas muito movimentadas; ative se quiser responder à Guilda pela Janela Rápida do Minimapa."
    L["Help: Quick Reply Say & Yell Logs"] = "Ajuda: Registros de Dizer e Gritar"
    L["Help: Quick Reply Say & Yell Alerts"] = "Ajuda: Alertas de Dizer e Gritar"
    L["Track login alerts, zone updates, and status via safe /who."] = "Monitore alertas de login, mudanças de zona e status via /who seguro."
    L["Already monitored on your Watchlist."] = "Este jogador já está sendo monitorado na sua Watchlist."
    L["Open player menu (Favorite, Whisper, Invite, Folder, Watchlist, Ignore)."] = "Abrir menu completo do jogador (Favoritar, Sussurrar, Convidar, Pasta, Watchlist, Ignorar)."
    L["Starts a Ready Check for your party or raid."] = "Inicia uma verificação de prontidão (Ready Check) para o grupo ou raide."
    L["Saved favorites: %d"] = "Favoritos salvos: %d"
    L["Groups"] = "Grupos"
    L["Message Notifications (By Type)"] = "Notificações de Mensagens (Por Tipo)"
    L["Chat Sounds (By Type)"] = "Sons do Chat (Por Tipo)"
    L["Auto-Hide Previews In:"] = "Ocultar Prévias Automaticamente Em:"
    L["Battlegrounds & Arenas"] = "Campos de Batalha & Arenas"
    L["Demoted"] = "Rebaixado"
    L["History Limit"] = "Limite de Registros"
    L["Keep: %d"] = "Manter: %d"
    L["%d entries"] = "%d registros"
    L["Copy History"] = "Copiar Histórico"
    L["Clear History"] = "Limpar Histórico"
    L["Are you sure you want to clear all %d saved guild roster history entries?"] = "Tem certeza que deseja apagar todos os %d registros salvos do histórico do elenco da guilda?"
    L["Help: Guild Roster History Limit"] = "Ajuda: Limite do Histórico da Guilda"
    L["Controls how many recent guild joins, departures, and rank changes are stored locally (up to 500 lightweight entries, ~60 days retention)."] = "Define quantas entradas, saídas e mudanças de cargo recentes da guilda ficam salvas localmente (até 500 registros leves, retenção de 60 dias)."
    L["Pick a limit from the menu without impacting game performance; older entries are trimmed automatically."] = "Escolha o limite no menu sem pesar no desempenho do jogo; os registros mais antigos são descartados automaticamente."
    L["%d joined · %d left · %d rank"] = "%d entraram · %d saíram · %d cargos"
    L["Search..."] = "Buscar..."
    L["Legend"] = "Legendas"
    L["Icon Legend"] = "Legenda dos Ícones"
    L["Showing Offline"] = "Mostrando Offline"
    L["Click to show offline players"] = "Clique para mostrar também jogadores Offline."
    L["Click to show online players only"] = "Clique para ver somente jogadores Online."
    L["Green = Online Only · Red = Showing Offline"] = "Verde = Só Online · Vermelho = Mostrando Offline"
    L["New Messages"] = "Novas Mensagens"
    L["Recent Notifications"] = "Avisos Recentes"
    L["No recent notifications."] = "Nenhum aviso recente."
    L["Focus Mode Timer"] = "Tempo do Modo Foco"
    L["For 30 minutes"] = "Por 30 minutos"
    L["For 1 hour"] = "Por 1 hora"
    L["Until leaving instance"] = "Até sair da instância"
    L["Until I turn it off"] = "Até eu desligar"
    L["Turn Off Do Not Disturb"] = "Desligar Não Perturbe"
    L["Focus Mode Ended"] = "Modo Foco Encerrado"
    L["You have %d unread messages."] = "Você tem %d mensagens não lidas."
    L["Focus Mode ended — you have %d unread messages."] = "Modo Foco encerrado — você tem %d mensagens não lidas."
    L["WoW /dnd (Busy)"] = "WoW /dnd (Ocupado)"
    L["Allow Favorites through Focus Mode & Do Not Disturb"] = "Permitir Favoritos mesmo no Modo Foco e Não Perturbe"
    L["Help: Allow Favorites in Focus Mode"] = "Ajuda: Permitir Favoritos no Modo Foco"
    L["Allows incoming whispers, notifications, and chimes from friends marked as Favorite in SocialCentral even while Focus Mode or Do Not Disturb is active."] = "Permite que sussurros, alertas e sons de amigos marcados como Favoritos no SocialCentral apareçam mesmo com o Modo Foco ou Não Perturbe ativo."
    L["Uncheck to silence everyone without exception during Focus Mode."] = "Desmarque para silenciar todo mundo sem exceções durante o Modo Foco."
    L["Sync Focus Mode automatically with WoW /dnd (Busy) status"] = "Sincronizar Modo Foco automaticamente com /dnd (Ocupado) do WoW"
    L["Help: Sync with WoW /dnd"] = "Ajuda: Sincronizar com /dnd do WoW"
    L["Automatically pauses SocialCentral popups and chimes whenever your character is marked Busy (/dnd) in World of Warcraft."] = "Pausa automaticamente os avisos e sons do SocialCentral sempre que seu personagem estiver marcado como Ocupado (/dnd) no jogo."
    L["Type /dnd in chat again to clear your Busy status and resume notifications."] = "Digite /dnd no chat novamente para sair do modo Ocupado e retomar os avisos."
    L["Message Actions"] = "Ações da Mensagem"
    L["Click to quote, copy, or save to notes."] = "Clique para citar, copiar ou salvar nas notas."
    L["Whisper in Quick Reply"] = "Sussurrar na Resposta Rápida"
    L["Hold Shift to compare"] = "Segure Shift para comparar"
    L["Click to view · Shift+Click to link"] = "Clique para ver · Shift+Clique para linkar"
    L["Save Guild & Officer chat history across reloads/logins"] = "Salvar histórico do chat da Guilda e Oficiais após /reload e relogar"
    L["Help: Save Guild Chat History"] = "Ajuda: Salvar Histórico do Chat da Guilda"
    L["Keeps recent Guild and Officer chat messages saved locally so you can still read what happened before a /reload, disconnect, or relog."] = "Mantém as mensagens recentes do chat da Guilda e de Oficiais salvas localmente para você continuar vendo a conversa mesmo após /reload, queda ou relogar."
    L["Enabled by default (300 lines). Uncheck if you prefer Guild chat to reset on every reload or login."] = "Ativado por padrão (300 linhas). Desmarque se preferir que o chat da Guilda reinicie a cada reload ou entrada no jogo."
    L["Saved Guild & Officer chat lines"] = "Linhas salvas no chat da Guilda e Oficiais"
    L["Help: Guild Chat History Limit"] = "Ajuda: Limite de Histórico do Chat da Guilda"
    L["Defines how many recent messages (50 to 2000 lines, default 300; capped at 100 MB text) are kept saved per Guild and Officer channel across reloads and logins."] = "Define quantas mensagens recentes (50 a 2000 linhas, padrão 300; limite global de 100 MB em texto) ficam salvas nos canais de Guilda e Oficiais entre reloads e logins."
    L["Use '-' and '+' in steps of 50. Requires 'Save Guild & Officer chat history across reloads/logins' to be checked."] = "Use '-' e '+' de 50 em 50. Exige que 'Salvar histórico do chat da Guilda e Oficiais após /reload e relogar' esteja marcado."
    L["Save General, Private Rooms, Alliance & Mentions history across reloads/logins"] = "Salvar histórico de Geral, Salas Privadas, Aliança e Menções após /reload e relogar"
    L["Help: Save General Conversations History"] = "Ajuda: Salvar Histórico Geral de Conversas"
    L["Keeps recent messages from General chat, Private Rooms, Alliance Chat, and the Mentions Radar saved locally across /reload and logins (protected by an automatic 100 MB text quota)."] = "Mantém as mensagens recentes do chat Geral, Salas Privadas, Chat da Aliança e Radar de Menções salvas localmente entre /reload e logins (protegido por cota automática de 100 MB só em texto)."
    L["Enabled by default (300 lines). Uncheck if you prefer General, Private Rooms, Alliance, and Mentions to reset each session."] = "Ativado por padrão (300 linhas). Desmarque se preferir que Geral, Salas Privadas, Aliança e Menções reiniciem a cada sessão."
    L["Save Party, Raid & Instance chat history across reloads/logins"] = "Salvar histórico de Grupo, Raide e Instância após /reload e relogar"
    L["Help: Save Group Chat History"] = "Ajuda: Salvar Histórico de Grupo e Raide"
    L["Keeps recent Party, Raid, and Instance messages saved locally so dungeon or raid calls remain readable in Conversations after a /reload, disconnect, or relog."] = "Mantém as mensagens recentes de Grupo, Raide e Instância salvas localmente para que chamadas de masmorra ou raide continuem visíveis em Conversas após /reload, queda ou relogar."
    L["Enabled by default. Uncheck if you run heavy Raids and prefer not to store Party/Raid history on disk."] = "Ativado por padrão. Desmarque se fizer muitas raides longas e preferir não guardar histórico de Grupo/Raide em disco."
    L["Saved lines per General, Room, Group, Alliance & Mentions"] = "Linhas salvas por Geral, Sala, Grupo, Aliança e Menções"
    L["Help: General Conversation History Limit"] = "Ajuda: Limite de Histórico de Conversas Gerais"
    L["Controls how many recent messages (50 to 2000 lines, default 300) are stored per General tab, Private Room, Party/Raid/Instance channel, Alliance Chat, and Mentions Radar (up to 2000 conversations and 100 MB text total)."] = "Define quantas mensagens recentes (50 a 2000 linhas, padrão 300) são armazenadas na aba Geral, Salas Privadas, canais de Grupo/Raide/Instância, Aliança e Menções (até 2000 conversas e cota de 100 MB de texto)."
    L["Use '-' and '+' in steps of 50. Lower this value only if you want an even smaller SavedVariables file."] = "Use '-' e '+' de 50 em 50. Reduza apenas se quiser deixar o arquivo salvo ainda menor."
    L["Open Quick Reply"] = "Abrir Janela Rápida"
    L["Unpin from Quick Reply"] = "Desafixar da Janela Rápida"
