    L["Right-click: Silence, pin or close tab · Middle-click: Clear unread/draft"] = "Clique dir.: Silenciar, fixar ou fechar guia · Botão do meio: Limpar não lidas/rascunho"
    L["Silence this tab for 5, 10, 30 minutes, until leaving a dungeon/raid, or permanently."] = "Silencie esta aba por 5, 10, 30 minutos, até sair de uma masmorra/raide, ou permanentemente."
