    L["Checks online group members for missing Fortitude, Arcane Intellect, Mark of the Wild, active World Buffs, and Chronoboon Displacer."] = "Verifica os membros online do grupo quanto a Fortitude, Intelecto Arcano, Marca do Indomado, Bônus Mundiais e Deslocador de Cronobênção."
    L["Chronoboon"] = "Cronobênção"
    L["Click to toggle between Overview (XP/Profs/Gold) and Account Resets & Reputations Checklist."] = "Clique para alternar entre Resumo (XP/Profissões/Ouro) e Resets, Reputações e Marcas da Conta."
    L["Click to view active polls, vote in 1 click, or create a new guild poll."] = "Clique para ver enquetes ativas, votar em 1 clique ou criar uma nova enquete da guilda."
    L["Click: Open Auditor · Shift+Click: Draft Missing Buffs in chat"] = "Clique: Abrir Auditor · Shift+Clique: Rascunhar Buffs Faltando no chat"
    L["Click: Whisper · Alt+Click: Invite · Ctrl+Click: Social Card · Right-click: Options"] = "Clique: Sussurrar · Alt+Clique: Convidar · Ctrl+Clique: Cartão Social · Clique dir.: Opções"
