    L["Help: Quick Chat Modifier Actions"] = "Ajuda: Ações Rápidas no Chat"
    L["Help: Streamer / Privacy Mode"] = "Ajuda: Modo Streamer / Privacidade"
    L["Honored"] = "Honrado"
    L["Languages & Play Hours:"] = "Idiomas e Horários de Jogo:"
    L["Lets officers create quick guild polls (2 to 5 choices) and guildmates vote live in real time."] = "Permite que oficiais criem enquetes rápidas da guilda (2 a 5 opções) e membros votem em tempo real."
    L["Lets you hold Alt+Left-Click on any player name in Blizzard chat, Conversations, or Quick Reply to invite them to your group, or Ctrl+Left-Click to open their Social Card."] = "Permite segurar Alt+Clique esq. em qualquer jogador no chat da Blizzard, Conversas ou Janela Rápida para convidar ao grupo, ou Ctrl+Clique esq. para abrir o Cartão Social."
    L["Lv %d+"] = "Nv %d+"
