    L["Marks & Tokens"] = "Marcas e Fichas"
    L["Masks Battle.net Real ID / BattleTag names and hides private Whisper or Room text across Minimap Previews, Notification Toasts, Quick Reply, Conversations, Recent Notifications, and Filtered Chat Log during streams or screenshots."] = "Oculta nomes de Real ID / BattleTag da Battle.net e esconde textos privados de Sussurros ou Salas nas Prévias do Minimapa, Avisos Flutuantes, Janela Rápida, Conversas, Notificações Recentes e Log Filtrado durante lives ou capturas de tela."
    L["My Social Profile"] = "Meu Perfil Social"
    L["My Social Profile (Opt-In)"] = "Meu Perfil Social (Opcional)"
    L["Needed Roles / Classes:"] = "Funções / Classes Procuradas:"
