    L["Saves your current LFG role, class exclusion, level range, playstyle, and language filters under a reusable name shared across all characters."] = "Salva seus filtros atuais de função, exclusão de classes, faixa de nível, estilo de jogo e idiomas com um nome reutilizável entre todos os personagens."
