    L["Pick the roles you want to perform or fill, then click Auto-Select anytime to match your current spec and continue to activities."] = "Escolha as funções que deseja exercer ou preencher e clique em Auto-Selecionar quando quiser combinar com sua especialização atual antes de seguir para as atividades."
    L["Check one or more activities above and click List Self (or use Official LFG on Tab 1) to publish your group or solo search."] = "Marque uma ou mais atividades acima e clique em Anunciar-se (ou use o LFG Oficial na Aba 1) para publicar seu grupo ou busca solo."
    L["Shows live Party/Raid members, integrated Find Groups (LFG) search, Recent Companions met in the last 365 days, and automatic Dungeon/Raid Run History."] = "Mostra membros ao vivo do Grupo/Raide, busca integrada Encontrar Grupos (LFG), Companheiros Recentes dos últimos 365 dias e Histórico Automático de Masmorras/Raides."
