    L["Press Ctrl+C to copy this /roll summary."] = "Pressione Ctrl+C para copiar este resumo de /roll."
    L["Press Ctrl+C to copy this loot roll breakdown."] = "Pressione Ctrl+C para copiar os detalhes desta rolagem."
    L["Press Ctrl+C to copy this summary to your clipboard."] = "Pressione Ctrl+C para copiar este resumo para sua área de transferência."
    L["Prevents accidental dragging of the fixed floating Roll Results button during combat or camera turns."] = "Evita arrastar acidentalmente o botão fixo de Resultados durante combate ou giros de câmera."
