    L["Show Fixed Roll Results Button"] = "Mostrar Botão Fixo de Resultados"
    L["Shows active group loot drops with Need, Greed, Disenchant, and Pass buttons, real-time teammate choices, roll numbers, current leader, and winners alongside automatic item level, stat, and recipe comparisons."] = "Exibe saques ativos do grupo com botões de Necessidade, Ganância, Desencantar e Passar, escolhas em tempo real, números rolados, líder atual e vencedor junto à comparação automática de iLvl, atributos e receitas."
    L["Simulated Loot Winner Banner triggered."] = "Aviso simulado de Vencedor de Saque exibido."
    L["Started a fresh Group /roll tracking round."] = "Nova rodada de acompanhamento de /roll em grupo iniciada."
    L["Test"] = "Teste"
