    L["Toggle anytime in SocialCentral Settings -> General & Tools"] = "Altere quando quiser em Configurações -> Geral e Ferramentas"
    L["Track group /roll (1-100) rounds passively from party/raid chat"] = "Registrar rodadas de /roll (1-100) do chat de grupo/raide"
    L["Uncheck to keep winner notifications silent without playing sound."] = "Desmarque para manter as notificações de vencedor em silêncio, sem som."
    L["Waiting for your roll"] = "Aguardando sua rolagem"
    L["When your party or raid uses /roll, players will be ranked here automatically (catching duplicate rolls and non 1-100 ranges)."] = "Quando seu grupo ou raide usar /roll, o ranking aparecerá aqui automaticamente (identificando rolagens duplicadas e faixas fora de 1-100)."
