    L["Winner:"] = "Vencedor:"
    L["Won by Me"] = "Venci"
    L["Would you like to activate SocialCentral's Group Loot Roll system with equipped-gear comparison, live party choices, and a fixed Roll Results button?"] = "Deseja ativar o sistema de Saque em Grupo do SocialCentral com comparação de equipamento, escolhas do grupo ao vivo e botão fixo de Resultados?"
    L["YOU WON!"] = "VOCÊ VENCEU!"
    L["rolls"] = "rolagens"
    L["|cff9da7b5%d drops · |cffffea70%d won|r"] = "|cff9da7b5%d saques · |cffffea70%d vencidos|r"
    L["Announce Winners in Local Chat"] = "Anunciar Vencedores no Chat Local"
    L["Announce group loot winners locally in chat (with Results link)"] = "Anunciar vencedores de saque localmente no chat (com link de Resultados)"
    L["Click Results to inspect all teammate rolls"] = "Clique em Resultados para ver todas as rolagens"
    L["Displays SocialCentral's celebratory gold medallion animation at the top of your screen when you win a group loot drop."] = "Exibe a animação comemorativa de medalhão dourado do SocialCentral no topo da tela quando você vence um saque em grupo."
    L["Epic Win Celebration"] = "Comemoração Épica de Vitória"
    L["Help: Epic Loot Win Celebration"] = "Ajuda: Comemoração Épica de Vitória"
    L["Help: Local Chat Winner Summary"] = "Ajuda: Resumo de Vencedor no Chat"
    L["Hover the item icon for full comparison tooltips, Shift+Click to link in chat, Ctrl+Click to preview in Dressing Room, switch tabs when multiple items drop, or click Results to open the full Roll Results History window."] = "Passe o mouse no ícone do item para comparar atributos, Shift+Clique para linkar no chat, Ctrl+Clique para provar no Provador, troque de aba em múltiplos saques ou clique em Resultados para abrir o Histórico completo."
    L["Loot Roll"] = "Saque em Grupo"
    L["Prints a private colored summary line in your own chat window showing who won each group drop and their roll, along with a clickable [Results] link."] = "Exibe apenas para você uma linha colorida no chat com quem venceu cada saque e o valor rolado, junto a um link clicável [Resultados]."
    L["Results"] = "Resultados"
    L["RollBtnDE"] = "Des."
    L["RollBtnGreed"] = "Gan."
    L["RollBtnNeed"] = "Nec."
    L["Show epic celebration splash when I win a group drop"] = "Exibir comemoração épica ao vencer um saque em grupo"
    L["Triggers only when you win an item (does not clutter message notifications or Notification History)."] = "Aparece apenas quando você ganha o item (sem poluir as notificações de mensagens nem o Histórico de Notificações)."
    L["%d drops · %d won"] = "%d saques · %d vencidos"
    L["2. Last Group vs. Full History"] = "2. Último Grupo e Histórico"
    L["Auto-hides in %dm %02ds after run end"] = "Oculta automaticamente em %dm %02ds"
    L["By default, opening Roll Results always shows only the summary of your last dungeon, raid, or group session."] = "Por padrão, abrir os Resultados mostra sempre o resumo da última masmorra, raide ou último grupo."
    L["Choose 'During dungeon/raid (+3 min after)' (recommended), 'Always visible', or 'Hide button' (still accessible via /sc rolls or the Minimap menu)."] = "Escolha 'Durante masmorra/raide (+3 min)' (recomendado), 'Sempre visível' ou 'Ocultar botão' (acessível via /sc rolls ou Minimapa)."
    L["Click 'Full History' whenever you explicitly want to view older drops from previous groups and runs."] = "Clique em 'Histórico Completo' somente quando quiser ver saques antigos de grupos e masmorras anteriores."
    L["Controls the movable floating dice button that lets you inspect Loot Roll Results with one click (visible by default during dungeons or raids and for 3 minutes after they end)."] = "Controla o botão flutuante móvel do dado para abrir os Resultados de Saque (visível por padrão durante masmorras ou raides e por 3 minutos após terminar)."
    L["During dungeon/raid (+3 min after)"] = "Durante masmorra/raide (+3 min)"
    L["Full History"] = "Histórico Completo"
    L["Group Participants:"] = "Participantes do Grupo:"
    L["Help: Roll History Scope"] = "Ajuda: Exibição de Resultados"
    L["Last Group"] = "Último Grupo"
    L["Last Group Summary"] = "Resumo do Último Grupo"
    L["Last Group: %s (%d drops · %d won)"] = "Último grupo: %s (%d saques · %d vencidos)"
    L["Left-click: Open Last Group Summary\nShift+Click: Show Active Roll Card\nRight-click: Options & Visibility\nDrag: Move button"] = "Clique esquerdo: Resumo do Último Grupo\nShift+Clique: Reabrir Saque Ativo\nClique direito: Opções e Visibilidade\nArrastar: Mover botão"
    L["No drops in the latest group session (click Full History above to view older runs)."] = "Nenhum saque no último grupo (clique em Histórico Completo acima para ver registros anteriores)."
    L["Open Loot Roll Results showing your latest dungeon, raid, or group summary (with an option inside for full history)."] = "Abrir os Resultados de Saque mostrando o resumo da última masmorra, raide ou grupo (com opção interna para ver o histórico completo)."
    L["Opens Loot Roll Results focused on your last dungeon, raid, or group summary, with an explicit option inside the window to expand older history and passive Group /roll (1-100) rounds."] = "Abre os Resultados de Saque focado no resumo da última masmorra, raide ou último grupo, com opção explícita dentro da janela para expandir o histórico completo e rodadas /roll (1-100)."
    L["Opens focused on the summary of your latest dungeon, raid, or group session, with an explicit toggle inside to inspect older saved drops and Group /roll (1-100) rounds."] = "Abre focado no resumo da última masmorra, raide ou último grupo, com opção explícita dentro da janela para ver saques antigos e rodadas de /roll (1-100)."
    L["Scope"] = "Exibição"
    L["Showing all saved drops and previous groups."] = "Exibindo todos os saques salvos de grupos anteriores."
    L["Showing only your latest dungeon, raid, or group session."] = "Exibindo somente a última masmorra, raide ou último grupo."
    L["Shows your latest dungeon, raid, or group loot summary."] = "Mostra o resumo de saques da última masmorra, raide ou grupo."
    L["You can also open this window anytime via the floating dice button (during/3 min after runs), Minimap right-click menu, Group panel, or /sc rolls."] = "Você também pode abrir esta janela pelo ícone do dado (durante/3 min após a masmorra), menu do Minimapa, painel de Grupo ou /sc rolls."
    L["Visible only to you (never sends automated messages to public or group chat)."] = "Visível apenas para você (nunca envia mensagens automáticas em chats públicos ou de grupo)."
    L["Choices:"] = "Escolhas:"
    L["Click: light up nearby herbs, ore & chests (halo + icon + banner).\nRight-click: lock button, toggle halo/chime, or settings."] = "Clique: acender brilho, ícone e faixa em ervas, minérios e baús.\nBotão direito: travar posição, opções visuais ou ajustes."
    L["Turns on WoW's official world-object detection so herbs, ore, and chests light up with a glow halo, game icon, and screen banner."] = "Liga a detecção oficial de objetos do WoW para acender brilho animado, ícone e faixa no topo em ervas, minérios e baús."
    L["Choose Enable Highlight to turn it on (or toggle anytime with 1 click on the floating button)."] = "Clique em Ativar Brilho para ligar agora (ou alterne a qualquer hora em 1 clique no botão flutuante)."
    L["Start with Collectibles Highlight active immediately"] = "Começar com Destaque em Coletáveis ligado agora"
    L["Tip: if Blizzard shows a yellow Interact Key box, bind an interact key and use it twice (or turn off Game Tutorials) to clear it."] = "Dica: se surgir o aviso amarelo da Tecla de Interação, defina um atalho e use 2x (ou desmarque Tutoriais no jogo) para sumir."
    L["Herbs, ore & chests now light up when you face them!\nLeft-click toggles ON/OFF · Right-click opens options.\nTip: if a yellow Interact Key box appears, bind an Interact Key and use it twice (or uncheck Game Tutorials) to clear it."] = "Ervas, minérios e baús agora acendem quando você olha para eles!\nClique esquerdo liga/desliga · Botão direito abre opções.\nDica: se surgir o aviso amarelo, defina um atalho de interação e use 2x (ou desmarque Tutoriais) para sumir."
    L["1-click ON/OFF highlight on nearby herbs, ore & chests (halo + game icon)."] = "Liga/desliga em 1 clique o brilho e detecção em ervas, minérios e baús."
    L["Use official object detection & icon (herbs, ore & chests)"] = "Usar detecção e ícone oficiais em ervas, minérios e baús"
    L["Master opt-in toggle for highlighting nearby herbs, mining veins, fishing pools, and chests using WoW's official near-object detection."] = "Interruptor principal para destacar ervas, veios de minério, cardumes e baús próximos usando a detecção oficial do WoW."
    L["Uses strictly official WoW world-object detection without binding keys or altering quest/enemy outlines. Disabling restores your original settings immediately."] = "Usa somente a detecção oficial de objetos do WoW, sem forçar atalhos e mantendo os contornos de missão e inimigos. Desativar restaura tudo na hora."
    L["Help: Official Object Detection"] = "Ajuda: Detecção Oficial de Objetos"
    L["Turns on WoW's official forward object detection and game-object icon so herbs, ore veins, fishing pools, and chests illuminate automatically as you approach — without touching quest or enemy outlines."] = "Ativa a detecção frontal oficial do WoW e o ícone de objeto para ervas, minérios, cardumes e baús brilharem ao se aproximar — sem apagar contornos de missão ou inimigos."
    L["If Blizzard shows a yellow Interact Key box, bind an interact key and use it twice (or uncheck Game Tutorials in WoW Options) to clear it permanently."] = "Se a Blizzard exibir o quadro amarelo da Tecla de Interação, defina um atalho e use 2x perto de um alvo (ou desmarque Tutoriais nas Opções do WoW) para removê-lo para sempre."
    L["Adds a small draggable herb button near your Minimap to toggle Collectible Highlight ON/OFF with 1 click anytime."] = "Mostra um botão móvel perto do Minimapa para ligar ou desligar o Destaque em Coletáveis em 1 clique."
    L["Left-click toggles detection & glow ON/OFF; drag to move; right-click to lock or hide."] = "Clique esquerdo liga/desliga detecção e brilho; arraste para mover; botão direito trava ou oculta."
    L["Helps herbalists, miners, anglers, and treasure hunters spot nearby collectibles using WoW's official forward object detection and game-object icon (without touching quest or enemy outlines)."] = "Ajuda herboristas, mineradores, pescadores e caçadores de tesouro a enxergar coletáveis próximos usando a detecção frontal oficial do WoW e o ícone de objeto (sem apagar contornos de missão ou inimigos)."
    L["Enable manually here or confirm the prompt when turning on Find Herbs / Find Minerals / Find Fish on your Minimap. If Blizzard shows a yellow Interact Key box, bind an interact key and use it twice (or uncheck Game Tutorials in WoW Options) to clear it permanently."] = "Ative manualmente aqui ou confirme ao ligar Rastrear Ervas / Minérios / Peixes no Minimapa. Se a Blizzard exibir o quadro amarelo da Tecla de Interação, defina um atalho e use 2x perto de um alvo (ou desmarque Tutoriais nas Opções do WoW) para removê-lo para sempre."
