    L["Settings Search"] = "Pesquisa nas Opções"
    L["Type |cff1d4ed8interact|r in the top search bar and look for |cff15803dInteract With Target|r.\nThen use it 2x so the warning never appears again!"] = "Pesquise no topo da janela digitando |cff1d4ed8interagir|r e procure o atalho |cff15803dInteragir com alvo|r.\nDepois use 2x para o aviso não aparecer mais!"
    L["Watchlist is empty. Type a player name above or click Battle.net to monitor login alerts."] = "Sua Watchlist está vazia. Digite um nome acima ou clique em Battle.net para acompanhar logins."
    L["No friendly players spotted nearby yet. Target or walk near friendly players to list them."] = "Nenhum jogador aliado detectado por perto ainda. Selecione ou chegue perto de aliados para listá-los."
    L["No characters match this filter. Try switching chips above or enabling Show Offline."] = "Nenhum personagem encontrado neste filtro. Troque os chips acima ou habilite Mostrar Offline."
    L["Filter listings by preferred realm or group languages."] = "Filtra anúncios pelos idiomas preferidos do reino ou do grupo."
    L["Choose how browse results and solo applicants are sorted."] = "Escolhe como resultados da busca e jogadores solo são ordenados."
    L["Hides dungeon and raid groups whose slots are already full."] = "Oculta grupos de masmorra e raide cujas vagas já estejam cheias."
    L["Filters Browse activities to dungeons and content within your character's recommended level range."] = "Filtra a busca para masmorras e conteúdos recomendados para o nível do seu personagem."
    L["Shows all groups and solo players from Official Blizzard LFG, Global Chat, Guild, Allies, and Friends."] = "Mostra todos os grupos e jogadores solo do Localizador Oficial da Blizzard, Chat Global, Guilda, Aliados e Amigos."
    L["Shows only public groups listed in Blizzard's Official Group Finder."] = "Mostra apenas grupos públicos listados no Localizador Oficial da Blizzard."
    L["Shows groups and solo listings shared by members of your Guild and Allied Guilds."] = "Mostra grupos e anúncios solo compartilhados por membros da sua Guilda e Guildas Aliadas."
    L["Shows only groups and players running SocialCentral [SC] for rich role, class, and status sync."] = "Mostra apenas grupos e jogadores usando o SocialCentral [SC] com sincronização de função, classe e status."
    L["Shows groups and solo listings involving your Friends list or Watchlist players."] = "Mostra grupos e anúncios solo envolvendo sua lista de Amigos ou jogadores da Watchlist."
    L["Shows group calls captured passively from World and Global chat channels."] = "Mostra chamados de grupo capturados passivamente dos canais de chat Mundial e Global."
    L["Separates formed Groups ([LFM]) and solo Players Looking ([Looking]) into two distinct collapsible sections."] = "Separa Grupos formados ([LFM]) e Jogadores Procurando ([Procurando]) em duas seções recolhíveis distintas."
    L["Clusters listings under collapsible Dungeon and Raid headers with slot summaries."] = "Agrupa anúncios sob cabeçalhos recolhíveis de Masmorras e Raides com resumo de vagas."
    L["Hides dungeon and raid listings for instances where your character already has a saved lockout."] = "Oculta anúncios de masmorras e raides onde seu personagem já possui vínculo salvo."
    L["Automatically hides listings containing Avoid-flagged players or Enemy Guild members."] = "Oculta automaticamente anúncios com jogadores marcados como Evitar ou membros de Guildas Inimigas."
    L["Displays class icons for current party/raid members on the bottom right of each Browse card."] = "Exibe os ícones de classe dos membros atuais do grupo/raide no canto inferior direito de cada cartão."
    L["Automatically switches to the SocialCentral Browse tab whenever you publish a new listing on Official Tab 1."] = "Muda automaticamente para a aba de busca do SocialCentral sempre que você publicar um anúncio oficial na Aba 1."
    L["Filters out groups and solo applicants of your own class so you have less competition on armor and class gear drops."] = "Filtra grupos e jogadores solo da sua própria classe para reduzir a competição por armaduras e saques da sua classe."
    L["Exclude specific classes you prefer not to share loot or party slots with when searching for groups."] = "Exclui classes específicas com quem você prefere não disputar saque ou vagas ao procurar grupos."
    L["Click / Right-click: Actions Menu"] = "Clique / Botão direito: Menu de Ações"
    L["%d active listings are hidden by your current filters. Open 'Filters »' to adjust or click Reset."] = "%d anúncios ativos estão ocultos pelos filtros atuais. Abra 'Filtros »' para ajustar ou clique em Limpar."
    L["Click to open conversation"] = "Clique para abrir a conversa"
    L["No saved shortcuts yet — fill the fields above and click + Save."] = "Nenhum atalho salvo ainda — preencha os campos acima e clique em + Salvar."
