    L["Add Battle.net Friends to Watchlist"] = "Adicionar Amigos Battle.net à Watchlist"
    L["Add Friend (Character Name or BattleTag#1234):"] = "Adicionar Amigo (Nome do Personagem ou BattleTag#1234):"
    L["Adds a same-faction character to your WoW Friends list or sends a Battle.net friend request when you type a BattleTag (Name#1234) or email."] = "Adiciona um personagem da mesma facção aos seus Amigos do WoW ou envia um pedido de amizade Battle.net ao digitar uma BattleTag (Nome#1234) ou e-mail."
    L["Already followed in Watchlist (all alts)."] = "Já acompanhado na Watchlist (todos os alts)."
