    L["Battle.net friend request sent."] = "Pedido de amizade Battle.net enviado."
    L["Choose Social Folder"] = "Escolher Pasta Social"
    L["Click any section header to expand/collapse (saved automatically) · Left-click a friend for Quick Inspect · Right-click for Notes, Folders, Battle.net Watchlist & Invites."] = "Clique em qualquer cabeçalho de seção para expandir/recolher (salvo automaticamente) · Clique esquerdo em um amigo para Inspeção Rápida · Botão direito para Notas, Pastas, Watchlist Battle.net e Convites."
    L["Click to clear the active folder filter."] = "Clique para limpar o filtro de pasta ativo."
    L["Click to stop tracking this Battle.net account."] = "Clique para parar de acompanhar esta conta Battle.net."
    L["Create, rename, or delete custom Social folders and assign multiple WoW friends to a folder in one batch."] = "Crie, renomeie ou exclua pastas Sociais personalizadas e organize vários amigos do WoW em uma pasta de uma só vez."
    L["Delete Folder"] = "Excluir Pasta"
    L["Enter a character name (including two-word names) or a BattleTag and click Add. Unavailable during combat."] = "Digite o nome do personagem (incluindo nomes compostos) ou uma BattleTag e clique em Adicionar. Indisponível em combate."
    L["Export / Import Social Data..."] = "Exportar / Importar Dados Sociais..."
