    L["Lets you add any character manually (or your current target), open the searchable Battle.net Friend Picker to track all alts of any Battle.net friend, and run an official single /who query outside combat with cooldown >= 5s."] = "Permite adicionar qualquer personagem manualmente (ou seu alvo atual), abrir o Seletor de Amigos Battle.net com busca para acompanhar todos os alts e executar um /who oficial único fora de combate com recarga >= 5s."
