    L["Search and filter all your Battle.net friends without overflowing the screen, then click '+ Follow' to track every character and alt on their account under one Watchlist entry."] = "Busque e filtre todos os seus amigos Battle.net sem estourar a tela, e clique em '+ Seguir' para acompanhar cada personagem e alt da conta em uma única entrada da Watchlist."
