    L["Switch chips (In WoW, Friends, Battle.net, Favorites), organize Folders in batch, sort, or add a character or BattleTag."] = "Alterne filtros rápidos (No WoW, Amigos, Battle.net, Favoritos), organize Pastas em lote, ordene ou adicione um personagem ou BattleTag."
    L["Target Folder (pick existing or type a new name):"] = "Pasta de Destino (escolha uma existente ou digite um novo nome):"
    L["Type Name or Name-Surname and click '+ Add', click the Battle.net icon to open the searchable Friend Picker modal, or leave empty while targeting a player."] = "Digite Nome ou Nome-Sobrenome e clique em '+ Adicionar', clique no ícone Battle.net para abrir o Seletor com busca, ou deixe vazio mirando um jogador."
    L["Type a character name, guild, zone, folder, or alias to filter instantly."] = "Digite um nome, guilda, zona, pasta ou apelido para filtrar na hora."
    L["Type a name (or target a player) and click '+ Add', or click the Battle.net icon for the searchable Friend Picker."] = "Digite um nome (ou mire um jogador) e clique em '+ Adicionar', ou clique no ícone Battle.net para abrir o Seletor com busca."
    L["Unassigned"] = "Sem Pasta"
    L["Unifies Character Friends, Battle.net friends, and Guildmates into smart collapsible sections (Favorites, Folders, Online in WoW, Guild, Battle.net & Other Games, Offline) without spending /who cooldown."] = "Unifica Amigos do Personagem, Amigos Battle.net e membros da Guilda em seções inteligentes recolhíveis (Favoritos, Pastas, Online no WoW, Guilda, Battle.net e Outros Jogos, Offline) sem gastar recarga de /who."
    L["Use the quick chips below (In WoW, Friends, Battle.net, Guild, Favorites), click the Bag icon to manage Social Folders in batch or export/import data, or click '+' to add a WoW character or BattleTag."] = "Use os filtros rápidos abaixo (No WoW, Amigos, Battle.net, Guilda, Favoritos), clique no ícone de Bolsa para organizar Pastas em lote ou exportar/importar dados, ou clique em '+' para adicionar personagem ou BattleTag."
    L["Use the search bar or filter pills (WoW, Online, Offline, All). Click '+ Follow' to add or 'Following' to remove — the window stays open so you can organize multiple friends quickly."] = "Use a barra de busca ou os filtros (WoW, Online, Offline, Todos). Clique em '+ Seguir' para adicionar ou 'Seguindo' para remover — a janela fica aberta para organizar vários amigos rapidamente."
