    L["Adjust dice button visibility, Tabbed/Stacked layout, hiding Blizzard's default roll bar, winner celebration, or jump straight to full Settings."] = "Ajuste a visibilidade do botão de dado, o layout em Abas ou Empilhado, ocultar a barra oficial da Blizzard, celebração de vitória ou abra as Configurações completas."
    L["Announce Winner"] = "Anunciar Vencedor"
