    L["Auto-hide floating dice button when Quick Access Bar is visible"] = "Ocultar automaticamente o botão flutuante de dado quando a Barra de Acesso Rápido estiver visível"
    L["Automatically opens Blizzard's side-by-side equipped item comparison tooltip whenever you hover a drop in the Roll Card or Roll Results window."] = "Abre automaticamente a comparação lado a lado do equipamento equipado ao passar o mouse sobre um item no cartão de Roll ou nos Resultados."
    L["Can Learn"] = "Pode Aprender"
