    L["Check if you already use the Quick Access Bar and don't want two separate dice icons on screen."] = "Marque se você já usa a Barra de Acesso Rápido e não quer dois ícones de dado separados na tela."
    L["Choose 'During dungeon/raid (+3 min after)' (recommended), 'Always visible', or 'Hide button' (still accessible via Quick Access Bar, /sc roll, or the Minimap menu)."] = "Escolha 'Durante masmorra/raide (+3 min após)' (recomendado), 'Sempre visível' ou 'Ocultar botão' (ainda acessível pela Barra de Acesso Rápido, /sc roll ou menu do Minimapa)."
    L["Chooses how multiple simultaneous boss drops are displayed in SocialCentral's active roll window."] = "Define como múltiplos itens derrubados ao mesmo tempo aparecem na janela ativa de rolagem do SocialCentral."
    L["Compare this drop against your other Ring, Trinket, or Off-Hand slot."] = "Compara este saque com seu outro espaço de Anel, Berloque ou Mão Secundária."
    L["Configures SocialCentral's Group Loot Roll card (Need/Greed/Disenchant/Pass with class usability, BoP safety, and stat comparison), stacked multi-drop layout, epic win celebration, fixed dice button, and Raid Leader /roll (1-100) console."] = "Configura o cartão de Saque em Grupo do SocialCentral (Necessidade/Ganância/Desencantar/Passar com aviso de classe, segurança BoP e comparação de atributos), modo empilhado, celebração épica, botão de dado e painel de /roll (1-100) do Líder."
