    L["Detects duplicate rolls, MS/OS brackets, and non 1-100 ranges automatically with zero network traffic."] = "Detecta rolagens duplicadas, faixas MS/OS e intervalos fora de 1-100 automaticamente sem tráfego de rede."
    L["Enable the roll window below, pick Tabbed or Stacked layout, and open Roll Results anytime from here, the floating dice button, Quick Access Bar, or /sc roll."] = "Ative a janela de rolagem abaixo, escolha o layout em Abas ou Empilhado e abra os Resultados quando quiser por aqui, pelo botão de dado, Barra de Acesso Rápido ou /sc roll."
    L["Executes /roll 1-100 immediately so your roll joins the active round."] = "Executa /roll 1-100 imediatamente para sua rolagem entrar na rodada ativa."
    L["Filter or sort drops on the left, right-click any drop or player for quick actions, switch to Group /roll (1-100) to run Raid Leader roll calls and tie-breakers, or click Configure for quick Loot Roll options."] = "Filtre ou ordene os saques à esquerda, clique com o botão direito em qualquer item ou jogador para ações rápidas, alterne para /roll em Grupo (1-100) para chamadas e desempates do Líder ou clique em Configurar."
    L["Greed Unusable"] = "Ganância Inúteis"
