    L["Hover anywhere on the item card for comparison tooltips, check usability badges, or swap Ring/Trinket comparison slots."] = "Passe o mouse no cartão do item para ver a comparação, confira avisos de uso pela sua classe ou troque o Anel/Berloque comparado."
    L["Inspect every roll, MS/OS brackets, and Boss/Master Loot info. Right-click any player to whisper or ask about an item."] = "Veja cada rolagem, faixas MS/OS e dados de Chefe/Mestre de Saque. Clique com o botão direito em qualquer jogador para sussurrar ou perguntar sobre um item."
    L["Keeps your screen clutter-free by hiding the standalone floating dice button whenever SocialCentral's Quick Access Bar already provides the Roll Results dice icon."] = "Mantém sua tela limpa ocultando o botão flutuante de dado sempre que a Barra de Acesso Rápido do SocialCentral já estiver exibindo o ícone de Resultados."
