    L["Opens focused on your latest dungeon, raid, or group loot summary with Win Rate & Roll Luck analytics, rarity/sort filters, Master Loot & boss attribution, and a full Raid Leader /roll (1-100) console with MS/OS brackets and automatic Tie-Breakers."] = "Abre focado no resumo do seu último grupo, masmorra ou raide com Taxa de Vitória e Sorte, filtros de raridade/ordenação, registro de Chefe e Mestre de Saque e console completo de /roll (1-100) com MS/OS e Desempate automático."
    L["Opens on Last Group with Win Rate, Average Roll, and top winners. Click Full History for older runs."] = "Abre no Último Grupo com Taxa de Vitória, Média de Rolagem e maiores vencedores. Clique em Histórico Completo para runs anteriores."
