    L["Visit a Bank NPC to snapshot bank items."] = "Habla con un banquero para guardar los objetos del banco."
    L["Web Armory Link"] = "Enlace Armería Web"
    L["Broadcasts your current activity tag (LFG, M+, Raid, PvP, etc.), optional short note, and Clan Sync toggle safely to guildmates using SocialCentral."] = "Transmite tu etiqueta de actividad actual (LFG, M+, Banda, JcJ, etc.), nota corta opcional y Sync de la Hermandad de forma segura a tu hermandad con SocialCentral."
    L["Centralizes Online Guild Roster (Rank/Zone/Note), Events, Diplomacy stances, Guild Crafters, and Saved Dungeon/Raid Lockouts."] = "Centraliza la lista en línea de la hermandad (Rango/Zona/Nota), Eventos, Diplomacia, Profesiones de artesanos y Bloqueos guardados."
    L["Click '+ Event Call' to post an event, or use the filter dropdown to inspect 'Calendar' and open the native WoW Calendar."] = "Haz clic en '+ Llamado' para crear un evento o usa el filtro para ver el 'Calendario' y abrir el Calendario oficial de WoW."
    L["Click 'My Status', pick an activity tag, toggle Clan Sync (SCentral1), or trigger a manual Sync."] = "Haz clic en 'Mi Estado', elige una etiqueta, activa/desactiva Sync de la Hermandad (SCentral1) o pulsa Sincronizar."
    L["Equipped"] = "Equipados"
    L["Filter: %s"] = "Filtro: %s"
    L["Type Name or Name-Surname and click '+ Add', click the Battle.net globe icon to track a Battle.net friend's entire account, or leave empty while targeting a player."] = "Escribe Nombre o Nombre-Apellido y pulsa '+ Añadir', haz clic en el globo de Battle.net para seguir toda la cuenta de un amigo de Battle.net, o déjalo vacío con un objetivo seleccionado."
    L["Lets you add any character manually (or your current target), pick a Battle.net friend account across all alts, and run an official single /who query outside combat with cooldown >= 5s."] = "Permite añadir cualquier personaje manualmente (o tu objetivo actual), elegir una cuenta de amigo de Battle.net para seguir todos sus personajes y ejecutar un /who oficial fuera de combate con espera mínima de 5s."
    L["Added %s to your Watchlist (tracking all Battle.net / linked alts)."] = "%s añadido a tu Watchlist (siguiendo todos los alters de Battle.net / vinculados)."
    L["%s now tracks all Battle.net & linked characters."] = "%s ahora sigue todos los personajes y alters vinculados en Battle.net."
    L["Could not add this Battle.net account right now."] = "No se pudo añadir esta cuenta de Battle.net en este momento."
    L["Added Battle.net friend %s for this session. As soon as they log into WoW on any character, it will stay saved permanently across all their alts."] = "Amigo de Battle.net %s añadido para esta sesión. En cuanto entre a WoW con cualquier personaje, quedará guardado permanentemente para todos sus alters."
    L["Track all Battle.net / linked alts"] = "Seguir todos los alters Battle.net / vinculados"
