    L["Right-click any player frame or chat name to quickly set Social Notes, 'Good Partner (+)', or 'Flag: Avoid'."] = "Haz clic derecho en cualquier jugador o nombre del chat para definir Notas Sociales, 'Buen Compañero (+)' o 'Marcar: Evitar'."
