    L["Click 'Auto-Detect' to pull your live professions, or click 'Publish Note' so all guildmates see your crafts even without SocialCentral."] = "Haz clic en 'Auto-Detectar' para obtener tus profesiones actuales, o en 'Publicar Nota' para que toda la hermandad vea tus oficios incluso sin SocialCentral."
