    L["Detects your character's current professions and skill ranks automatically, and lets you publish a compact tag to your Guild Public Note."] = "Detecta automáticamente las profesiones y rangos de habilidad actuales y te permite publicar una etiqueta compacta en tu Nota Pública de Hermandad."
