    L["Help: Floating Notification Toast"] = "Ayuda: Toast Flotante"
    L["Help: Guild Event Alerts"] = "Ayuda: Alertas de Eventos de Hermandad"
    L["Help: Guild Signup Alerts"] = "Ayuda: Alertas de Inscripción"
