    L["Left-click the pill to jump directly to the conversation (deferred automatically after combat), hover to pause, or right-click to dismiss."] = "Clic izquierdo en el aviso para ir directo a la conversación (pospuesto tras el combate), pasa el ratón para pausar o clic derecho para cerrar."
    L["Notifies you as the event organizer whenever a guildmate signs up (or declines) on one of your active Guild Events."] = "Te notifica como organizador cuando un compañero de hermandad se apunta (o declina) en uno de tus Eventos de Hermandad activos."
    L["Notify me when guildmates sign up to my Events"] = "Notificarme cuando compañeros se apunten a mis Eventos"
    L["Notify when guildmates post a new Guild Event"] = "Notificar cuando compañeros publiquen un nuevo Evento de Hermandad"
    L["Only flashes for priority incoming notifications and does nothing while you are already viewing the open thread."] = "Solo parpadea en avisos prioritarios y no actúa si ya estás viendo esa conversación abierta."
