    L["Spawns a sample floating Notification Toast pill with sound so you can preview its look and drag it to your preferred screen position."] = "Muestra un Toast de prueba con sonido para previsualizar su estilo y arrastrarlo a tu posición preferida."
    L["Test Notification Toast"] = "Probar Toast de Notificación"
    L["Triggers only on events you created so your chat stays clutter-free."] = "Solo se activa en eventos creados por ti para mantener limpio tu chat."
