    L["Keep enabled so guildless characters stay clutter-free without manually turning Guild options off and on."] = "Déjalo activado para mantener limpios los personajes sin hermandad sin cambiar opciones manualmente."
    L["Keep opt-in sync off for 100% local play, or turn on to share guild status/LFG/events with teammates."] = "Deja desactivada la sincronización para uso 100% local o actívala para compartir estado, LFG y eventos con tu hermandad."
