    L["Notify on shared Guild Scout sighting alerts"] = "Notificar alertas de Explorador compartidas por Hermandad"
    L["Only %s"] = "Solo %s"
    L["Opt-in guild communication, Group Finder automation-free helpers, and peer version checks."] = "Comunicación opcional de hermandad, asistentes manuales del Buscador y comprobación de versión."
    L["Radar & Map"] = "Radar y Mapa"
    L["Screen Target Radar"] = "Radar de Objetivos en Pantalla"
    L["Shows chat, sound, and popup alerts when a guildmate shares an Enemy Scout sighting."] = "Muestra alertas en chat, sonido y popup cuando un compañero de hermandad comparte un avistamiento de Explorador enemigo."
    L["Silence this notification"] = "Silenciar esta notificación"
    L["Social & Friends (O)"] = "Social y Amigos (O)"
    L["Stop checking or alerting when peers run a newer addon version."] = "Deja de comprobar o avisar cuando otros jugadores tengan una versión más nueva."
    L["Stop notifying on Scout sightings shared by guildmates."] = "Deja de notificar avistamientos de Explorador compartidos por la hermandad."
    L["Stop notifying when Classic World Buffs are announced or synced."] = "Deja de notificar cuando se anuncien o sincronicen World Buffs Clásicos."
    L["Stop notifying when Watchlist players come online."] = "Deja de notificar cuando jugadores de Watchlist se conecten."
    L["Stop notifying when friends connect to WoW."] = "Deja de notificar cuando tus amigos se conecten a WoW."
    L["Stop notifying when friends disconnect from WoW."] = "Deja de notificar cuando tus amigos se desconecten de WoW."
    L["Stop notifying when guildmates look for a Dungeon / Group."] = "Deja de notificar cuando compañeros de hermandad busquen Mazmorra o Grupo."
    L["Stop notifying when guildmates post new Guild Events."] = "Deja de notificar cuando publiquen nuevos Eventos de Hermandad."
    L["Stop notifying when guildmates sign up to your Events."] = "Deja de notificar cuando compañeros se inscriban a tus Eventos."
    L["Stop showing 15m and 5m reminders before Guild & Calendar events."] = "Deja de mostrar recordatorios de 15 min y 5 min antes de eventos de Hermandad y Calendario."
    L["Stop showing floating popups for addon messages (conversations still appear in Chat)."] = "Deja de mostrar popups flotantes de mensajes del addon (seguirás viéndolos en Conversaciones y chat)."
    L["Stop warning when an Avoid-flagged player enters your group."] = "Deja de avisar cuando un jugador marcado como Evitar entre en tu grupo o banda."
