    L["Summary & Windows"] = "Resumen y Ventanas"
    L["Uncheck to keep Blizzard's Friends (O) window 100% vanilla while still keeping '/sc hub' available."] = "Desmarca para dejar la ventana de Amigos (O) 100% original manteniendo '/sc hub' disponible."
    L["Uncheck to mute shared Guild Scout alerts without disabling your own Target Radar."] = "Desmarca para silenciar alertas de Explorador de la Hermandad sin desactivar tu propio Radar de Objetivos."
    L["Watchlist Online Alerts"] = "Alertas Watchlist Online"
    L["World Buff Expiry Warning"] = "Aviso de Expiración de World Buff"
    L["Your character is not currently in a guild."] = "Tu personaje actual no pertenece a ninguna hermandad."
    L["This module is disabled in Settings."] = "Este módulo está desactivado en Opciones."
    L["disabled. Re-enable anytime in Settings -> Notifications."] = "desactivado. Puedes reactivarlo en Opciones -> Notificaciones."
    L["All notification categories are active and no individual players are muted."] = "Todas las categorías de notificación están activas y no hay jugadores silenciados."
    L["Alt+Click: toggle Target Radar"] = "Alt+Clic: alternar Radar de Objetivos"
    L["Attaches the Clans, Allies & Global Chat LFG side-tab inside Blizzard's Group Finder (I) window and scans public LFG channels."] = "Añade la pestaña lateral de Hermandades, Aliados y Chat Global en el Buscador de Grupos (I) y explora los canales públicos de LFG."
    L["Auto-silence social popups & chimes inside Dungeons, Raids & BGs"] = "Silenciar avisos y sonidos sociales automáticamente en Mazmorras, Bandas y Campos de Batalla"
    L["Automatically pauses social popups and chimes whenever you enter a Dungeon, Raid, or Battleground (Group Avoid safety warnings still show)."] = "Pausa automáticamente los avisos y sonidos sociales al entrar en una Mazmorra, Banda o Campo de Batalla (los avisos de seguridad de Evitar en Grupo siguen apareciendo)."
    L["Click 'Re-enable Alerts' or 'Unmute All Players' anytime if you accidentally silenced something via the toast crossed-bell button."] = "Haz clic en 'Reactivar Alertas' o 'Quitar Silencio a Todos' en cualquier momento si silenciaste algo por error desde el botón de campana tachada del aviso."
    L["Click any shortcut below to jump straight to that official game window with the SocialCentral tab active, or configure preferences above."] = "Haz clic en cualquier acceso directo abajo para abrir directamente esa ventana oficial del juego con la pestaña de SocialCentral activa, o ajusta tus preferencias arriba."
    L["Ctrl+Click: open Conversations"] = "Ctrl+Clic: abrir Conversaciones"
