    L["Ideal for bank alts or leveling characters where you want a lighter setup without changing your main character."] = "Ideal para alters de banco o personajes subiendo de nivel donde quieres una configuración más ligera sin cambiar tu personaje principal."
    L["Instantly switch between Full Suite, Friends & Chat Only, or Ultra-Light (Alts & Notes) presets, then fine-tune any checkbox below."] = "Cambia al instante entre los perfiles Completo, Solo Amigos y Chat o Ultra-Ligero (Alters y Notas), y ajusta cualquier opción abajo."
