    L["Shows a live summary of notification categories you silenced and how many individual players or conversations are currently muted."] = "Muestra un resumen en vivo de las categorías de notificación silenciadas y cuántos jugadores o conversaciones individuales están en silencio."
    L["Temporarily pauses all non-critical floating popups and sound chimes without overwriting any of your saved notification checkboxes."] = "Pausa temporalmente todos los avisos flotantes no críticos y sonidos sin sobrescribir tus casillas guardadas."
    L["Turn entire SocialCentral modules and Blizzard window integrations (O, I, J, C, M) on or off immediately without reload."] = "Activa o desactiva módulos enteros de SocialCentral e integraciones en ventanas del juego (O, I, J, C, M) al instante sin recargar."
    L["Uncheck to disable the Guild module completely. Also hides automatically on characters without a guild."] = "Desmarca para desactivar por completo el módulo de Hermandad. También se oculta automáticamente en personajes sin hermandad."
    L["Uncheck to disable the My Alts module, bag/bank snapshots, and alt item tooltip counts completely."] = "Desmarca para desactivar por completo el módulo Mis Alters, capturas de bolsas/banco y conteo de objetos en descripciones."
    L["Uncheck to disable the entire Group Finder (I) module and stop LFG chat scanning immediately."] = "Desmarca para desactivar todo el módulo del Buscador de Grupos (I) y detener al instante la lectura de canales LFG."
    L["Uncheck to hide Conversations and disable all addon chat popups and chimes."] = "Desmarca para ocultar Conversaciones y desactivar todos los avisos y sonidos del chat del addon."
    L["Uncheck to hide the Group tab and stop recording recent party/raid companions."] = "Desmarca para ocultar la pestaña Grupo y dejar de registrar compañeros recientes de grupo o banda."
    L["Uncheck to hide the Nearby tab and stop all passive unit/chat proximity recording."] = "Desmarca para ocultar la pestaña Cercanos y detener todo registro pasivo de proximidad."
    L["Uncheck to hide the Watchlist tab and mute Watchlist online tracking completely."] = "Desmarca para ocultar la pestaña Watchlist y silenciar por completo el seguimiento en línea."
    L["Uncheck to pause screen scanning and disable all Target Radar controls and HUD."] = "Desmarca para pausar el escaneo en pantalla y desactivar todos los controles y el HUD del Radar de Objetivos."
    L["Unchecking a module disables its tabs, shortcuts, alerts, and background scanners completely."] = "Desmarcar un módulo desactiva por completo sus pestañas, accesos directos, alertas y escáneres en segundo plano."
    L["Unmute All Players"] = "Quitar Silencio a Todos"
