    L["Only the group leader can manage group listings."] = "Solo el líder del grupo puede crear o gestionar listados."
    L["You are currently in a party led by %s. By Blizzard rules, only the party leader can create, edit, or advertise group listings and invite members.\n\nWhat you can do right now:\n• Click 'Browse Groups' below to view active Guild, Allies & Friends groups (read-only and whisper).\n• Ask the leader to broadcast the group or promote you, or leave the party to list solo."] = "Estás en un grupo liderado por %s. Según las reglas de Blizzard, solo el líder puede crear, editar o publicar listados de grupo e invitar jugadores.\n\nQué puedes hacer ahora:\n• Haz clic en 'Buscar grupos' abajo para ver grupos activos de Hermandad, Aliados y Amigos (lectura y susurro).\n• Pide al líder que publique el grupo o te ascienda a líder, o sal del grupo para buscar en solitario."
    L["You are currently in a party and another player is the leader. By Blizzard rules, only the group leader can create, edit, or advertise group listings and invite members.\n\nWhat you can do right now:\n• Click 'Browse Groups' below to view active Guild, Allies & Friends groups (read-only and whisper).\n• Ask the leader to broadcast the group or promote you, or leave the party to list solo."] = "Estás en un grupo y otra persona es el líder. Según las reglas de Blizzard, solo el líder del grupo puede crear, editar o publicar listados e invitar jugadores.\n\nQué puedes hacer ahora:\n• Haz clic en 'Buscar grupos' abajo para ver grupos activos de Hermandad, Aliados y Amigos (lectura y susurro).\n• Pide al líder que publique el grupo o te ascienda a líder, o sal del grupo para buscar en solitario."
    L["Member mode (Leader: %s) — Only the leader can list or invite; you can browse and whisper."] = "Modo miembro (Líder: %s) — Solo el líder puede publicar o invitar; puedes ver grupos y susurrar."
    L["Member mode — Only the leader can list or invite; you can browse and whisper."] = "Modo miembro — Solo el líder puede publicar o invitar; puedes ver grupos y susurrar."
    L["Only the party leader (%s) can list or broadcast this group."] = "Solo el líder del grupo (%s) puede publicar o gestionar este grupo."
    L["Only the party leader can list or broadcast this group."] = "Solo el líder del grupo puede publicar o gestionar este grupo."
    L["Only the group leader can invite players into this party."] = "Solo el líder del grupo puede invitar nuevos jugadores a este grupo."
    L["Broadcast Current Group (Leader Only)"] = "Difundir Grupo Actual (Solo Líder)"
