    L["Your character is Lv %d — first dungeons (Ragefire Chasm / Hall of Thanes) start at Lv 13.\n\nSwitch Category to 'All Categories' or 'Quests & Zones', uncheck 'My Level', or use '/LookingForGroup' to see all groups now."] = "Tu personaje está en Nv %d — las primeras mazmorras (Simas Ígneas / Hall of Thanes) comienzan en Nv 13.\n\nCambia la categoría a 'Todas las Categorías' o 'Misiones y Zonas', desmarca 'Mi Nivel' o usa '/LookingForGroup' para ver grupos ahora."
