    L["You can change this anytime in Settings -> Summary & Windows."] = "Puedes cambiar esto en cualquier momento en Configuración -> Resumen y Ventanas."
    L["You opened %s (%s) with SocialCentral integration enabled.\nWould you like this shortcut to open directly on the SocialCentral tab instead of Blizzard's default tab?"] = "Abriste %s (%s) con la integración de SocialCentral activada.\n¿Deseas que este atajo abra directamente en la pestaña de SocialCentral en lugar de la pestaña oficial de Blizzard?"
    L["Anyone in the guild need Stratholme or Scholomance?"] = "¿Alguien en la hermandad necesita Stratholme o Scholomance?"
    L["Automatically pauses minimap message previews while you are inside 5-player Dungeons or instanced scenarios."] = "Pausa automáticamente las vistas previas junto al minimapa mientras estás dentro de Mazmorras de 5 jugadores o gestas instanciadas."
