    L["Account-Ignored players also trigger Group Avoid warnings, LFG warnings, and Target Radar alerts. Never stores BattleTags or Real IDs."] = "Los jugadores en Ignorados de la Cuenta también activan avisos de Grupo, Buscador y Radar de Objetivos. Nunca guarda BattleTags ni Real IDs."
    L["Add details (optional)..."] = "Añadir detalles (opcional)..."
    L["Add extra words or short phrases to hide in public channels when Anti-Spam Shield is enabled."] = "Añade palabras o frases cortas adicionales para ocultar en canales públicos cuando el Escudo Anti-Spam esté activo."
    L["Add keywords like 'Crusader' or 'Onyxia' above to get instant alerts from busy city chats."] = "Añade palabras clave como 'Cruzado' u 'Onyxia' arriba para recibir alertas al instante en chats concurridos."
    L["Are you sure you want to clear the session filtered messages log?"] = "¿Seguro que deseas limpiar el registro de mensajes filtrados de esta sesión?"
    L["Are you sure you want to remove '%s' from your Account Ignore list?"] = "¿Seguro que deseas eliminar a '%s' de tu lista de Ignorados de la Cuenta?"
    L["Automatically hides messages in Blizzard's chat windows from anyone on your unlimited Account Ignore list without consuming WoW's 50-slot per-character ignore cap."] = "Oculta automáticamente en el chat oficial de WoW los mensajes de cualquier jugador en tu lista ilimitada de Ignorados de la Cuenta sin gastar el límite de 50 espacios por personaje."
    L["Block"] = "Bloquear"
    L["Blocked Keyword"] = "Palabra Bloqueada"
    L["Blocks a player across all characters on your account with a reason, optional expiration, and automatic official chat hiding without using WoW's 50-slot character ignore limit."] = "Bloquea a un jugador en todos los personajes de tu cuenta con motivo, duración opcional y ocultado automático en el chat oficial sin usar el límite de 50 espacios."
    L["Busy / AFK"] = "Ocupado / Ausente"
