    L["Character Name:"] = "Nombre del Personaje:"
    L["Chat Shield, Account Ignores & Clickable Links"] = "Protección de Chat, Ignorados de la Cuenta y Enlaces Clicables"
    L["Chat hidden"] = "Chat oculto"
    L["Chat visible"] = "Chat visible"
    L["Checks Trade, General, World, and LFG channels for your name, nicknames, and custom keywords (automatically skipping blocked/spam messages)."] = "Supervisa los canales Comercio, General, Mundo y LFG buscando tu nombre, apodos y palabras clave (omitiendo automáticamente mensajes bloqueados/spam)."
    L["Checks incoming Guild and Officer messages for your name, nicknames, and custom keywords."] = "Supervisa los mensajes de Hermandad y Oficial buscando tu nombre, apodos y palabras clave."
    L["Checks incoming Party, Raid, and Instance messages for your name, nicknames, and custom keywords."] = "Supervisa los mensajes de Grupo, Banda e Instancia buscando tu nombre, apodos y palabras clave."
    L["Checks nearby Say and Yell messages for your name, nicknames, and custom keywords."] = "Supervisa los mensajes cercanos en Decir y Gritar buscando tu nombre, apodos y palabras clave."
    L["Clear Log"] = "Limpiar Registro"
    L["Click a sender name above to reply, or click 'Keywords' to configure."] = "Haz clic en el nombre de un remitente arriba para responder o en 'Palabras Clave' para configurar."
    L["Click any highlighted link to open SocialCentral's Copy Link popup ready for Ctrl+C."] = "Haz clic en cualquier enlace resaltado para abrir la ventana de copia de SocialCentral lista para Ctrl+C."
    L["Click any row to copy the message, edit/remove an Account Ignore, or block a spammer permanently."] = "Haz clic en cualquier fila para copiar el mensaje, editar/quitar un Ignorado de la Cuenta o bloquear a un spammer."
    L["Click any sender name to whisper or open chat, or click Keywords to edit monitored words."] = "Haz clic en el nombre de cualquier remitente para susurrar o abrir chat, o en Palabras Clave para editar términos."
