    L["On my way from {zone}!"] = "¡En camino desde {zona}!"
    L["On my way! ({zone})"] = "¡En camino! ({zona})"
    L["Opens the Social directory filtered directly to your Account Ignores list where you can view reasons, timers, add new blocks, or unblock players."] = "Abre el directorio Social filtrado directamente en tus Ignorados de la Cuenta para ver motivos, plazos, añadir bloqueos o desbloquear jugadores."
    L["Optional Note:"] = "Nota Opcional:"
    L["Other"] = "Otro"
    L["Party / Raid / Instance"] = "Grupo / Banda / Instancia"
    L["Highlights matched words in gold directly inside chat messages, triggers optional alerts, and logs matches in the Mentions Radar whenever your name, nicknames, or keywords appear in selected channels."] = "Resalta en dorado las palabras coincidentes dentro de los mensajes del chat, lanza alertas opcionales y registra en el Radar de Menciones cuando aparezcan tu nombre, apodos o palabras clave."
    L["Permanent"] = "Permanente"
    L["Personal nicknames / alt names (comma-separated):"] = "Apodos personales / nombres de alts (separados por comas):"
    L["Play audio chime on mention or keyword match"] = "Reproducir sonido al detectar mención o palabra clave"
    L["Plays a subtle audio chime whenever a monitored mention or custom keyword is detected in chat."] = "Reproduce un sonido sutil cada vez que se detecte una mención o palabra clave supervisada en el chat."
    L["Press Ctrl+C to copy this link to your clipboard."] = "Pulsa Ctrl+C para copiar este enlace al portapapeles."
    L["Protects your chat across all characters with an unlimited Account Ignore list, optional public Anti-Spam Shield, and 1-click copyable Discord/Web links."] = "Protege tu chat en todos tus personajes con Ignorados de la Cuenta ilimitados, Escudo Anti-Spam público opcional y enlaces de Discord/Web clicables en 1 clic."
    L["Public Channels (Trade/General)"] = "Canales Públicos (Comercio/General)"
    L["Reason:"] = "Motivo:"
    L["Reduces wall-of-text repetition in Trade and World channels without affecting guild or party chat."] = "Reduce mensajes repetidos seguidos en Comercio y Mundo sin afectar el chat de hermandad o grupo."
    L["Repeated Flood"] = "Flood Repetido"
    L["Save Block"] = "Guardar Bloqueo"
    L["Say"] = "Decir"
    L["Say / Yell"] = "Decir / Gritar"
    L["Scammer"] = "Estafador"
    L["Sends a local sample mention to preview the Notification Toast, chime, and Mentions Radar log."] = "Envía una mención de ejemplo local para probar el Toast, el sonido y el registro en el Radar de Menciones."
    L["Separate entries with commas (e.g. 'Rapha, MainName'). Matching is case- and accent-insensitive."] = "Separa con comas (p. ej. 'Rapha, Principal'). La búsqueda ignora mayúsculas y acentos."
    L["Separate entries with commas (e.g. 'gdkp, boost, carry'). Ignored for Friends, Guild, and Group members."] = "Separa con comas (p. ej. 'gdkp, boost, carry'). Nunca afecta a Amigos, Hermandad ni Grupo."
    L["Separate keywords with commas (e.g. 'Onyxia, Crusader, Portal, BRD'). Matching ignores accents and capitalization."] = "Separa palabras clave con comas (p. ej. 'Onyxia, Cruzado, Portal, BRD'). Ignora acentos y mayúsculas."
    L["Separate multiple entries with commas (e.g. 'Onyxia, Crusader, Portal, Tank'). Respects Do Not Disturb and Auto-Silence in Instances."] = "Separa varios términos con comas (p. ej. 'Onyxia, Cruzado, Portal, Tank'). Respeta No Molestar y Silenciar en Instancias."
    L["Shows every message hidden this session by your Account Ignore list or the optional Public Anti-Spam Shield so nothing legitimate is ever lost silently."] = "Muestra cada mensaje oculto esta sesión por Ignorados de la Cuenta o el Escudo Anti-Spam para que nada legítimo se pierda."
    L["Spam / RMT"] = "Spam / RMT"
    L["Spammer"] = "Spammer"
    L["Stop alerting when your name, nickname, or custom keywords appear in chat."] = "Dejar de avisar cuando tu nombre, apodo o palabras clave aparezcan en el chat."
    L["Suppress repeated identical public messages (flood) from strangers"] = "Bloquear mensajes públicos repetidos seguidos (flood) de desconocidos"
    L["Target a player first."] = "Selecciona primero a un jugador como objetivo."
    L["Test Mention Alert"] = "Probar Alerta de Mención"
    L["Toxic"] = "Tóxico"
    L["Trade & Craft"] = "Comercio y Profesiones"
    L["Turns Discord invite links (discord.gg/...) and web URLs (https://...) into clickable links in both SocialCentral Conversations and official WoW chat."] = "Convierte invitaciones de Discord (discord.gg/...) y URLs web (https://...) en enlaces clicables tanto en Conversaciones de SocialCentral como en el chat oficial."
    L["Unblock"] = "Desbloquear"
    L["Uncheck for silent visual toast and Mentions Radar logging only."] = "Desmarca para recibir solo el aviso visual y el registro silencioso en el Radar de Menciones."
    L["Use a character name (BattleTags are never stored)."] = "Usa el nombre de un personaje (nunca se guardan BattleTags)."
    L["Useful when raid leaders call your name or role in chat."] = "Útil cuando los líderes de banda llaman tu nombre o función en el chat."
    L["Watch selected chat channels for custom words or short phrases such as bosses, dungeons, enchants, or portals."] = "Supervisa los canales seleccionados buscando palabras o frases cortas como jefes, mazmorras, encantamientos o portales."
    L["When Anti-Spam Shield is active, hides duplicate identical messages sent by the same stranger in public channels within 45 seconds."] = "Con el Escudo Anti-Spam activo, oculta mensajes idénticos repetidos enviados por el mismo desconocido en canales públicos en un plazo de 45 segundos."
    L["Yell"] = "Gritar"
    L["You can also use /sc ignore <name> anytime."] = "También puedes usar /sc ignore <nombre> en cualquier momento."
    L["Zero network messages are sent; purely local preview."] = "No se envía ningún mensaje de red; vista previa 100% local."
    L["e.g. Onyxia, Crusader, Portal, BRD"] = "p. ej. Onyxia, Cruzado, Portal, BRD"
    L["e.g. Rapha, Tank, MainName"] = "p. ej. Rapha, Tank, Principal"
    L["Minimum interval between message sounds (anti-spam):"] = "Intervalo mínimo entre sonidos de mensaje (anti-spam):"
    L["Help: Message Sound Cooldown"] = "Ayuda: Intervalo del Sonido de Mensaje"
    L["Prevents rapid spam from repeating the message notification sound. No new message chime will play until at least this many seconds have passed (6 seconds by default, 3 seconds minimum)."] = "Evita que el spam rápido repita el sonido de notificación de mensajes. No volverá a sonar ningún aviso hasta que pase al menos este tiempo en segundos (6 segundos por defecto, mínimo 3 segundos)."
    L["Applies globally and per sender across Whispers, Battle.net, Rooms, Mentions, and mirrored Guild/Group chat."] = "Se aplica globalmente y por remitente en Susurros, Battle.net, Salas, Menciones y chat reflejado de Hermandad/Grupo."
    L["Test Message Sound"] = "Probar Sonido de Mensaje"
    L["Help: Test Message Sound"] = "Ayuda: Probar Sonido de Mensaje"
    L["Plays the incoming message notification chime so you can verify your volume and anti-spam interval."] = "Reproduce el sonido de notificación de mensaje entrante para comprobar tu volumen y el intervalo anti-spam."
    L["Click repeatedly to confirm the anti-spam cooldown prevents rapid re-triggering within the chosen interval."] = "Haz clic varias veces seguidas para comprobar que la protección anti-spam evita que el sonido se repita dentro del intervalo elegido."
    L["%d boss(es)"] = "%d jefe(s)"
    L["%s logged: %s — %s (%d members). View in /sc runs"] = "%s registrada: %s — %s (%d miembros). Ver en /sc runs"
    L["...and %d more"] = "...y %d más"
    L["Are you sure you want to delete all %d recorded dungeon and raid runs?"] = "¿Seguro que deseas eliminar las %d mazmorras y bandas registradas?"
    L["Armed"] = "Preparado"
    L["Automatically saves each dungeon or raid that actually enters combat, storing teammate names, classes, roles, bosses, and duration from the 1st enemy pulled until a member leaves or the run finishes."] = "Guarda automáticamente cada mazmorra o banda que realmente entra en combate, almacenando nombres, clases, roles, jefes derrotados y la duración desde el 1.er enemigo atacado hasta que un miembro abandona el grupo o termina la estancia."
    L["Avoid / Red Flag"] = "Evitar / Alerta"
    L["Bosses Defeated"] = "Jefes Derrotados"
    L["Clear Dungeon Log"] = "Limpiar Historial de Mazmorras"
    L["Click for teammate actions, copy summary, or delete"] = "Clic para acciones con compañeros, copiar resumen o eliminar"
    L["Completed"] = "Completada"
    L["Copy Run Summary"] = "Copiar Resumen de Mazmorra"
    L["Delete This Run"] = "Eliminar Esta Mazmorra"
    L["Disable Recording"] = "Desactivar Registro"
    L["Dungeon & Raid Group Log"] = "Registro de Grupos de Mazmorra y Banda"
    L["Dungeon & Raid Log"] = "Historial de Mazmorras"
    L["Dungeon & Raid recording disabled. Re-enable anytime in Settings -> Summary & Windows -> Dungeon & Raid Group Log."] = "Registro de Mazmorras y Bandas desactivado. Reactívalo cuando quieras en Configuración -> Resumen y Ventanas -> Registro de Grupos de Mazmorra y Banda."
    L["Dungeon Log"] = "Mazmorras"
    L["Duration (1st pull to end)"] = "Duración (1.er combate hasta el fin)"
    L["Ended By"] = "Finalizada por"
    L["Entered another instance"] = "Entró en otra estancia"
    L["Exited instance"] = "Salió de la estancia"
    L["Help: Dungeon & Raid Log"] = "Ayuda: Historial de Mazmorras y Bandas"
    L["Help: Record Dungeon & Raid Log"] = "Ayuda: Registrar Mazmorras y Bandas"
    L["In Progress"] = "En Curso"
    L["Instance reset"] = "Estancia reiniciada"
    L["Joined mid-run"] = "Se unió a mitad"
    L["Keep Recording"] = "Seguir Registrando"
    L["Left early"] = "Salió antes"
    L["Left group"] = "Dejó el grupo"
    L["Member left group"] = "Miembro dejó el grupo"
    L["No matching dungeon or raid runs found."] = "No se encontraron mazmorras o bandas coincidentes."
    L["No started dungeons or raids recorded yet. Runs are logged automatically from the 1st enemy pulled."] = "Aún no se han registrado mazmorras o bandas iniciadas. El registro empieza automáticamente en el 1.er enemigo atacado."
    L["Open Dungeon & Raid Log"] = "Abrir Historial de Mazmorras"
    L["Open Log"] = "Abrir Historial"
    L["Opens your searchable progression history of started dungeon and raid groups with all teammates and run times."] = "Abre tu historial consultable de grupos de mazmorras y bandas iniciadas con todos los compañeros y el tiempo total de cada una."
    L["Passively records started dungeon and raid groups, teammate names, roles, bosses defeated, and total run time from the first enemy pulled until the run ends."] = "Registra pasivamente grupos de mazmorras y bandas que realmente comenzaron, con el nombre de cada miembro, rol, jefes derrotados y tiempo total desde el primer enemigo atacado hasta el final."
    L["Record started dungeon & raid groups (teammates & total time)"] = "Registrar grupos de mazmorras y bandas iniciadas (compañeros y tiempo total)"
    L["Recorded Runs"] = "Registros Guardados"
    L["Recorded runs: %d / 120 (event-driven, zero lag)"] = "Registros guardados: %d / 120 (por eventos, cero lag)"
    L["Recording is paused. Click 'Recording: OFF' to re-enable."] = "Registro en pausa. Haz clic en 'Registro: OFF' para reactivar."
    L["Recording: OFF"] = "Registro: OFF"
    L["Recording: ON"] = "Registro: ON"
    L["Remove %s from your Dungeon & Raid Log?"] = "¿Eliminar %s de tu Historial de Mazmorras y Bandas?"
    L["Search by dungeon, player or boss..."] = "Buscar por mazmorra, jugador o jefe..."
    L["Session ended"] = "Sesión finalizada"
    L["Shows started dungeons and raids with all teammate names, roles, bosses defeated, and total run time from the 1st enemy pulled."] = "Muestra mazmorras y bandas iniciadas con los nombres de todos los miembros, roles, jefes derrotados y el tiempo total desde el 1.er enemigo atacado."
    L["Solo / no teammates recorded"] = "Solo / sin compañeros registrados"
    L["Started / Ended"] = "Inicio / Fin"
    L["Teammates"] = "Compañeros"
    L["This Character"] = "Este Personaje"
    L["Ultra-lightweight: only runs when a dungeon/raid actually starts combat, with zero background polling. You can change this anytime in Settings -> Summary & Windows -> Dungeon & Raid Group Log."] = "Ultraligero: solo se activa cuando una mazmorra o banda entra en combate, sin escaneos en segundo plano. Puedes cambiarlo en cualquier momento en Configuración -> Resumen y Ventanas -> Registro de Grupos de Mazmorra y Banda."
    L["Uncheck to pause recording. Already recorded runs remain available in the Dungeon & Raid Log until you clear them."] = "Desmarca para pausar nuevos registros. Las mazmorras ya guardadas seguirán visibles en el historial hasta que lo limpies."
    L["Press I to open Blizzard's Group Finder and apply directly on the official Browse tab."] = "Pulsa I para abrir el Buscador de Grupos de Blizzard y solicitar directamente en la pestaña oficial Explorar."
    L["View anytime in /sc -> Dungeon & Raid Log (or /sc runs). Uses zero combat-log scanning and keeps up to 120 compact runs so PC impact stays negligible."] = "Consúltalo cuando quieras en /sc -> Historial de Mazmorras (o /sc runs). No escanea el registro de combate y guarda hasta 120 registros compactos para un impacto mínimo en tu PC."
    L["You can also open this view anytime via '/sc runs' or from the Group tab inside the main SocialCentral window."] = "También puedes abrirlo directamente con '/sc runs' o desde la pestaña Grupo en la ventana principal de SocialCentral."
    L["Your first dungeon/raid group has been recorded! You can check who you ran with and how long each run took anytime via /sc (Dungeon & Raid Log). Would you like to keep recording future runs?"] = "¡Tu primera mazmorra/banda ha sido registrada! Puedes consultar con quién jugaste y el tiempo total de cada una cuando quieras en /sc (Historial de Mazmorras). ¿Quieres seguir registrando las próximas?"
    L["waiting for 1st pull"] = "esperando 1.er combate"
    L["Create a Private Addon Room for synced group or friend chats."] = "Crea una Sala Privada del Addon para chats sincronizados con tu grupo o amigos."
    L["Displays the selected character's full profile and character management actions."] = "Muestra el perfil completo del personaje seleccionado y acciones de gestión."
    L["Click 'Actions' to view the Web Armory link or remove an offline alt, and switch between 'Overview', 'Items', 'Gear', and 'Account' below."] = "Haz clic en 'Acciones' para copiar el enlace de la Armería o eliminar un alt desconectado, y cambia entre 'Resumen', 'Objetos', 'Equipo' y 'Cuenta' abajo."
    L["Plays a live sample message preview beside your Minimap with expand and close-to-SC-icon animation."] = "Reproduce una vista previa animada de mensaje junto al Minimapa con efecto de expansión y cierre hacia el icono SC."
    L["You can also test specific channels anytime using '/sc preview whisper', 'bnet', 'group', or 'guild'."] = "También puedes probar canales específicos cuando quieras con '/sc preview whisper', 'bnet', 'group' o 'guild'."
    L["Copy Official Chat"] = "Copiar Chat Oficial"
    L["No chat messages captured yet on this chat window."] = "Aún no hay mensajes capturados en esta ventana de chat."
    L["Press Ctrl+C to copy recent chat lines."] = "Pulsa Ctrl+C para copiar las líneas recientes del chat."
    L["Lv."] = "Nv."
    L["Official Window"] = "Ventana Oficial"
    L["Click: Toggle features or disable here"] = "Clic: Alternar funciones o desactivar aquí"
    L["Tab 1 Mirror Bar"] = "Barra Espejo de Pestaña 1"
    L["On"] = "Activo"
    L["Off"] = "Apagado"
    L["Show Official Tab 1 Mirror Bar"] = "Mostrar Barra Espejo Oficial de Pestaña 1"
    L["Official Chat"] = "Chat Oficial"
    L["Short Channels"] = "Canales Cortos"
    L["Sender Badges"] = "Etiquetas de Jugador"
    L["Clickable URLs"] = "Enlaces Clicables (URLs)"
    L["EditBox History"] = "Historial de Barra"
    L["Fast Scroll"] = "Desplazamiento Rápido"
    L["Anti-Spam Shield"] = "Escudo Anti-Spam"
    L["Shorten public channel names"] = "Acortar nombres de canales públicos"
    L["Show [Lv], [Main], [+]/[Avoid] tags"] = "Mostrar etiquetas [Nv], [Main], [+]/[Evitar]"
    L["Remember typed chat history (EditBox)"] = "Recordar historial escrito en el chat (EditBox)"
    L["Fast scroll (Shift/Ctrl + Wheel)"] = "Desplazamiento rápido (Shift/Ctrl + Rueda)"
    L["Hide Account-Ignored chat"] = "Ocultar chat de Ignorados de Cuenta"
    L["Public Chat Anti-Spam Shield"] = "Escudo Anti-Spam en Chat Público"
    L["Hide quick [SC] button here"] = "Ocultar botón rápido [SC] aquí"
    L["Official Chat [SC] button hidden. Re-enable anytime in Settings (/sc)."] = "Botón [SC] del Chat Oficial ocultado. Reactívalo cuando quieras en Ajustes (/sc)."
    L["Disable Official Chat Enhancements"] = "Desactivar Funciones en Chat Oficial"
    L["Official Chat enhancements disabled. Re-enable anytime in Settings (/sc)."] = "Funciones del Chat Oficial desactivadas. Reactívalas cuando quieras en Ajustes (/sc)."
    L["Quick Select Alt Recipient attached to Blizzard's Mailbox."] = "Selector rápido de destinatario Alt acoplado al Correo oficial de Blizzard."
    L["Disable in this window"] = "Desactivar en esta ventana"
    L["Disabled in this window. Re-enable anytime in Settings (/sc)."] = "Desactivado en esta ventana. Reactívalo cuando quieras en Ajustes (/sc)."
    L["Official Chat (ChatFrame)"] = "Chat Oficial (ChatFrame)"
    L["Help: Official Chat (ChatFrame)"] = "Ayuda: Chat Oficial (ChatFrame)"
    L["Master switch for SocialCentral features injected directly into Blizzard's official Chat windows (short channels, sender badges, Copy Chat, fast scroll, and [SC] button)."] = "Interruptor maestro de las funciones de SocialCentral integradas en las ventanas oficiales de Chat de Blizzard (canales cortos, etiquetas de remitente, Copiar Chat, desplazamiento rápido y botón [SC])."
    L["Uncheck here or click [SC] beside Chat -> 'Disable in this window' to keep Blizzard Chat 100% vanilla."] = "Desmarca aquí o pulsa [SC] junto al Chat -> 'Desactivar en esta ventana' para mantener el Chat de Blizzard 100% original."
    L["Official Mailbox (Alts)"] = "Correo Oficial (Alts)"
    L["Help: Official Mailbox (Alts)"] = "Ayuda: Correo Oficial (Alts)"
    L["Attaches the 'Alts v' recipient selector and standardized [SC] quick toggle directly inside Blizzard's Send Mail window."] = "Acopla el selector de destinatario 'Alts v' y el botón rápido estandarizado [SC] dentro de la ventana de envío de Correo de Blizzard."
    L["Uncheck here or click [SC] beside the Mailbox field to keep Blizzard's Send Mail window completely unmodified."] = "Desmarca aquí o pulsa [SC] junto al campo de destinatario del Correo para mantener el Correo de Blizzard sin cambios."
    L["Official Chat & Quick [SC] Controls"] = "Chat Oficial y Controles Rápidos [SC]"
    L["Help: Official Chat Enhancements"] = "Ayuda: Mejoras del Chat Oficial"
    L["Controls SocialCentral enhancements directly inside Blizzard's official Chat windows (short channels, clickable sender tags, EditBox history, fast mouse wheel scroll, Copy Official Chat, and the quick [SC] control button)."] = "Controla las mejoras de SocialCentral directamente en las ventanas oficiales de Chat de Blizzard (canales cortos, etiquetas clicables de remitente, historial de EditBox, desplazamiento rápido, Copiar Chat Oficial y el botón rápido [SC])."
    L["Every feature below can be toggled here or directly via the standardized [SC] button beside Blizzard's Official Chat, Mailbox, and Group Finder (I)."] = "Cada función puede alternarse aquí o directamente desde el botón estandarizado [SC] junto al Chat Oficial, Correo y Buscador de Grupos (I)."
    L["Enable Official Chat Enhancements (ChatFrame)"] = "Activar Mejoras en Chat Oficial (ChatFrame)"
    L["Help: Master Official Chat Toggle"] = "Ayuda: Interruptor Maestro de Chat Oficial"
    L["Master switch for SocialCentral features injected directly into Blizzard's official Chat windows."] = "Interruptor general para las funciones de SocialCentral inyectadas en las ventanas oficiales de Chat de Blizzard."
    L["Uncheck to return Blizzard's Chat frames to 100% vanilla while keeping all settings ready to re-enable anytime."] = "Desmarca para devolver los marcos de Chat oficiales a su comportamiento 100% original manteniendo tus ajustes listos para reactivar."
    L["Show quick [SC] control button beside Official Chat"] = "Mostrar botón rápido [SC] junto al Chat Oficial"
    L["Help: Quick [SC] Chat Button"] = "Ayuda: Botón Rápido [SC] del Chat"
    L["Shows the standardized [SC] quick-menu button beside Blizzard's main Chat frame so you can toggle Short Channels, Sender Badges, History, or Copy Chat in 1 click."] = "Muestra el botón de menú rápido estandarizado [SC] junto al Chat principal de Blizzard para alternar Canales Cortos, Etiquetas, Historial o Copiar Chat en 1 clic."
    L["You can also right-click the button to hide it anytime and re-enable it right here."] = "También puedes hacer clic derecho en el botón para ocultarlo cuando quieras y reactivarlo aquí mismo."
    L["Shorten public channel names in Official Chat ([LFG], [Trade], [Defense])"] = "Acortar nombres de canales públicos en Chat Oficial ([LFG], [Comercio], [Defensa])"
    L["Help: Short Official Channels"] = "Ayuda: Canales Cortos en Chat Oficial"
    L["Replaces verbose channel prefixes such as [LookingForGroup] or [General - Stormwind City] with compact [LFG], [General], and [Defense] tags inside official chat."] = "Sustituye prefijos largos como [BuscandoGrupo] o [General - Ventormenta] por siglas compactas como [LFG], [General] y [Defensa] dentro del chat oficial."
    L["Applies cleanly via Blizzard's message filter with zero UI taint."] = "Se aplica limpiamente mediante el filtro oficial de mensajes de Blizzard sin taint."
    L["Show [Lv], [Main], and [+]/[AVOID] sender tags in Official Chat"] = "Mostrar etiquetas [Nv], [Main] y [+]/[EVITAR] de remitente en Chat Oficial"
    L["Help: Official Sender Badges"] = "Ayuda: Etiquetas de Remitente en Chat Oficial"
    L["Prepends cached [Lv.X], linked [Main], and saved [+] Good / [AVOID] reputation badges beside known players directly in Blizzard's chat window."] = "Añade antes del remitente las etiquetas guardadas [Nv.X], [Main] vinculado y reputación [+] Bueno / [EVITAR] de jugadores conocidos directamente en el chat oficial."
    L["Reads strictly from already-known guild, friend, or Social notes memory (zero automatic /who queries)."] = "Lee estrictamente datos ya conocidos de hermandad, amigos o notas sociales (cero consultas /who automáticas)."
    L["Remember typed Official Chat history across /reload (Alt+Up / Down)"] = "Recordar historial escrito en Chat Oficial tras /reload (Alt+Arriba / Abajo)"
    L["Help: Persistent EditBox History"] = "Ayuda: Historial Persistente de EditBox"
    L["Saves your last 25 sent lines per character (excluding Battle.net tokens for privacy) so you can recall them with Up/Down arrows even after reloading UI."] = "Guarda tus últimas 25 líneas enviadas por personaje (omitiendo tokens de Battle.net por privacidad) para recuperarlas con las flechas incluso tras recargar la interfaz."
    L["Uncheck anytime to stop saving chat bar history across reloads."] = "Desmarca cuando quieras para dejar de guardar el historial de la barra entre recargas."
    L["Fast scroll in Official Chat (Shift+Wheel top/bottom, Ctrl+Wheel page)"] = "Desplazamiento rápido en Chat Oficial (Shift+Rueda inicio/fin, Ctrl+Rueda página)"
    L["Help: Fast Official Chat Scroll"] = "Ayuda: Desplazamiento Rápido en Chat Oficial"
    L["Lets you jump straight to the top or bottom of official chat with Shift+MouseWheel, or scroll 4 lines at a time with Ctrl+MouseWheel."] = "Te permite saltar directo al principio o final del chat oficial con Shift+Rueda del ratón, o avanzar 4 líneas a la vez con Ctrl+Rueda."
    L["Disable anytime if you prefer standard single-line WoW mousewheel scrolling."] = "Desactiva cuando quieras si prefieres el desplazamiento estándar de 1 línea de WoW."
    L["Help: Copy Official Chat"] = "Ayuda: Copiar Chat Oficial"
    L["Opens a clean Ctrl+C copy window containing the most recent lines rendered in Blizzard's main Official Chat window."] = "Abre una ventana limpia lista para Ctrl+C con las líneas más recientes mostradas en la ventana principal del Chat Oficial de Blizzard."
    L["You can also use '/sc copychat' (or '/sc copychat 80' to choose how many lines) or click the [SC] button beside Official Chat."] = "También puedes usar '/sc copychat' (o '/sc copychat 80' para elegir cuántas líneas copiar) o pulsar el botón [SC] junto al Chat Oficial."
    L["Manual Chat"] = "Chat manual"
    L["Manual Chat (SocialCentral)"] = "Chat manual (SocialCentral)"
    L["Shared Library"] = "Biblioteca compartida"
    L["Origin: %s"] = "Origen: %s"
    L["Identify error origin in chat"] = "Identificar origen de errores en el chat"
    L["Identify addon origin on chat errors ([Origin: Addon])"] = "Identificar qué addon generó errores en el chat ([Origen: Addon])"
    L["Help: Chat Error Origin Identifier"] = "Ayuda: Identificador de Origen de Errores en el Chat"
    L["Correlates unblocked yellow system errors in Official Chat (such as offline player whispers, missing group/guild, or message throttles) with recent addon or manual chat activity and appends [Origin: Addon] to show what triggered the error."] = "Correlaciona errores amarillos del sistema mostrados en el Chat Oficial (como susurros a jugadores desconectados, avisos de grupo/hermandad o límite de envíos) con actividad reciente de addons o envíos manuales, añadiendo [Origen: Addon] en la línea."
    L["Keep checked to immediately see which addon is causing 'No player named...' spam or chat errors. SocialCentral's own silent presence checks remain automatically hidden."] = "Déjalo marcado para ver al instante qué addon está causando spam de 'No hay ningún jugador...' u otros errores. Las comprobaciones silenciosas del propio SocialCentral siguen ocultándose automáticamente."
    L["Show Official Tab 1 Mirror Bar in Group Finder (I)"] = "Mostrar Barra Espejo Oficial de Pestaña 1 en Buscador de Grupos (I)"
    L["Help: Official LFG Tab 1 Mirror Bar"] = "Ayuda: Barra Espejo Oficial de Pestaña 1 en Buscador (I)"
    L["Displays the compact SocialCentral quick-mirror bar and standardized [SC] control button below Blizzard's Group Finder (I) Browse tab."] = "Muestra la barra compacta de espejo rápido de SocialCentral y el botón estandarizado [SC] debajo de la pestaña Explorar del Buscador de Grupos (I) de Blizzard."
    L["You can toggle this anytime from here or via the [SC] button directly on Blizzard's Group Finder bar."] = "Puedes activarlo o desactivarlo aquí o directamente mediante el botón [SC] en la barra del Buscador de Grupos de Blizzard."
