    L["Help: Official Professions (Recipes)"] = "Ayuda: Profesiones Oficiales (Recetas)"
    L["Passively catalogs each character's learned recipes when opening Blizzard's Profession window and attaches the standardized [SC] quick control button."] = "Cataloga pasivamente todas las recetas aprendidas al abrir la ventana oficial de Profesión de Blizzard y acopla el botón rápido estandarizado [SC]."
    L["Uncheck here or click [SC] inside any Profession window -> 'Disable in this window' to stop indexing recipes and hide the button."] = "Desmarca aquí o pulsa [SC] en la ventana de Profesión -> 'Desactivar en esta ventana' para detener el indexado y ocultar el botón."
    L["Show 'Craftable by Alt / Guild' and Recipe hints in tooltips"] = "Mostrar 'Fabricable por Alt / Hermandad' y avisos de Receta en tooltips"
    L["Help: Craftable & Recipe Tooltips"] = "Ayuda: Tooltips de Crafteo y Recetas"
    L["Shows directly on Blizzard item tooltips which Alt or Guildmate can craft the hovered item, and whether a hovered Recipe scroll is already learned or needed by an Alt."] = "Muestra directamente en el tooltip oficial de cualquier objeto qué Alt o compañero de Hermandad sabe fabricarlo, y si una Receta/Fórmula ya está aprendida o falta en algún Alt."
    L["Open each character's Profession window once so SocialCentral indexes their recipes for Auction House, Bags, Mail, and Chat links."] = "Abre la ventana de Profesión una vez con cada personaje para que SocialCentral use sus recetas en Subasta, Bolsas, Correo y enlaces del Chat."
    L["Answer online Guild Recipe Searches (requires Clan Sync)"] = "Responder búsquedas de recetas de Hermandad conectado (requiere Sync)"
    L["Help: Guild Recipe Replies"] = "Ayuda: Respuestas de Receta en Hermandad"
    L["Allows your character to reply quietly (Trickle rate-limited) when a guildmate clicks 'Ask Guild' inside Guild Professions (J) looking for a learned recipe."] = "Permite que tu personaje responda en silencio (con límite anti-spam) cuando un compañero pulse 'Consultar Hermandad' en Profesiones (J) buscando una receta."
    L["Requires 'Enable Clan guild sync (opt-in)' above; never sends replies in combat or floods guild chat."] = "Requiere activar 'Sincronización de Hermandad (opt-in)' arriba; nunca envía respuestas en combate ni satura el chat."
    L["Alert in Official Chat when Watched Dungeon or Raid groups appear"] = "Avisar en el Chat Oficial cuando aparezcan grupos de Mazmorras o Bandas Vigiladas"
    L["All Dungeons & Raids"] = "Todas las Mazmorras y Bandas"
