    L["Press Ctrl+C to copy your SocialCentral backup, or paste a string below and click Import & Merge."] = "Presiona Ctrl+C para copiar tu respaldo de SocialCentral, o pega un texto abajo y pulsa Importar y Fusionar."
    L["Press Ctrl+C to copy your backup string, or paste a received string and click 'Import & Merge' to merge entries safely without overwriting active timers."] = "Presiona Ctrl+C para copiar el respaldo, o pega un texto recibido y pulsa 'Importar y Fusionar' para unir entradas sin sobrescribir temporizadores."
    L["Preventive Popup Alerts"] = "Alertas Preventivas en Popups"
    L["Prints Allied Guild chat messages directly inside Blizzard's main Official Chat window with <Guild> tags and clickable player whisper links."] = "Muestra los mensajes de Alianza de Hermandades directamente en el Chat Oficial de Blizzard con etiqueta <Hermandad> y enlaces clicables para susurrar."
    L["Prints a local summary with a clickable [Announce Missing Buffs] chat draft link — also accessible anytime via 'Audit Buffs' in O -> Group."] = "Imprime un resumen local con el enlace clicable [Anunciar Beneficios Faltantes] — también accesible desde el botón 'Auditar Buffs' en O -> Grupo."
