    L["Right-click: Silence, pin or close tab · Middle-click: Clear unread/draft"] = "Clic der.: Silenciar, anclar o cerrar pestaña · Clic central: Limpiar no leídos/borrador"
    L["Silence this tab for 5, 10, 30 minutes, until leaving a dungeon/raid, or permanently."] = "Silencia esta pestaña durante 5, 10, 30 minutos, hasta salir de una mazmorra/banda o permanentemente."
