    L["Checks online group members for missing Fortitude, Arcane Intellect, Mark of the Wild, active World Buffs, and Chronoboon Displacer."] = "Comprueba en los miembros conectados del grupo si faltan Entereza, Intelecto Arcano, Marca de lo Salvaje, Beneficios del Mundo y Desplazador de Cronobendición."
