    L["Lets officers create quick guild polls (2 to 5 choices) and guildmates vote live in real time."] = "Permite a los oficiales crear encuestas rápidas de hermandad (2 a 5 opciones) y votar en tiempo real."
    L["Lets you hold Alt+Left-Click on any player name in Blizzard chat, Conversations, or Quick Reply to invite them to your group, or Ctrl+Left-Click to open their Social Card."] = "Permite mantener Alt+Clic izq. en cualquier nombre de jugador en el chat de Blizzard, Conversaciones o Respuesta Rápida para invitar al grupo, o Ctrl+Clic izq. para abrir su Tarjeta Social."
    L["Lv %d+"] = "Nv %d+"
