    L["Masks Battle.net Real ID / BattleTag names and hides private Whisper or Room text across Minimap Previews, Notification Toasts, Quick Reply, Conversations, Recent Notifications, and Filtered Chat Log during streams or screenshots."] = "Oculta nombres Real ID / BattleTag de Battle.net y esconde textos privados de Susurros o Salas en Vistas Previas del Minimapa, Avisos Flotantes, Respuesta Rápida, Conversaciones, Notificaciones Recientes y Registro Filtrado durante streams o capturas."
