    L["Share my voluntary Social Profile in tooltips"] = "Compartir mi Perfil Social voluntario en tooltips"
    L["Shift+Left-Click continues to run Blizzard's native /who check unchanged."] = "Shift+Clic izquierdo sigue ejecutando la consulta /who nativa de Blizzard sin cambios."
