    L["Streamer / Privacy Mode (mask BattleTags and sensitive message previews)"] = "Modo Streamer / Privacidad (oculta BattleTags y vistas previas privadas)"
    L["Toggle anytime from Settings or directly from the Minimap right-click menu."] = "Actívalo en cualquier momento en Ajustes o en el menú contextual del Minimapa."
    L["View: Level, Professions & Gold"] = "Vista: Nivel, Profesiones y Oro"
    L["View: Resets, Reputations & Marks"] = "Vista: Reinicios, Reputaciones y Marcas"
    L["Vote on active Guild Polls or create a new poll for your guildmates."] = "Vota en encuestas activas de hermandad o crea una nueva encuesta."
    L["Whisper for invite!"] = "¡Susurra para invitación!"
    L["World Buffs & Chronoboon"] = "Beneficios del Mundo y Cronobendición"
    L["[Hidden in Streamer Mode]"] = "[Oculto en Modo Streamer]"
    L["e.g. 15/12 or Next Week"] = "ej: 15/12 o Próxima Semana"
    L["e.g. Chill dungeon tank, Discord ready"] = "ej: Tanque tranquilo p/ mazmorras, Discord listo"
    L["e.g. Friendly PvE/PvP guild clearing MC & BWL!"] = "ej: ¡Hermandad amigable PvE/PvP limpiando MC y BWL!"
    L["e.g. Healers, Warlocks, Tanks"] = "ej: Sanadores, Brujos, Tanques"
    L["e.g. Next Raid Night or Loot Rule?"] = "ej: ¿Próxima Noche de Banda o Regla de Botín?"
