    L["Pick the roles you want to perform or fill, then click Auto-Select anytime to match your current spec and continue to activities."] = "Elige los roles que quieres desempeñar o cubrir y pulsa Autoseleccionar en cualquier momento para coincidir con tu especialización actual y pasar a las actividades."
