    L["Click Tank/Heal/DPS buttons to cycle Any -> + Needs -> = Has, toggle All/Groups/Looking, or open Filters for Exclude Classes, Languages, Playstyle, Players Looking (Roles/Class/Level/Sort), and saved Presets."] = "Pulsa Tanque/Cura/DPS para alternar Cualquiera -> + Necesita -> = Ya tiene, alterna Todos/Grupos/Buscando o abre Filtros para Excluir Clases, Idiomas, Estilo, Jugadores Buscando (Roles/Clase/Nivel/Orden) y Preajustes."
