    L["Ignore party/raid members"] = "Ignorar miembros del grupo/banda"
    L["Open Watchlist"] = "Abrir Watchlist"
    L["Play alert sound"] = "Reproducir sonido de alerta"
    L["Preset: Dungeon & Raid"] = "Perfil: Mazmorra y Banda"
    L["Preset: Gather & World"] = "Perfil: Recolección y Mundo"
    L["Preset: Social & Guild"] = "Perfil: Social y Hermandad"
