    L["Press Ctrl+C to copy this loot roll breakdown."] = "Pulsa Ctrl+C para copiar este desglose de botín."
    L["Press Ctrl+C to copy this summary to your clipboard."] = "Pulsa Ctrl+C para copiar este resumen al portapapeles."
    L["Prevents accidental dragging of the fixed floating Roll Results button during combat or camera turns."] = "Evita arrastrar por accidente el botón fijo de Resultados durante combate o giros de cámara."
