    L["Show Fixed Roll Results Button"] = "Mostrar Botón Fijo de Resultados"
    L["Shows active group loot drops with Need, Greed, Disenchant, and Pass buttons, real-time teammate choices, roll numbers, current leader, and winners alongside automatic item level, stat, and recipe comparisons."] = "Muestra el botín activo del grupo con botones de Necesidad, Codicia, Desencantar y Pasar, elecciones en tiempo real, números, líder actual y ganador junto a la comparación automática de iLvl, estadísticas y recetas."
    L["Simulated Loot Winner Banner triggered."] = "Aviso simulado de Ganador de Botín mostrado."
