    L["Test"] = "Prueba"
    L["Tied!"] = "¡Empate!"
    L["Toggle anytime in SocialCentral Settings -> General & Tools"] = "Cámbialo cuando quieras en Ajustes -> General y Herramientas"
    L["Track group /roll (1-100) rounds passively from party/raid chat"] = "Registrar rondas de /roll (1-100) desde chat de grupo/banda"
    L["Uncheck to keep winner notifications silent without playing sound."] = "Desmarca para mantener las notificaciones del ganador sin sonido."
    L["Waiting for your roll"] = "Esperando tu tirada"
    L["When your party or raid uses /roll, players will be ranked here automatically (catching duplicate rolls and non 1-100 ranges)."] = "Cuando tu grupo o banda use /roll, los jugadores se ordenarán aquí automáticamente (detectando tiradas duplicadas o fuera de 1-100)."
    L["Winner"] = "Ganador"
    L["Winner:"] = "Ganador:"
    L["Won by Me"] = "Ganados por Mí"
    L["Would you like to activate SocialCentral's Group Loot Roll system with equipped-gear comparison, live party choices, and a fixed Roll Results button?"] = "¿Quieres activar el sistema de Botín en Grupo de SocialCentral con comparación de equipo, elecciones del grupo en vivo y botón fijo de Resultados?"
    L["YOU WON!"] = "¡GANASTE!"
    L["rolls"] = "tiradas"
    L["|cff9da7b5%d drops · |cffffea70%d won|r"] = "|cff9da7b5%d objetos · |cffffea70%d ganados|r"
    L["Announce Winners in Local Chat"] = "Anunciar Ganadores en Chat Local"
    L["Announce group loot winners locally in chat (with Results link)"] = "Anunciar ganadores de botín localmente en el chat (con enlace a Resultados)"
    L["Click Results to inspect all teammate rolls"] = "Pulsa Resultados para ver todas las tiradas"
    L["Displays SocialCentral's celebratory gold medallion animation at the top of your screen when you win a group loot drop."] = "Muestra la animación festiva del medallón dorado de SocialCentral arriba de la pantalla cuando ganas un botín en grupo."
    L["Epic Win Celebration"] = "Celebración Épica de Victoria"
    L["Help: Epic Loot Win Celebration"] = "Ayuda: Celebración Épica de Victoria"
    L["Help: Local Chat Winner Summary"] = "Ayuda: Resumen de Ganador en Chat"
    L["Hover the item icon for full comparison tooltips, Shift+Click to link in chat, Ctrl+Click to preview in Dressing Room, switch tabs when multiple items drop, or click Results to open the full Roll Results History window."] = "Pasa el ratón sobre el icono para comparar estadísticas, Shift+Clic para enlazar en el chat, Ctrl+Clic para probar en el Probador, cambia de pestaña si caen varios objetos o pulsa Resultados para abrir el Historial completo."
    L["Loot Roll"] = "Botín en Grupo"
    L["Prints a private colored summary line in your own chat window showing who won each group drop and their roll, along with a clickable [Results] link."] = "Muestra solo para ti una línea en color en el chat con quién ganó cada botín y su tirada, junto a un enlace clicable [Resultados]."
    L["Results"] = "Resultados"
    L["RollBtnDE"] = "Des."
    L["RollBtnGreed"] = "Cod."
    L["RollBtnNeed"] = "Nec."
    L["Show epic celebration splash when I win a group drop"] = "Mostrar celebración épica al ganar un botín en grupo"
    L["Triggers only when you win an item (does not clutter message notifications or Notification History)."] = "Se muestra solo cuando ganas un objeto (sin llenar las notificaciones de mensajes ni el Historial de Notificaciones)."
    L["Visible only to you (never sends automated messages to public or group chat)."] = "Visible solo para ti (nunca envía mensajes automáticos a chats públicos o de grupo)."
    L["Choices:"] = "Elecciones:"
    L["%d drops · %d won"] = "%d objetos · %d ganados"
    L["2. Last Group vs. Full History"] = "2. Último Grupo e Historial"
    L["Auto-hides in %dm %02ds after run end"] = "Se oculta automáticamente en %dm %02ds"
    L["By default, opening Roll Results always shows only the summary of your last dungeon, raid, or group session."] = "Por defecto, al abrir Resultados siempre se muestra solo el resumen de la última mazmorra, banda o último grupo."
    L["Choose 'During dungeon/raid (+3 min after)' (recommended), 'Always visible', or 'Hide button' (still accessible via /sc rolls or the Minimap menu)."] = "Elige 'En mazmorra/banda (+3 min)' (recomendado), 'Siempre visible' u 'Ocultar botón' (accesible vía /sc rolls o Minimapa)."
    L["Click 'Full History' whenever you explicitly want to view older drops from previous groups and runs."] = "Pulsa 'Historial Completo' solo cuando quieras ver botines antiguos de grupos y mazmorras anteriores."
    L["Controls the movable floating dice button that lets you inspect Loot Roll Results with one click (visible by default during dungeons or raids and for 3 minutes after they end)."] = "Controla el botón flotante móvil del dado para abrir Resultados de Botín (visible por defecto durante mazmorras o bandas y 3 minutos después de terminar)."
    L["During dungeon/raid (+3 min after)"] = "En mazmorra/banda (+3 min)"
    L["Full History"] = "Historial Completo"
    L["Group Participants:"] = "Participantes del Grupo:"
    L["Help: Roll History Scope"] = "Ayuda: Alcance del Historial"
    L["Last Group"] = "Último Grupo"
    L["Last Group Summary"] = "Resumen del Último Grupo"
    L["Last Group: %s (%d drops · %d won)"] = "Último grupo: %s (%d objetos · %d ganados)"
    L["Left-click: Open Last Group Summary\nShift+Click: Show Active Roll Card\nRight-click: Options & Visibility\nDrag: Move button"] = "Clic izquierdo: Resumen del Último Grupo\nShift+Clic: Ver Botín Activo\nClic derecho: Opciones y Visibilidad\nArrastrar: Mover botón"
    L["No drops in the latest group session (click Full History above to view older runs)."] = "Sin objetos en el último grupo (pulsa Historial Completo arriba para ver tiradas anteriores)."
    L["Open Loot Roll Results showing your latest dungeon, raid, or group summary (with an option inside for full history)."] = "Abrir Resultados de Botín con el resumen de tu última mazmorra, banda o grupo (con opción interna para el historial completo)."
    L["Opens Loot Roll Results focused on your last dungeon, raid, or group summary, with an explicit option inside the window to expand older history and passive Group /roll (1-100) rounds."] = "Abre Resultados de Botín centrado en el resumen de tu última mazmorra, banda o grupo, con opción explícita dentro para ver el historial completo y rondas /roll (1-100)."
    L["Opens focused on the summary of your latest dungeon, raid, or group session, with an explicit toggle inside to inspect older saved drops and Group /roll (1-100) rounds."] = "Abre centrado en el resumen de tu última mazmorra, banda o grupo, con un selector explícito dentro para consultar botines antiguos y rondas de /roll (1-100)."
    L["Scope"] = "Alcance"
    L["Showing all saved drops and previous groups."] = "Mostrando todos los botines guardados de grupos anteriores."
    L["Showing only your latest dungeon, raid, or group session."] = "Mostrando solo tu última mazmorra, banda o último grupo."
    L["Shows your latest dungeon, raid, or group loot summary."] = "Muestra el resumen de botín de tu última mazmorra, banda o grupo."
    L["You can also open this window anytime via the floating dice button (during/3 min after runs), Minimap right-click menu, Group panel, or /sc rolls."] = "También puedes abrir esta ventana desde el botón flotante del dado (en mazmorras/+3 min), menú del Minimapa, panel de Grupo o /sc rolls."
    L["Click: light up nearby herbs, ore & chests (halo + icon + banner).\nRight-click: lock button, toggle halo/chime, or settings."] = "Clic: iluminar hierbas, menas y cofres cercanos (halo, icono y aviso).\nClic derecho: fijar botón, halo/sonido o ajustes."
    L["Turns on WoW's official world-object detection so herbs, ore, and chests light up with a glow halo, game icon, and screen banner."] = "Activa la detección oficial de objetos del mundo de WoW para iluminar hierbas, menas y cofres con halo brillante, icono y aviso superior."
    L["Choose Enable Highlight to turn it on (or toggle anytime with 1 click on the floating button)."] = "Pulsa Activar Brillo para encenderlo ahora (o altérnalo en 1 clic desde el botón flotante)."
    L["Start with Collectibles Highlight active immediately"] = "Empezar con Brillo en Recolectables activo ahora"
    L["Tip: if Blizzard shows a yellow Interact Key box, bind an interact key and use it twice (or turn off Game Tutorials) to clear it."] = "Consejo: si ves el aviso amarillo de Tecla de interacción, asigna un atajo y úsalo 2 veces (o desactiva Tutoriales del juego) para quitarlo."
    L["Herbs, ore & chests now light up when you face them!\nLeft-click toggles ON/OFF · Right-click opens options.\nTip: if a yellow Interact Key box appears, bind an Interact Key and use it twice (or uncheck Game Tutorials) to clear it."] = "¡Hierbas, menas y cofres ahora brillan al mirarlos!\nClic izquierdo enciende/apaga · Clic derecho abre opciones.\nConsejo: si ves el aviso amarillo, asigna un atajo de interacción y úsalo 2 veces (o desactiva Tutoriales) para quitarlo."
    L["1-click ON/OFF highlight on nearby herbs, ore & chests (halo + game icon)."] = "Enciende o apaga en 1 clic el brillo y detección en hierbas, menas y cofres."
    L["Use official object detection & icon (herbs, ore & chests)"] = "Usar detección e icono oficiales en hierbas, menas y cofres"
    L["Master opt-in toggle for highlighting nearby herbs, mining veins, fishing pools, and chests using WoW's official near-object detection."] = "Interruptor principal para resaltar hierbas, vetas, bancos de pesca y cofres cercanos con la detección oficial de WoW."
    L["Uses strictly official WoW world-object detection without binding keys or altering quest/enemy outlines. Disabling restores your original settings immediately."] = "Usa estrictamente la detección oficial de objetos de WoW, sin forzar teclas ni quitar contornos de misión o enemigos. Al desactivar se restaura todo al instante."
    L["Help: Official Object Detection"] = "Ayuda: Detección Oficial de Objetos"
    L["Turns on WoW's official forward object detection and game-object icon so herbs, ore veins, fishing pools, and chests illuminate automatically as you approach — without touching quest or enemy outlines."] = "Activa la detección frontal oficial de WoW y el icono de objeto para que hierbas, menas, bancos y cofres brillen al acercarte — sin alterar contornos de misión o enemigos."
    L["If Blizzard shows a yellow Interact Key box, bind an interact key and use it twice (or uncheck Game Tutorials in WoW Options) to clear it permanently."] = "Si Blizzard muestra el cuadro amarillo de Tecla de interacción, asigna un atajo y úsalo 2 veces cerca de un objetivo (o desactiva Tutoriales en Opciones de WoW) para quitarlo para siempre."
    L["Adds a small draggable herb button near your Minimap to toggle Collectible Highlight ON/OFF with 1 click anytime."] = "Muestra un botón móvil cerca del Minimapa para activar o desactivar el Brillo en Recolectables en 1 clic."
    L["Left-click toggles detection & glow ON/OFF; drag to move; right-click to lock or hide."] = "Clic izquierdo enciende/apaga detección y brillo; arrastra para mover; clic derecho fija u oculta."
    L["Helps herbalists, miners, anglers, and treasure hunters spot nearby collectibles using WoW's official forward object detection and game-object icon (without touching quest or enemy outlines)."] = "Ayuda a herboristas, mineros, pescadores y buscadores a localizar recolectables cercanos con la detección frontal oficial de WoW y el icono de objeto (sin tocar contornos de misión o enemigos)."
    L["Enable manually here or confirm the prompt when turning on Find Herbs / Find Minerals / Find Fish on your Minimap. If Blizzard shows a yellow Interact Key box, bind an interact key and use it twice (or uncheck Game Tutorials in WoW Options) to clear it permanently."] = "Actívalo aquí manualmente o confirma al activar Rastrear hierbas / minerales / peces en el Minimapa. Si Blizzard muestra el cuadro amarillo de Tecla de interacción, asigna un atajo y úsalo 2 veces cerca de un objetivo (o desactiva Tutoriales en Opciones de WoW) para quitarlo para siempre."
