    L["Type |cff1d4ed8interact|r in the top search bar and look for |cff15803dInteract With Target|r.\nThen use it 2x so the warning never appears again!"] = "Busca arriba escribiendo |cff1d4ed8interactuar|r y busca el atajo |cff15803dInteractuar con objetivo|r.\n¡Luego úsalo 2x para que el aviso no salga más!"
    L["Watchlist is empty. Type a player name above or click Battle.net to monitor login alerts."] = "Tu Watchlist está vacía. Escribe un nombre arriba o haz clic en Battle.net para seguir inicios de sesión."
    L["No friendly players spotted nearby yet. Target or walk near friendly players to list them."] = "Aún no se detectaron jugadores aliados cerca. Selecciona o acércate a jugadores aliados para listarlos."
    L["No characters match this filter. Try switching chips above or enabling Show Offline."] = "Ningún personaje coincide con este filtro. Cambia los chips arriba o activa Mostrar Desconectados."
    L["Filter listings by preferred realm or group languages."] = "Filtra anuncios según los idiomas preferidos del reino o grupo."
    L["Choose how browse results and solo applicants are sorted."] = "Elige cómo se ordenan los resultados de búsqueda y jugadores en solitario."
    L["Hides dungeon and raid groups whose slots are already full."] = "Oculta grupos de mazmorra y banda que ya tienen las plazas completas."
    L["Filters Browse activities to dungeons and content within your character's recommended level range."] = "Filtra la búsqueda a mazmorras y contenido recomendado para el nivel de tu personaje."
    L["Shows all groups and solo players from Official Blizzard LFG, Global Chat, Guild, Allies, and Friends."] = "Muestra todos los grupos y jugadores en solitario del Buscador Oficial de Blizzard, Chat Global, Hermandad, Aliados y Amigos."
    L["Shows only public groups listed in Blizzard's Official Group Finder."] = "Muestra solo grupos públicos listados en el Buscador Oficial de Blizzard."
    L["Shows groups and solo listings shared by members of your Guild and Allied Guilds."] = "Muestra grupos y anuncios compartidos por miembros de tu Hermandad y Hermandades Aliadas."
    L["Shows only groups and players running SocialCentral [SC] for rich role, class, and status sync."] = "Muestra solo grupos y jugadores que usan SocialCentral [SC] con sincronización completa."
    L["Shows groups and solo listings involving your Friends list or Watchlist players."] = "Muestra grupos y anuncios que incluyen jugadores de tu lista de Amigos o Watchlist."
    L["Shows group calls captured passively from World and Global chat channels."] = "Muestra búsquedas de grupo capturadas pasivamente de los canales de chat Mundial y Global."
    L["Separates formed Groups ([LFM]) and solo Players Looking ([Looking]) into two distinct collapsible sections."] = "Separa Grupos formados ([LFM]) y Jugadores buscando ([Buscando]) en dos secciones plegables."
    L["Clusters listings under collapsible Dungeon and Raid headers with slot summaries."] = "Agrupa anuncios bajo encabezados plegables de Mazmorras y Bandas con resumen de plazas."
    L["Hides dungeon and raid listings for instances where your character already has a saved lockout."] = "Oculta anuncios de mazmorras y bandas en las que tu personaje ya tiene registro guardado."
    L["Automatically hides listings containing Avoid-flagged players or Enemy Guild members."] = "Oculta automáticamente anuncios con jugadores marcados como Evitar o de Hermandades Enemigas."
    L["Displays class icons for current party/raid members on the bottom right of each Browse card."] = "Muestra iconos de clase de los miembros actuales abajo a la derecha de cada tarjeta."
    L["Automatically switches to the SocialCentral Browse tab whenever you publish a new listing on Official Tab 1."] = "Cambia automáticamente a la pestaña Buscar de SocialCentral al publicar un anuncio oficial en la Pestaña 1."
    L["Filters out groups and solo applicants of your own class so you have less competition on armor and class gear drops."] = "Filtra grupos y jugadores de tu misma clase para reducir la competencia por armadura y botín de clase."
    L["Exclude specific classes you prefer not to share loot or party slots with when searching for groups."] = "Excluye clases específicas con las que prefieres no compartir botín ni plazas al buscar grupo."
    L["Click / Right-click: Actions Menu"] = "Clic / Clic derecho: Menú de Acciones"
    L["%d active listings are hidden by your current filters. Open 'Filters »' to adjust or click Reset."] = "%d anuncios activos están ocultos por tus filtros actuales. Abre 'Filtros »' para ajustar o haz clic en Restablecer."
    L["Click to open conversation"] = "Clic para abrir la conversación"
    L["No saved shortcuts yet — fill the fields above and click + Save."] = "Aún no hay atajos guardados — completa los campos arriba y haz clic en + Guardar."
