    L["Adds a same-faction character to your WoW Friends list or sends a Battle.net friend request when you type a BattleTag (Name#1234) or email."] = "Añade un personaje de tu misma facción a tus Amigos de WoW o envía una solicitud de Battle.net al escribir un BattleTag (Nombre#1234) o correo."
    L["Already followed in Watchlist (all alts)."] = "Ya seguido en Watchlist (todos los alts)."
    L["Apply Folder"] = "Aplicar Carpeta"
    L["Asks for confirmation before removing this contact from your Battle.net Friends list."] = "Pide confirmación antes de eliminar este contacto de tu lista de Amigos de Battle.net."
