    L["Battle.net friend request sent."] = "Solicitud de amistad de Battle.net enviada."
    L["Choose Social Folder"] = "Elegir Carpeta Social"
    L["Click any section header to expand/collapse (saved automatically) · Left-click a friend for Quick Inspect · Right-click for Notes, Folders, Battle.net Watchlist & Invites."] = "Haz clic en cualquier encabezado de sección para expandir/contraer (se guarda automáticamente) · Clic izquierdo para Inspección Rápida · Clic derecho para Notas, Carpetas, Watchlist Battle.net e Invitaciones."
    L["Click to clear the active folder filter."] = "Haz clic para limpiar el filtro de carpeta activo."
    L["Click to stop tracking this Battle.net account."] = "Haz clic para dejar de seguir esta cuenta de Battle.net."
    L["Create, rename, or delete custom Social folders and assign multiple WoW friends to a folder in one batch."] = "Crea, renombra o elimina carpetas Sociales personalizadas y asigna varios amigos de WoW a una carpeta en lote."
    L["Delete Folder"] = "Eliminar Carpeta"
    L["Enter a character name (including two-word names) or a BattleTag and click Add. Unavailable during combat."] = "Escribe un nombre de personaje (incluyendo nombres compuestos) o un BattleTag y haz clic en Añadir. No disponible en combate."
