    L["Lets you add any character manually (or your current target), open the searchable Battle.net Friend Picker to track all alts of any Battle.net friend, and run an official single /who query outside combat with cooldown >= 5s."] = "Te permite añadir cualquier personaje manualmente (o tu objetivo actual), abrir el Selector de Amigos Battle.net con búsqueda para seguir todos sus alts y ejecutar una consulta /who oficial fuera de combate con recarga >= 5s."
