    L["Type Name or Name-Surname and click '+ Add', click the Battle.net icon to open the searchable Friend Picker modal, or leave empty while targeting a player."] = "Escribe Nombre o Nombre-Apellido y haz clic en '+ Añadir', haz clic en el icono de Battle.net para abrir el Selector con búsqueda, o déjalo vacío seleccionando a un jugador."
