    L["Adjust dice button visibility, Tabbed/Stacked layout, hiding Blizzard's default roll bar, winner celebration, or jump straight to full Settings."] = "Ajusta la visibilidad del botón de dado, el diseño en Pestañas o Apilado, ocultar la barra oficial de Blizzard, celebración de victoria o abre los Ajustes completos."
