    L["Automatically opens Blizzard's side-by-side equipped item comparison tooltip whenever you hover a drop in the Roll Card or Roll Results window."] = "Abre automáticamente la comparación lado a lado con tu equipo al pasar el cursor sobre un botín en la tarjeta de Tirada o en Resultados."
