    L["Choose 'During dungeon/raid (+3 min after)' (recommended), 'Always visible', or 'Hide button' (still accessible via Quick Access Bar, /sc roll, or the Minimap menu)."] = "Elige 'Durante mazmorra/banda (+3 min después)' (recomendado), 'Siempre visible' u 'Ocultar botón' (sigue accesible desde la Barra de Acceso Rápido, /sc roll o el menú del Minimapa)."
    L["Chooses how multiple simultaneous boss drops are displayed in SocialCentral's active roll window."] = "Define cómo se muestran varios botines simultáneos en la ventana activa de tiradas de SocialCentral."
