    L["Enable the roll window below, pick Tabbed or Stacked layout, and open Roll Results anytime from here, the floating dice button, Quick Access Bar, or /sc roll."] = "Activa la ventana de tiradas abajo, elige Pestañas o Apilado y abre Resultados cuando quieras desde aquí, el botón flotante de dado, la Barra de Acceso Rápido o /sc roll."
