    L["Filter or sort drops on the left, right-click any drop or player for quick actions, switch to Group /roll (1-100) to run Raid Leader roll calls and tie-breakers, or click Configure for quick Loot Roll options."] = "Filtra u ordena los botines a la izquierda, haz clic derecho en cualquier objeto o jugador para acciones rápidas, cambia a /roll en Grupo (1-100) para rondas y desempates del Líder o haz clic en Configurar."
